                    : "Retest charts on Trial/Pro."
                }
                onUpgrade={openUpgrade}
              >
                <BreakdownCharts metrics={result.metrics} />
              </PremiumGate>
            </>
          )}

          <DonateOption />
        </main>

        <UpgradeModal
          open={upgradeOpen}
          onClose={() => setUpgradeOpen(false)}
          plan={plan}
        />
      </div>
    </TooltipProvider>
  );
}

