function DirPill({
  up,
  down,
  tUp,
  tDown,
}: {
  up: number;
  down: number;
  tUp: string;
  tDown: string;
}) {
  const Icon = up >= down ? ArrowUpRight : down > up ? ArrowDownRight : Minus;
  const color =
    up >= down + 5
      ? "text-bull"
      : down >= up + 5
        ? "text-bear"
        : "text-muted-fg";
  return (
    <span className={cn("inline-flex items-center gap-1 font-medium", color)}>
      <Icon className="size-3.5" />
      {tUp} {formatPct(up, 0)} · {tDown} {formatPct(down, 0)}
    </span>
  );
}

