function waitForAlertsHydrated(): Promise<void> {
  const persistApi = usePriceAlerts.persist;
  if (persistApi.hasHydrated()) return Promise.resolve();
  return new Promise((resolve) => {
    const unsub = persistApi.onFinishHydration(() => {
      unsub();
      resolve();
    });
    setTimeout(() => {
      try {
        unsub();
      } catch {
        /* ignore */
      }
      resolve();
    }, 2500);
  });
}

function mergeAlert(a: PriceAlert, b: PriceAlert): PriceAlert {
  const base = normalizeAlert({
    ...a,
    ...b,
    armedProbability:
      coerceArmedProbability(b.armedProbability) ??
      coerceArmedProbability(a.armedProbability),
    armedHistTouch:
      coerceArmedProbability(b.armedHistTouch) ??
      coerceArmedProbability(a.armedHistTouch),
    armedRank: coerceArmedRank(b.armedRank) ?? coerceArmedRank(a.armedRank),
    hitAt: b.hitAt ?? a.hitAt,
    hitPrice: b.hitPrice ?? a.hitPrice,
    abandonedAt: b.abandonedAt ?? a.abandonedAt,
    abandonReason: b.abandonReason ?? a.abandonReason,
    livePrice:
      (b.liveAt ?? 0) >= (a.liveAt ?? 0)
        ? (b.livePrice ?? a.livePrice)
        : (a.livePrice ?? b.livePrice),
    liveAt: Math.max(b.liveAt ?? 0, a.liveAt ?? 0) || undefined,
    active:
      b.active || a.active
        ? b.hitAt || a.hitAt
          ? false
          : b.active || a.active
        : false,
  });
  if (a.hitAt || b.hitAt) {
    const hitSrc = (b.hitAt ?? 0) >= (a.hitAt ?? 0) ? b : a;
    base.active = false;
    base.hitAt = hitSrc.hitAt;
    base.hitPrice = hitSrc.hitPrice;
  }
  if (a.abandonedAt || b.abandonedAt) {
    const ab = (b.abandonedAt ?? 0) >= (a.abandonedAt ?? 0) ? b : a;
    if (!base.hitAt) {
      base.abandonedAt = ab.abandonedAt;
      base.abandonReason = ab.abandonReason;
      if (ab.abandonedAt) base.active = false;
    }
  }
  return base;
}

function mergeLists(remote: PriceAlert[], local: PriceAlert[]): PriceAlert[] {
  const byId = new Map<string, PriceAlert>();
  for (const a of remote.map(normalizeAlert)) byId.set(a.id, a);
  for (const a of local.map(normalizeAlert)) {
    const prev = byId.get(a.id);
    byId.set(a.id, prev ? mergeAlert(prev, a) : a);
  }
  const byKey = new Map<string, PriceAlert>();
  for (const a of byId.values()) {
    const k = `${a.symbol.toUpperCase()}|${a.targetPrice}|${a.tick}`;
    const prev = byKey.get(k);
    if (!prev) byKey.set(k, a);
    else byKey.set(k, mergeAlert(prev, a));
  }
  return [...byKey.values()].sort(
    (a, b) => (b.hitAt ?? b.createdAt) - (a.hitAt ?? a.createdAt),
  );
}

export type AccountSyncParams = {
  symbol: string;
  interval: string;
  range: string;
  windowKey: string;
  onSettings?: (s: {
    lang?: Lang | null;
    lastSymbol?: string | null;
    lastInterval?: string | null;
    lastRange?: string | null;
    lastWindow?: string | null;
  }) => void;
};

export type AccountSyncStatus =
  | "guest"
  | "loading"
  | "synced"
  | "syncing"
  | "error"
  | "local";

export function useAccountSync(params: AccountSyncParams) {
  const { user, isPending } = useCurrentUserState();
  const { lang, setLang } = useI18n();
  const alerts = usePriceAlerts((s) => s.alerts);
  const replaceAll = usePriceAlerts((s) => s.replaceAll);

  const syncedUser = useRef<string | null>(null);
  const skipNextPush = useRef(false);
  const pushTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pullInFlight = useRef(false);
  const lastToastAt = useRef(0);
  const lastFocusPullAt = useRef(0);
  const loginAttempts = useRef(0);
  const langRef = useRef(lang);
  langRef.current = lang;
  const setLangRef = useRef(setLang);
  setLangRef.current = setLang;
  const userRef = useRef(user);
  userRef.current = user;

  const [status, setStatus] = useState<AccountSyncStatus>("guest");
  const statusRef = useRef<AccountSyncStatus>("guest");
  statusRef.current = status;
  const [lastSyncedAt, setLastSyncedAt] = useState<number | null>(null);
  const [alertCountCloud, setAlertCountCloud] = useState<number | null>(null);
  const [accountKey, setAccountKey] = useState<string | null>(null);

  const paramsRef = useRef(params);
  paramsRef.current = params;

  const pullFromServer = useCallback(
    async (opts?: {
      silent?: boolean;
      reason?: "login" | "focus" | "poll" | "manual";
      force?: boolean;
    }) => {
      const u = userRef.current;
      if (!u || u.isDevFallback) return;
      if (pullInFlight.current && !opts?.force) return;

      const reason = opts?.reason ?? "poll";
      const cur = statusRef.current;
      if (!opts?.force && (reason === "focus" || reason === "poll")) {
        if (cur === "synced") {
          const minGap = reason === "focus" ? 10_000 : 30_000;
          if (Date.now() - lastFocusPullAt.current < minGap) return;
        }
      }

      pullInFlight.current = true;
      if (reason === "manual" || reason === "login") setStatus("syncing");

      try {
        await waitForAlertsHydrated();
        // Bearer wait: max ~1.5s (was ~3s)
        for (let i = 0; i < 10 && !getBearerToken(); i++) {
          await new Promise((r) => setTimeout(r, 150));
        }
        if (!getBearerToken()) throw new Error("Unauthorized");

        // 1) Upload THIS device first (server merges — safe)
        const localBefore = usePriceAlerts.getState().alerts;
        if (localBefore.length > 0) {
          try {
            const pre = await pushMyAlerts(localBefore, false);
            if (pre.accountKey) setAccountKey(pre.accountKey);
          } catch (e) {
            console.warn("[account-sync] pre-push", e);
          }
        }

        // 2) Download (2 retries max — faster login)
        let remote: Awaited<ReturnType<typeof fetchMyAlertsDetailed>> | null =
          null;
        let lastErr: unknown = null;
        for (let attempt = 1; attempt <= 2; attempt++) {
          try {
            remote = await fetchMyAlertsDetailed();
            lastErr = null;
            break;
          } catch (e) {
            lastErr = e;
            if (attempt < 2) await new Promise((r) => setTimeout(r, 250));
          }
        }
        if (lastErr || !remote) throw lastErr ?? new Error("list_failed");

        if (remote.accountKey) setAccountKey(remote.accountKey);

        // 3) Merge
        const local = usePriceAlerts.getState().alerts;
        const merged = mergeLists(remote.alerts, local);

        skipNextPush.current = true;
        replaceAll(merged);

        // 4) Push merged
        try {
          const pushRes = await pushMyAlerts(merged, merged.length === 0);
          setAlertCountCloud(
            typeof pushRes.count === "number" ? pushRes.count : merged.length,
          );
          if (pushRes.accountKey) setAccountKey(pushRes.accountKey);
        } catch (e) {
          console.warn("[account-sync] post-merge push", e);
          setAlertCountCloud(merged.length);
        }

        try {
          const settings = await getMySettings();
          const st = settings as {
            lang: Lang | null;
            lastSymbol: string | null;
            lastInterval: string | null;
            lastRange: string | null;
            lastWindow: string | null;
            alertEmail?: string | null;
            emailAlertsEnabled?: boolean;
          };
          if (st.lang === "en" || st.lang === "es")
            setLangRef.current(st.lang);
          if (st.alertEmail) {
            useEmailAlertPrefs.getState().subscribe(st.alertEmail);
            if (!st.emailAlertsEnabled)
              useEmailAlertPrefs.getState().unsubscribe();
            else useEmailAlertPrefs.getState().setEnabled(true);
          }
          paramsRef.current.onSettings?.(st);
        } catch {
          /* optional */
        }

        syncedUser.current = u.id;
        loginAttempts.current = 0;
        lastFocusPullAt.current = Date.now();
        setLastSyncedAt(Date.now());
        setStatus("synced");

        if ((reason === "login" || reason === "manual") && !opts?.silent) {
          const now = Date.now();
          if (now - lastToastAt.current > 5_000) {
            lastToastAt.current = now;
            const n = merged.length;
            toast[n === 0 ? "message" : "success"](
              n === 0
                ? langRef.current === "es"
                  ? "Nube lista · 0 alertas (crea una y se copia a PC y móvil)"
                  : "Cloud ready · 0 alerts (create one — copies to PC & mobile)"
                : langRef.current === "es"
                  ? `Nube · ${n} alertas sincronizadas`
                  : `Cloud · ${n} alerts synced`,
              { duration: 3200, id: "pra-sync-ok" },
            );
          }
        }
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        console.warn("[account-sync] failed", reason, msg);

        if (reason === "login" && loginAttempts.current < 5) {
          loginAttempts.current += 1;
          pullInFlight.current = false;
          setTimeout(() => {
            void pullFromServer({ reason: "login", force: true });
          }, 600 * loginAttempts.current);
          return;
        }

        lastFocusPullAt.current = Date.now();
        setStatus(
          msg === "Unauthorized" || /unauthor/i.test(msg) ? "local" : "error",
        );

        const local = usePriceAlerts.getState().alerts;
        if (local.length > 0 && getBearerToken()) {
          void pushMyAlerts(local, false)
            .then((r) => {
              setAlertCountCloud(r.count ?? local.length);
              if (r.accountKey) setAccountKey(r.accountKey);
            })
            .catch(() => {});
        }

        if (reason === "manual" || reason === "login") {
          toast.error(
            langRef.current === "es"
              ? "Sync incompleta — toca el badge ☁"
              : "Sync incomplete — tap cloud badge",
            { id: "pra-sync-err", duration: 4000 },
          );
        }
      } finally {
        pullInFlight.current = false;
      }
    },
    [replaceAll],
  );

  useEffect(() => {
    if (isPending) {
      setStatus("loading");
      return;
    }
    if (!user || user.isDevFallback) {
      syncedUser.current = null;
      loginAttempts.current = 0;
      setStatus("guest");
      setAlertCountCloud(null);
      setAccountKey(null);
      return;
    }
    if (syncedUser.current === user.id && statusRef.current === "synced") {
      return;
    }
    loginAttempts.current = 0;
    void pullFromServer({ reason: "login" });
  }, [user?.id, user?.isDevFallback, isPending, pullFromServer]);

  useEffect(() => {
    if (!user || user.isDevFallback) return;
    const kick = (force: boolean) => {
      void pullFromServer({ silent: true, reason: "focus", force });
    };
    const onVis = () => {
      if (document.visibilityState === "visible") {
        kick(statusRef.current !== "synced");
      }
    };
    const onShow = () => kick(true);
    document.addEventListener("visibilitychange", onVis);
    window.addEventListener("pageshow", onShow);
    window.addEventListener("focus", onShow);
    const interval = window.setInterval(() => {
      if (document.visibilityState === "visible") {
        void pullFromServer({ silent: true, reason: "poll" });
      }
    }, 25_000);
    return () => {
      document.removeEventListener("visibilitychange", onVis);
      window.removeEventListener("pageshow", onShow);
      window.removeEventListener("focus", onShow);
      window.clearInterval(interval);
    };
  }, [user?.id, user?.isDevFallback, pullFromServer]);

  // Live push — any status except guest (don't wait for "synced")
  useEffect(() => {
    if (!user || user.isDevFallback) return;
    if (!getBearerToken()) return;
    if (status === "guest") return;
    if (skipNextPush.current) {
      skipNextPush.current = false;
      return;
    }
    if (pushTimer.current) clearTimeout(pushTimer.current);
    pushTimer.current = setTimeout(() => {
      const list = usePriceAlerts.getState().alerts;
      void pushMyAlerts(list, list.length === 0)
        .then((res) => {
          setAlertCountCloud(
            typeof res.count === "number" ? res.count : list.length,
          );
          if (res.accountKey) setAccountKey(res.accountKey);
          setLastSyncedAt(Date.now());
          if (statusRef.current !== "error") setStatus("synced");
          syncedUser.current = user.id;
        })
        .catch((e) => {
          console.warn("[account-sync] live push", e);
          setStatus("error");
        });
    }, 300);
    return () => {
      if (pushTimer.current) clearTimeout(pushTimer.current);
    };
  }, [alerts, user?.id, user?.isDevFallback, status]);

  useEffect(() => {
    if (!user || user.isDevFallback) return;
    const tmr = setTimeout(() => {
      const p = paramsRef.current;
      void saveMySettings({
        data: {
          lang,
          lastSymbol: p.symbol,
          lastInterval: p.interval,
          lastRange: p.range,
          lastWindow: p.windowKey,
        },
      }).catch(() => {});
    }, 1200);
    return () => clearTimeout(tmr);
  }, [
    user?.id,
    user?.isDevFallback,
    lang,
    params.symbol,
    params.interval,
    params.range,
    params.windowKey,
  ]);

  const syncNow = useCallback(() => {
    syncedUser.current = null;
    loginAttempts.current = 0;
    return pullFromServer({ reason: "manual", force: true });
  }, [pullFromServer]);

  return {
    status,
    lastSyncedAt,
    alertCountCloud,
    accountKey,
    isCloud: Boolean(user && !user.isDevFallback && status === "synced"),
    wantsCloud: Boolean(user && !user.isDevFallback),
    syncNow,
  };
}

import { useEffect, useRef } from "react";
import { toast } from "sonner";
import { fetchLiveQuote } from "@/lib/analyzer/server";
import { useEmailAlertPrefs } from "@/lib/email-alerts";
import {
  ALERT_TTL_DAYS,
  detectAlertHit,
  evaluateAbandon,
  fireBrowserNotification,
  formatSignedPips,
  pipsSinceEntry,
  usePriceAlerts,
  type AbandonReason,
} from "@/lib/price-alerts";
import { notifyAlertEmail } from "@/lib/user-data/server";
import { formatPrice } from "@/lib/utils";

const POLL_MS = 15_000;
const ARM_GRACE_MS = 10_000;

function abandonCopy(
  reason: AbandonReason,
  lang: "en" | "es",
): { title: string; body: string } {
  if (lang === "es") {
    if (reason === "expired") {
      return {
        title: "Alerta expirada",
        body: `Pasaron ${ALERT_TTL_DAYS} días sin alcanzar el objetivo (el alejamiento no cancela).`,
      };
    }
    // Legacy reasons from old history
    if (reason === "too_far" || reason === "away_timeout") {
      return {
        title: "Alerta detenida (regla antigua)",
        body: "Antes se cancelaba al alejarse; esa regla ya no se usa.",
      };
    }
    return {
      title: "Alerta detenida",
      body: "Seguimiento cerrado.",
    };
  }
  if (reason === "expired") {
    return {
      title: "Alert expired",
      body: `${ALERT_TTL_DAYS} days passed without hitting the target (drifting does not cancel).`,
    };
  }
  if (reason === "too_far" || reason === "away_timeout") {
    return {
      title: "Alert stopped (legacy rule)",
      body: "Older builds cancelled on drift; that rule is disabled.",
    };
  }
  return {
    title: "Alert stopped",
    body: "Watch closed.",
  };
}

/**
 * Polls live quotes. Hits only count after arming.
 * Auto-stop is calendar TTL only (weekly) — never for price distance.
 */
export function useAlertWatcher(lang: "en" | "es") {
  const alerts = usePriceAlerts((s) => s.alerts);
  const markHit = usePriceAlerts((s) => s.markHit);
  const markAbandoned = usePriceAlerts((s) => s.markAbandoned);
  const updateLive = usePriceAlerts((s) => s.updateLive);
  const busy = useRef(false);

  useEffect(() => {
    const active = alerts.filter((a) => a.active);
    if (active.length === 0) return;

    const symbols = [...new Set(active.map((a) => a.symbol))];

    const tickOnce = async () => {
      if (busy.current) return;
      busy.current = true;
      try {
        for (const symbol of symbols) {
          const targets = usePriceAlerts
            .getState()
            .alerts.filter(
              (a) =>
                a.active && a.symbol.toUpperCase() === symbol.toUpperCase(),
            );
          if (targets.length === 0) continue;

          const oldest = Math.min(...targets.map((a) => a.createdAt));

          const quote = (await fetchLiveQuote({
            data: { symbol, sinceMs: oldest },
          })) as {
            last: number;
            barTime: number;
            fetchedAt: number;
            bars: { t: number; o: number; h: number; l: number; c: number }[];
          };

          const now = quote.fetchedAt || Date.now();

          for (const alert of targets) {
            const age = now - alert.createdAt;
            const barsStrict = (quote.bars ?? []).filter(
              (b) => b.t >= alert.createdAt,
            );

            const detection = detectAlertHit(
              alert,
              barsStrict,
              quote.last,
              now,
            );

            const aband = evaluateAbandon(alert, quote.last, now);

            updateLive(alert.id, quote.last, now, {
              hasLeftTarget: detection.leftTarget || !!alert.hasLeftTarget,
              awaySince: aband.awaySince,
            });

            if (age < ARM_GRACE_MS) continue;

            // Hit always wins over TTL expiry
            if (
              detection.hit &&
              !(
                detection.hitAt != null &&
                detection.hitAt > 0 &&
                detection.hitAt < alert.createdAt
              )
            ) {
              const hitAt = Math.max(detection.hitAt || now, alert.createdAt);
              const hitPrice = detection.hitPrice ?? quote.last;
              markHit(alert.id, hitAt, hitPrice);

              const when = new Date(hitAt).toLocaleString(
                lang === "es" ? "es" : "en",
                { dateStyle: "medium", timeStyle: "medium" },
              );
              const priceStr = formatPrice(alert.targetPrice, alert.tick);
              const moved = formatSignedPips(
                pipsSinceEntry({ ...alert, hitPrice }, hitPrice),
              );
              const title =
                lang === "es"
                  ? `Alerta: ${alert.symbol} tocó ${priceStr}`
                  : `Alert: ${alert.symbol} hit ${priceStr}`;
              const body =
                lang === "es"
                  ? `Llegó a las ${when} · movimiento ${moved} pips desde la alerta`
                  : `Reached at ${when} · moved ${moved} pips since alert`;

              toast.success(title, { description: body, duration: 12_000 });
              fireBrowserNotification(title, body);

              const prefs = useEmailAlertPrefs.getState();
              if (prefs.enabled) {
                void notifyAlertEmail({
                  data: {
                    alertId: alert.id,
                    symbol: alert.symbol,
                    targetPrice: alert.targetPrice,
                    hitPrice,
                    hitAt,
                    tick: alert.tick,
                    lang,
                  },
                }).catch(() => {});
              }
              continue;
            }

            if (aband.abandon && aband.reason) {
              markAbandoned(alert.id, now, aband.reason, quote.last);
              const copy = abandonCopy(aband.reason, lang);
              const priceStr = formatPrice(alert.targetPrice, alert.tick);
              toast.message(`${copy.title} · ${alert.symbol}`, {
                description: `${copy.body} · obj ${priceStr}`,
                duration: 10_000,
              });
              fireBrowserNotification(
                `${copy.title} · ${alert.symbol}`,
                copy.body,
              );
            }
          }
        }
      } catch {
        /* next poll */
      } finally {
        busy.current = false;
      }
    };

    const first = window.setTimeout(() => void tickOnce(), 5000);
    const id = window.setInterval(() => void tickOnce(), POLL_MS);
    return () => {
      window.clearTimeout(first);
      window.clearInterval(id);
    };
  }, [alerts, markHit, markAbandoned, updateLive, lang]);
}

import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { AnalysisResult, PriceScenario } from "@/lib/analyzer/types";
import type { PriceAlert } from "@/lib/price-alerts";
import { alertPipSize } from "@/lib/price-alerts";

export type ScenarioSnap = {
  price: number;
  probability: number;
  reachProb: number;
  offsetTicks: number;
  isMagnet: boolean;
};

export type AnalysisSnapshot = {
  id: string;
  at: number;
  symbol: string;
  yahooSymbol: string;
  interval: string;
  range: string;
  windowLabel: string;
  lastPrice: number;
  tick: number;
  trendScore: number;
  trendLabel: string;
  pBull: number;
  pBear: number;
  pSide: number;
  avgRetests: number;
  avgVisits: number;
  avgHotRetests: number;
  pctRetested: number;
  windowsAnalyzed: number;
  levelsTouchedPeak: number;
  topScenarios: ScenarioSnap[];
  topScenarioPrice: number | null;
  topScenarioProb: number | null;
  firstImpulseUp: number;
  firstImpulseDown: number;
  revisitCurrent: number;
  hotLevel: number | null;
  magnetPrice: number | null;
};

type HistState = {
  runs: AnalysisSnapshot[];
  record: (result: AnalysisResult) => void;
  clear: () => void;
};

function snapScenarios(list: PriceScenario[]): ScenarioSnap[] {
  return list.slice(0, 5).map((s) => ({
    price: s.price,
    probability: s.probability,
    reachProb: s.reachProb,
    offsetTicks: s.offsetTicks,
    isMagnet: s.isMagnet,
  }));
}

export function snapshotFromResult(result: AnalysisResult): AnalysisSnapshot {
  const tops = snapScenarios(result.scenarios.scenarios);
  const magnet =
    tops.find((s) => s.isMagnet) ?? tops[0] ?? null;
  const hot = result.metrics.hottestLevels[0]?.level ?? null;
  return {
    id: `${result.symbol}-${result.fetchedAt}`,
    at: result.fetchedAt,
    symbol: result.symbol,
    yahooSymbol: result.yahooSymbol,
    interval: result.interval,
    range: result.range,
    windowLabel: result.windowLabel,
    lastPrice: result.lastPrice,
    tick: result.tick,
    trendScore: result.trend.score,
    trendLabel: result.trend.label,
    pBull: result.trend.pBull,
    pBear: result.trend.pBear,
    pSide: result.trend.pSide,
    avgRetests: result.metrics.avgRetestsPerLevel,
    avgVisits: result.metrics.avgVisitsPerLevel,
    avgHotRetests: result.metrics.avgHotRetests,
    pctRetested: result.metrics.pctLevelsRetested,
    windowsAnalyzed: result.metrics.windowsAnalyzed,
    levelsTouchedPeak: result.metrics.hottestLevels.length
      ? result.metrics.hottestLevels.reduce((s, l) => s + l.visits, 0)
      : 0,
    topScenarios: tops,
    topScenarioPrice: tops[0]?.price ?? null,
    topScenarioProb: tops[0]?.probability ?? null,
    firstImpulseUp: result.scenarios.firstImpulseUp,
    firstImpulseDown: result.scenarios.firstImpulseDown,
    revisitCurrent: result.scenarios.revisitCurrent,
    hotLevel: hot,
    magnetPrice: magnet?.price ?? null,
  };
}

export const useAnalyzerHistory = create<HistState>()(
  persist(
    (set, get) => ({
      runs: [],
      record: (result) => {
        const snap = snapshotFromResult(result);
        const prev = get().runs.filter((r) => r.id !== snap.id);
        set({ runs: [snap, ...prev].slice(0, 50) });
      },
      clear: () => set({ runs: [] }),
    }),
    { name: "pra-analyzer-history-v2" },
  ),
);

/** Recency weight: newest = 1, decays for older runs. */
function recencyWeights(n: number): number[] {
  if (n <= 0) return [];
  const raw = Array.from({ length: n }, (_, i) => Math.pow(0.88, i));
  const sum = raw.reduce((a, b) => a + b, 0);
  return raw.map((w) => w / sum);
}

function wavg(values: number[], weights: number[]): number {
  let s = 0;
  for (let i = 0; i < values.length; i++) s += values[i]! * (weights[i] ?? 0);
  return s;
}

export type HealthBreakdown = {
  retest: number; // 0–100
  coverage: number;
  depth: number;
  scenarios: number;
  consistency: number;
};

export type AnalyzerHealth = {
  runs: number;
  symbols: number;
  avgTrend: number;
  avgRetests: number;
  avgHotRetests: number;
  avgVisits: number;
  avgPctRetested: number;
  avgImpulseUp: number;
  avgImpulseDown: number;
  avgRevisit: number;
  avgTopScenarioProb: number;
  bullishShare: number;
  bearishShare: number;
  sideShare: number;
  lastAt: number | null;
  lastSymbol: string | null;
  healthScore: number;
  healthLabel: "strong" | "ok" | "weak";
  confidence: number; // 0–100 sample confidence
  breakdown: HealthBreakdown;
  /** Per-symbol aggregate for leaderboard */
  bySymbol: {
    symbol: string;
    runs: number;
    avgRetests: number;
    avgTrend: number;
    lastAt: number;
  }[];
};

export function computeAnalyzerHealth(runs: AnalysisSnapshot[]): AnalyzerHealth {
  const emptyBreakdown: HealthBreakdown = {
    retest: 0,
    coverage: 0,
    depth: 0,
    scenarios: 0,
    consistency: 0,
  };

  if (runs.length === 0) {
    return {
      runs: 0,
      symbols: 0,
      avgTrend: 50,
      avgRetests: 0,
      avgHotRetests: 0,
      avgVisits: 0,
      avgPctRetested: 0,
      avgImpulseUp: 50,
      avgImpulseDown: 50,
      avgRevisit: 0,
      avgTopScenarioProb: 0,
      bullishShare: 0,
      bearishShare: 0,
      sideShare: 0,
      lastAt: null,
      lastSymbol: null,
      healthScore: 0,
      healthLabel: "weak",
      confidence: 0,
      breakdown: emptyBreakdown,
      bySymbol: [],
    };
  }

  const n = runs.length;
  const w = recencyWeights(n);

  const avgRetests = wavg(
    runs.map((r) => r.avgRetests),
    w,
  );
  const avgHotRetests = wavg(
    runs.map((r) => r.avgHotRetests ?? r.avgRetests),
    w,
  );
  const avgVisits = wavg(
    runs.map((r) => r.avgVisits),
    w,
  );
  const avgPctRetested = wavg(
    runs.map((r) => r.pctRetested),
    w,
  );
  const avgTrend = wavg(
    runs.map((r) => r.trendScore),
    w,
  );
  const avgImpulseUp = wavg(
    runs.map((r) => r.firstImpulseUp),
    w,
  );
  const avgImpulseDown = wavg(
    runs.map((r) => r.firstImpulseDown ?? 100 - r.firstImpulseUp),
    w,
  );
  const avgRevisit = wavg(
    runs.map((r) => r.revisitCurrent),
    w,
  );
  const avgTopScenarioProb = wavg(
    runs.map((r) => r.topScenarioProb ?? 0),
    w,
  );
  const avgWindows = wavg(
    runs.map((r) => r.windowsAnalyzed),
    w,
  );

  let bull = 0,
    bear = 0,
    side = 0;
  for (const r of runs) {
    if (r.trendLabel === "alcista") bull++;
    else if (r.trendLabel === "bajista") bear++;
    else side++;
  }

  // --- Sub-scores 0–100 ---
  // Retest activity: typical good retests ~1.5–3
  const retest = Math.min(
    100,
    avgRetests * 22 + avgHotRetests * 8,
  );
  // Coverage of levels that retest
  const coverage = Math.min(100, avgPctRetested * 1.05);
  // Sample depth from windows
  const depth = Math.min(100, Math.log10(Math.max(1, avgWindows)) * 45 + avgWindows * 0.8);
  // Scenario clarity: peaked top scenario is better than flat 20/20/20
  const scenarios = Math.min(100, Math.max(0, (avgTopScenarioProb - 15) * 2.2));
  // Consistency: lower trend volatility across runs + revisit rate
  const trendVar =
    n > 1
      ? runs.reduce((s, r) => s + Math.pow(r.trendScore - avgTrend, 2), 0) / n
      : 0;
  const consistency = Math.min(
    100,
    Math.max(0, 100 - Math.sqrt(trendVar) * 1.4) * 0.55 +
      Math.min(100, avgRevisit) * 0.45,
  );

  const breakdown: HealthBreakdown = {
    retest: Math.round(retest),
    coverage: Math.round(coverage),
    depth: Math.round(depth),
    scenarios: Math.round(scenarios),
    consistency: Math.round(consistency),
  };

  const healthScore = Math.round(
    retest * 0.28 +
      coverage * 0.22 +
      depth * 0.18 +
      scenarios * 0.16 +
      consistency * 0.16,
  );

  // Confidence grows with runs + unique symbols (caps at 100)
  const symbols = new Set(runs.map((r) => r.symbol.toUpperCase())).size;
  const confidence = Math.min(
    100,
    Math.round(n * 12 + symbols * 8 + Math.min(20, avgWindows / 2)),
  );

  const healthLabel: AnalyzerHealth["healthLabel"] =
    healthScore >= 68 && confidence >= 25
      ? "strong"
      : healthScore >= 42
        ? "ok"
        : "weak";

  // Symbol leaderboard
  const map = new Map<
    string,
    { runs: number; retests: number; trend: number; lastAt: number }
  >();
  for (const r of runs) {
    const k = r.symbol.toUpperCase();
    const cur = map.get(k) ?? { runs: 0, retests: 0, trend: 0, lastAt: 0 };
    cur.runs += 1;
    cur.retests += r.avgRetests;
    cur.trend += r.trendScore;
    cur.lastAt = Math.max(cur.lastAt, r.at);
    map.set(k, cur);
  }
  const bySymbol = [...map.entries()]
    .map(([symbol, v]) => ({
      symbol,
      runs: v.runs,
      avgRetests: v.retests / v.runs,
      avgTrend: v.trend / v.runs,
      lastAt: v.lastAt,
    }))
    .sort((a, b) => b.avgRetests - a.avgRetests || b.runs - a.runs)
    .slice(0, 6);

  return {
    runs: n,
    symbols,
    avgTrend,
    avgRetests,
    avgHotRetests,
    avgVisits,
    avgPctRetested,
    avgImpulseUp,
    avgImpulseDown,
    avgRevisit,
    avgTopScenarioProb,
    bullishShare: (bull / n) * 100,
    bearishShare: (bear / n) * 100,
    sideShare: (side / n) * 100,
    lastAt: runs[0]?.at ?? null,
    lastSymbol: runs[0]?.symbol ?? null,
    healthScore,
    healthLabel,
    confidence,
    breakdown,
    bySymbol,
  };
}

export type AlertPerformance = {
  total: number;
  active: number;
  hit: number;
  abandoned: number;
  stopped: number;
  /** hit / (hit + abandoned + stopped) when closed > 0 */
  hitRate: number | null;
  avgTimeToHitMs: number | null;
  medianTimeToHitMs: number | null;
  /** Sum of |entry→hit| pips on reached alerts only */
  reachedVolumePips: number;
  abandonedTooFar: number;
  abandonedNoReturn: number;
  abandonedExpired: number;
};

export function computeAlertPerformance(alerts: PriceAlert[]): AlertPerformance {
  const active = alerts.filter((a) => a.active);
  const hit = alerts.filter((a) => a.hitAt);
  const abandoned = alerts.filter((a) => a.abandonedAt && !a.hitAt);
  const stopped = alerts.filter(
    (a) => !a.active && !a.hitAt && !a.abandonedAt,
  );

  const times = hit
    .map((a) =>
      a.hitAt != null && a.createdAt != null ? a.hitAt - a.createdAt : null,
    )
    .filter((x): x is number => x != null && x >= 0)
    .sort((a, b) => a - b);

  const avgMs =
    times.length > 0
      ? times.reduce((s, x) => s + x, 0) / times.length
      : null;
  const medianMs =
    times.length > 0
      ? times[Math.floor(times.length / 2)]!
      : null;

  let reachedVolumePips = 0;
  for (const a of hit) {
    const hitPx = a.hitPrice ?? a.livePrice;
    if (hitPx == null || !Number.isFinite(a.entryPrice)) continue;
    const ps = alertPipSize(a.yahooSymbol, a.tick);
    if (!(ps > 0)) continue;
    reachedVolumePips += Math.abs(hitPx - a.entryPrice) / ps;
  }

  const closed = hit.length + abandoned.length + stopped.length;
  const hitRate = closed > 0 ? (hit.length / closed) * 100 : null;

  return {
    total: alerts.length,
    active: active.length,
    hit: hit.length,
    abandoned: abandoned.length,
    stopped: stopped.length,
    hitRate,
    avgTimeToHitMs: avgMs,
    medianTimeToHitMs: medianMs,
    reachedVolumePips,
    abandonedTooFar: abandoned.filter((a) => a.abandonReason === "too_far")
      .length,
    abandonedNoReturn: abandoned.filter(
      (a) => a.abandonReason === "away_timeout",
    ).length,
    abandonedExpired: abandoned.filter((a) => a.abandonReason === "expired")
      .length,
  };
}

/**
 * Alpha Vantage client (server-only).
 * Free keys: ~25 req/day + 1/sec — use sparingly with long TTL cache.
 * Never import this from client components.
 */
import type { OHLCBar } from "./types";
import { resolveYahooSymbol } from "./symbols";

const BASE = "https://www.alphavantage.co/query";

function apiKey(): string | null {
  const k = process.env.ALPHA_VANTAGE_API_KEY?.trim();
  if (!k || process.env.ALPHA_VANTAGE_ENABLED === "false") return null;
  return k;
}

export function isAlphaVantageEnabled(): boolean {
  return !!apiKey();
}

/** Soft daily budget (free default 25). Leave headroom. */
const DAILY_BUDGET = Number(process.env.ALPHA_VANTAGE_DAILY_BUDGET || 20);
const MIN_GAP_MS = 1200;
const CACHE_TTL_MS = 5 * 60_000; // 5 min — stretch free quota

type CacheEntry = { at: number; json: unknown };
const cache = new Map<string, CacheEntry>();
let lastCallAt = 0;
let dayKey = "";
let dayCount = 0;

function todayKey() {
  return new Date().toISOString().slice(0, 10);
}

function budgetLeft(): number {
  const d = todayKey();
  if (d !== dayKey) {
    dayKey = d;
    dayCount = 0;
  }
  return Math.max(0, DAILY_BUDGET - dayCount);
}

async function avFetch(params: Record<string, string>): Promise<unknown | null> {
  const key = apiKey();
  if (!key) return null;
  if (budgetLeft() <= 0) return null;

  const qs = new URLSearchParams({ ...params, apikey: key });
  const cacheKey = qs.toString().replace(/apikey=[^&]+/, "apikey=***");
  const hit = cache.get(cacheKey);
  if (hit && Date.now() - hit.at < CACHE_TTL_MS) return hit.json;

  const wait = MIN_GAP_MS - (Date.now() - lastCallAt);
  if (wait > 0) await new Promise((r) => setTimeout(r, wait));

  lastCallAt = Date.now();
  dayCount += 1;

  try {
    const res = await fetch(`${BASE}?${qs.toString()}`, {
      headers: { Accept: "application/json" },
    });
    if (!res.ok) return null;
    const json = (await res.json()) as Record<string, unknown>;
    if (json.Note || json.Information) {
      // rate limited — don't cache as success forever
      console.warn("[alpha-vantage] rate limit / info:", json.Note || json.Information);
      return null;
    }
    if (json["Error Message"]) {
      console.warn("[alpha-vantage] error:", json["Error Message"]);
      return null;
    }
    cache.set(cacheKey, { at: Date.now(), json });
    return json;
  } catch (e) {
    console.warn("[alpha-vantage] fetch failed", e);
    return null;
  }
}

function parseSeries(
  series: Record<string, Record<string, string>> | undefined,
): OHLCBar[] {
  if (!series) return [];
  const bars: OHLCBar[] = [];
  for (const [ts, row] of Object.entries(series)) {
    const o = Number(row["1. open"] ?? row["1a. open (USD)"]);
    const h = Number(row["2. high"] ?? row["2a. high (USD)"]);
    const l = Number(row["3. low"] ?? row["3a. low (USD)"]);
    const c = Number(row["4. close"] ?? row["4a. close (USD)"]);
    const v = Number(row["5. volume"] ?? row["5. volume"] ?? 0);
    if (![o, h, l, c].every(Number.isFinite)) continue;
    const t = Date.parse(ts.includes("T") ? ts : ts.replace(" ", "T") + "Z");
    if (!Number.isFinite(t)) continue;
    bars.push({ t, o, h, l, c, v: Number.isFinite(v) ? v : 0 });
  }
  bars.sort((a, b) => a.t - b.t);
  return bars;
}

/** Map app interval → AV interval string */
function avInterval(interval: string): string | null {
  if (interval === "1m") return "1min";
  if (interval === "5m") return "5min";
  if (interval === "15m") return "15min";
  if (interval === "1h" || interval === "60m") return "60min";
  return null; // daily handled separately
}

type FxPair = { from: string; to: string };

function asFxPair(yahooOrApp: string): FxPair | null {
  const s = yahooOrApp.toUpperCase().replace("=X", "");
  if (s.length === 6 && /^[A-Z]{6}$/.test(s)) {
    return { from: s.slice(0, 3), to: s.slice(3) };
  }
  return null;
}

function isCrypto(yahoo: string): { from: string; to: string } | null {
  const s = yahoo.toUpperCase();
  if (s === "BTC-USD" || s === "BTCUSD") return { from: "BTC", to: "USD" };
  if (s === "ETH-USD" || s === "ETHUSD") return { from: "ETH", to: "USD" };
  if (s === "ETH-BTC") return { from: "ETH", to: "BTC" };
  return null;
}

/**
 * Live last price from Alpha Vantage (spot FX, equity quote, crypto).
 * Returns null if disabled / budget / unsupported.
 */
export async function fetchAvLivePrice(symbol: string): Promise<{
  price: number;
  source: string;
} | null> {
  if (!apiKey()) return null;
  const yahoo = resolveYahooSymbol(symbol);

  // Spot FX
  const fx = asFxPair(yahoo.endsWith("=X") ? yahoo : symbol);
  if (fx || (yahoo.endsWith("=X") && asFxPair(yahoo))) {
    const pair = fx ?? asFxPair(yahoo)!;
    const json = (await avFetch({
      function: "CURRENCY_EXCHANGE_RATE",
      from_currency: pair.from,
      to_currency: pair.to,
    })) as Record<string, Record<string, string>> | null;
    const row = json?.["Realtime Currency Exchange Rate"];
    const price = Number(row?.["5. Exchange Rate"]);
    if (Number.isFinite(price) && price > 0) {
      return { price, source: `av-fx:${pair.from}${pair.to}` };
    }
  }

  // Crypto
  const cry = isCrypto(yahoo);
  if (cry) {
    const json = (await avFetch({
      function: "CURRENCY_EXCHANGE_RATE",
      from_currency: cry.from,
      to_currency: cry.to,
    })) as Record<string, Record<string, string>> | null;
    const row = json?.["Realtime Currency Exchange Rate"];
    const price = Number(row?.["5. Exchange Rate"]);
    if (Number.isFinite(price) && price > 0) {
      return { price, source: `av-crypto:${cry.from}${cry.to}` };
    }
  }

  // Equities / ETFs / futures tickers AV may know
  // Skip pure futures like GC=F — AV free often wrong/unsupported
  if (!yahoo.includes("=") && !yahoo.startsWith("^")) {
    const json = (await avFetch({
      function: "GLOBAL_QUOTE",
      symbol: yahoo,
    })) as Record<string, Record<string, string>> | null;
    const q = json?.["Global Quote"];
    const price = Number(q?.["05. price"]);
    if (Number.isFinite(price) && price > 0) {
      return { price, source: `av-quote:${yahoo}` };
    }
  }

  return null;
}

/**
 * Optional OHLC from AV for FX (spot path). Limited history on free tier.
 */
export async function fetchAvFxBars(
  symbol: string,
  interval: string,
): Promise<{ bars: OHLCBar[]; source: string } | null> {
  if (!apiKey()) return null;
  const yahoo = resolveYahooSymbol(symbol);
  const pair = asFxPair(yahoo.endsWith("=X") ? yahoo : symbol) ?? asFxPair(yahoo);
  if (!pair) return null;

  const avInt = avInterval(interval);
  if (avInt) {
    const json = (await avFetch({
      function: "FX_INTRADAY",
      from_symbol: pair.from,
      to_symbol: pair.to,
      interval: avInt,
      outputsize: "full",
    })) as Record<string, Record<string, Record<string, string>>> | null;
    const key = Object.keys(json || {}).find((k) =>
      k.startsWith("Time Series FX"),
    );
    const bars = parseSeries(key ? json![key] : undefined);
    if (bars.length >= 10) {
      return { bars, source: `av-fx-intra:${pair.from}${pair.to}` };
    }
  }

  // Daily fallback
  const json = (await avFetch({
    function: "FX_DAILY",
    from_symbol: pair.from,
    to_symbol: pair.to,
    outputsize: "compact",
  })) as Record<string, Record<string, Record<string, string>>> | null;
  const key = Object.keys(json || {}).find((k) =>
    k.startsWith("Time Series FX"),
  );
  const bars = parseSeries(key ? json![key] : undefined);
  if (bars.length >= 10) {
    return { bars, source: `av-fx-daily:${pair.from}${pair.to}` };
  }
  return null;
}

export function avStatus(): {
  enabled: boolean;
  budgetLeft: number;
  dailyBudget: number;
} {
  return {
    enabled: isAlphaVantageEnabled(),
    budgetLeft: budgetLeft(),
    dailyBudget: DAILY_BUDGET,
  };
}

import { allowsPriceDecimals, detectTick } from "./symbols";
import {
  minScenarioOffsetTicks,
  pipSize as scenarioPipSize,
} from "./pips";
import type {
  AggregateMetrics,
  AnalysisResult,
  LevelStats,
  OHLCBar,
  PathPoint,
  PriceScenario,
  RecentRevisit,
  ScenarioBundle,
  TrendResult,
  WindowStats,
} from "./types";

export function discretize(price: number, tick: number): number {
  if (tick <= 0) return price;
  const n = Math.round(price / tick) * tick;
  const decimals = tick >= 1 ? 0 : Math.min(10, Math.max(0, Math.ceil(-Math.log10(tick)) + 1));
  return Number(n.toFixed(decimals));
}

/**
 * Reconstruct intra-bar path so high/low touches are not lost.
 * Bullish: open → low → high → close
 * Bearish: open → high → low → close
 *
 * Timestamps are spread inside each bar so leave/return gaps are measurable.
 */
export function reconstructPath(bars: OHLCBar[], tick: number): PathPoint[] {
  const out: PathPoint[] = [];
  for (let bi = 0; bi < bars.length; bi++) {
    const bar = bars[bi]!;
    const sequence =
      bar.c >= bar.o
        ? [bar.o, bar.l, bar.h, bar.c]
        : [bar.o, bar.h, bar.l, bar.c];

    const nextT = bars[bi + 1]?.t;
    const barLen =
      nextT != null && nextT > bar.t
        ? nextT - bar.t
        : bi > 0
          ? Math.max(60_000, bar.t - bars[bi - 1]!.t)
          : 60_000;

    const seq: number[] = [];
    for (const p of sequence) {
      if (seq.length === 0 || Math.abs(p - seq[seq.length - 1]!) >= tick * 0.25) {
        seq.push(p);
      }
    }
    if (seq.length === 0) continue;

    for (let k = 0; k < seq.length; k++) {
      const p = seq[k]!;
      const frac = seq.length === 1 ? 0 : k / seq.length;
      const t = bar.t + Math.floor(frac * Math.max(0, barLen - 1));
      out.push({ t, price: p, level: discretize(p, tick) });
    }
  }
  return out;
}

export function countVisits(path: PathPoint[]): Map<number, number> {
  const visits = new Map<number, number>();
  if (path.length === 0) return visits;

  let current = path[0]!.level;
  visits.set(current, 1);

  for (let i = 1; i < path.length; i++) {
    const lv = path[i]!.level;
    if (lv !== current) {
      visits.set(lv, (visits.get(lv) ?? 0) + 1);
      current = lv;
    }
  }
  return visits;
}

function median(nums: number[]): number {
  if (nums.length === 0) return 0;
  const a = [...nums].sort((x, y) => x - y);
  const m = Math.floor(a.length / 2);
  return a.length % 2 ? a[m]! : (a[m - 1]! + a[m]!) / 2;
}

function estimateBarMs(path: PathPoint[]): number {
  const times: number[] = [];
  let prev = -1;
  for (const p of path) {
    if (p.t !== prev) {
      times.push(p.t);
      prev = p.t;
    }
  }
  const gaps: number[] = [];
  for (let i = 1; i < times.length; i++) {
    const g = times[i]! - times[i - 1]!;
    if (g > 0 && g < 7 * 24 * 3600_000) gaps.push(g);
  }
  const med = median(gaps);
  return med > 0 ? med : 5 * 60_000;
}

/**
 * Meaningful retests only:
 * - Build contiguous presence segments per level
 * - On re-entry, timeAway = enterNow − leavePrevious
 * - Drop micro-chops shorter than ~2 bars (min 15m)
 * Newest `limit` events first.
 */
export function findRecentRevisits(
  path: PathPoint[],
  limit = 5,
  minAwayMsOverride?: number,
): RecentRevisit[] {
  if (path.length < 2) return [];

  const barMs = estimateBarMs(path);
  const minAwayMs =
    minAwayMsOverride ?? Math.max(15 * 60_000, Math.min(2 * barMs, 2 * 60 * 60_000));

  type Seg = { level: number; enterT: number; leaveT: number; visitNumber: number };
  const visitCount = new Map<number, number>();

  let curLevel = path[0]!.level;
  let enterT = path[0]!.t;
  visitCount.set(curLevel, 1);

  const segments: Seg[] = [];

  for (let i = 1; i < path.length; i++) {
    const pt = path[i]!;
    if (pt.level === curLevel) continue;

    const leaveT = path[i - 1]!.t;
    segments.push({
      level: curLevel,
      enterT,
      leaveT: Math.max(leaveT, enterT),
      visitNumber: visitCount.get(curLevel) ?? 1,
    });

    const next = pt.level;
    visitCount.set(next, (visitCount.get(next) ?? 0) + 1);
    curLevel = next;
    enterT = pt.t;
  }
  segments.push({
    level: curLevel,
    enterT,
    leaveT: path[path.length - 1]!.t,
    visitNumber: visitCount.get(curLevel) ?? 1,
  });

  const lastSegByLevel = new Map<number, Seg>();
  const events: RecentRevisit[] = [];

  for (const seg of segments) {
    const prev = lastSegByLevel.get(seg.level);
    if (prev && seg.visitNumber > 1) {
      const timeAwayMs = Math.max(0, seg.enterT - prev.leaveT);
      if (timeAwayMs >= minAwayMs - 1) {
        events.push({
          level: seg.level,
          visitNumber: seg.visitNumber,
          at: seg.enterT,
          leftAt: prev.leaveT,
          timeAwayMs,
        });
      }
    }
    lastSegByLevel.set(seg.level, seg);
  }

  return events.slice(-limit).reverse();
}

function levelStatsFromVisits(visits: Map<number, number>): LevelStats[] {
  return [...visits.entries()]
    .map(([level, v]) => ({
      level,
      visits: v,
      retests: Math.max(0, v - 1),
    }))
    .sort((a, b) => b.visits - a.visits || a.level - b.level);
}

export function sliceWindows(
  path: PathPoint[],
  windowMs: number,
): { start: number; end: number; points: PathPoint[] }[] {
  if (path.length === 0) return [];
  const t0 = path[0]!.t;
  const t1 = path[path.length - 1]!.t;
  const windows: { start: number; end: number; points: PathPoint[] }[] = [];

  let start = t0;
  while (start + windowMs * 0.5 <= t1) {
    const end = start + windowMs;
    const points = path.filter((p) => p.t >= start && p.t < end);
    if (points.length >= 4) {
      windows.push({ start, end, points });
    }
    start = end;
  }
  return windows;
}

export function analyzeWindows(path: PathPoint[], windowMs: number): WindowStats[] {
  const slices = sliceWindows(path, windowMs);
  return slices.map((w) => {
    const visits = countVisits(w.points);
    const stats = levelStatsFromVisits(visits);
    const n = stats.length || 1;
    const avgVisits = stats.reduce((s, x) => s + x.visits, 0) / n;
    const avgRetests = stats.reduce((s, x) => s + x.retests, 0) / n;
    const hot = stats[0] ?? null;
    const retested = stats.filter((x) => x.retests > 0).length;
    const mid = new Date((w.start + w.end) / 2);
    return {
      start: w.start,
      end: w.end,
      levelStats: stats,
      avgVisits,
      avgRetests,
      hotLevel: hot?.level ?? null,
      hotRetests: hot?.retests ?? 0,
      pctRetested: (retested / n) * 100,
      levelsTouched: stats.length,
      hour: mid.getUTCHours(),
      dayOfWeek: mid.getUTCDay(),
    };
  });
}

export function aggregateMetrics(windows: WindowStats[]): AggregateMetrics {
  if (windows.length === 0) {
    return {
      avgVisitsPerLevel: 0,
      avgRetestsPerLevel: 0,
      avgHotRetests: 0,
      pctLevelsRetested: 0,
      windowsAnalyzed: 0,
      bestWindow: null,
      hottestLevels: [],
      byHour: [],
      byDay: [],
    };
  }

  const avgVisitsPerLevel =
    windows.reduce((s, w) => s + w.avgVisits, 0) / windows.length;
  const avgRetestsPerLevel =
    windows.reduce((s, w) => s + w.avgRetests, 0) / windows.length;
  const avgHotRetests =
    windows.reduce((s, w) => s + w.hotRetests, 0) / windows.length;
  const pctLevelsRetested =
    windows.reduce((s, w) => s + w.pctRetested, 0) / windows.length;

  let bestWindow = windows[0]!;
  for (const w of windows) {
    if (w.avgRetests > bestWindow.avgRetests) bestWindow = w;
  }

  const global = new Map<number, { visits: number; retests: number }>();
  for (const w of windows) {
    for (const ls of w.levelStats) {
      const g = global.get(ls.level) ?? { visits: 0, retests: 0 };
      g.visits += ls.visits;
      g.retests += ls.retests;
      global.set(ls.level, g);
    }
  }
  const hottestLevels = [...global.entries()]
    .map(([level, v]) => ({
      level,
      visits: v.visits,
      retests: v.retests,
    }))
    .sort((a, b) => b.visits - a.visits)
    .slice(0, 12);

  const hourMap = new Map<number, { visits: number; retests: number; count: number }>();
  const dayMap = new Map<number, { visits: number; retests: number; count: number }>();
  for (const w of windows) {
    const h = hourMap.get(w.hour) ?? { visits: 0, retests: 0, count: 0 };
    h.visits += w.avgVisits;
    h.retests += w.avgRetests;
    h.count += 1;
    hourMap.set(w.hour, h);

    const d = dayMap.get(w.dayOfWeek) ?? { visits: 0, retests: 0, count: 0 };
    d.visits += w.avgVisits;
    d.retests += w.avgRetests;
    d.count += 1;
    dayMap.set(w.dayOfWeek, d);
  }

  const byHour = [...hourMap.entries()]
    .map(([hour, v]) => ({
      hour,
      avgVisits: v.visits / v.count,
      avgRetests: v.retests / v.count,
      count: v.count,
    }))
    .sort((a, b) => a.hour - b.hour);

  const byDay = [...dayMap.entries()]
    .map(([day, v]) => ({
      day,
      avgVisits: v.visits / v.count,
      avgRetests: v.retests / v.count,
      count: v.count,
    }))
    .sort((a, b) => a.day - b.day);

  return {
    avgVisitsPerLevel,
    avgRetestsPerLevel,
    avgHotRetests,
    pctLevelsRetested,
    windowsAnalyzed: windows.length,
    bestWindow,
    hottestLevels,
    byHour,
    byDay,
  };
}

function clamp01(x: number) {
  return Math.max(0, Math.min(1, x));
}

export function computeTrend(
  bars: OHLCBar[],
  path: PathPoint[],
  tick: number,
): TrendResult {
  if (bars.length < 5) {
    return {
      score: 50,
      pBull: 33,
      pBear: 33,
      pSide: 34,
      label: "lateral",
      factors: [],
    };
  }

  const last = bars[bars.length - 1]!.c;
  const first = bars[0]!.c;
  const ret = (last - first) / (Math.abs(first) || 1);

  const n = Math.min(20, bars.length);
  const recent = bars.slice(-n);
  const older = bars.slice(Math.max(0, bars.length - 2 * n), bars.length - n);
  const recentMid = recent.reduce((s, b) => s + b.c, 0) / recent.length;
  const olderMid =
    older.length > 0
      ? older.reduce((s, b) => s + b.c, 0) / older.length
      : recentMid;
  const momentum = (recentMid - olderMid) / (Math.abs(olderMid) || 1);

  let upStruct = 0;
  let downStruct = 0;
  const step = Math.max(1, Math.floor(bars.length / 12));
  const piv: number[] = [];
  for (let i = step; i < bars.length; i += step) piv.push(bars[i]!.c);
  for (let i = 2; i < piv.length; i++) {
    if (piv[i]! > piv[i - 1]! && piv[i - 1]! > piv[i - 2]!) upStruct++;
    if (piv[i]! < piv[i - 1]! && piv[i - 1]! < piv[i - 2]!) downStruct++;
  }
  const structure =
    upStruct + downStruct > 0
      ? (upStruct - downStruct) / (upStruct + downStruct)
      : 0;

  const prices = path.map((p) => p.level);
  const mid =
    prices.length > 0
      ? prices.reduce((a, b) => a + b, 0) / prices.length
      : last;
  let above = 0;
  let below = 0;
  for (const p of path) {
    if (p.level >= mid) above++;
    else below++;
  }
  const asymmetry =
    above + below > 0 ? (above - below) / (above + below) : 0;

  const range = Math.max(...bars.map((b) => b.h)) - Math.min(...bars.map((b) => b.l));
  const atrLike =
    bars.reduce((s, b) => s + (b.h - b.l), 0) / bars.length / (Math.abs(last) || 1);
  const rangePct = range / (Math.abs(last) || 1);
  const compression = 1 - clamp01(rangePct / (atrLike * 8 + 1e-9));

  const factors = [
    { name: "Retorno", value: Math.tanh(ret * 40), weight: 0.28 },
    { name: "Momentum", value: Math.tanh(momentum * 30), weight: 0.24 },
    { name: "Estructura HH/HL", value: clamp01((structure + 1) / 2) * 2 - 1, weight: 0.22 },
    { name: "Asimetría visitas", value: asymmetry, weight: 0.16 },
    { name: "Rango (lateralidad)", value: -(compression * 2 - 1) * 0.5, weight: 0.1 },
  ];

  let raw = 0;
  let wSum = 0;
  for (const f of factors) {
    raw += f.value * f.weight;
    wSum += f.weight;
  }
  const directional = raw / (wSum || 1);
  const score = Math.round(clamp01((directional + 1) / 2) * 100);

  const bullEnergy = Math.exp(directional * 2.2);
  const bearEnergy = Math.exp(-directional * 2.2);
  const sideEnergy = Math.exp((1 - Math.abs(directional)) * 2.5 + compression * 1.5);
  const z = bullEnergy + bearEnergy + sideEnergy;
  const pBull = (bullEnergy / z) * 100;
  const pBear = (bearEnergy / z) * 100;
  const pSide = (sideEnergy / z) * 100;

  let label: TrendResult["label"] = "lateral";
  if (pBull >= pBear && pBull >= pSide && score >= 55) label = "alcista";
  else if (pBear >= pBull && pBear >= pSide && score <= 45) label = "bajista";

  void tick;

  return { score, pBull, pBear, pSide, label, factors };
}

export { minScenarioOffsetTicks } from "./pips";


export function computeScenarios(
  path: PathPoint[],
  windowMs: number,
  tick: number,
  maxScenarios = 5,
  yahooSymbol = "EURUSD=X",
): ScenarioBundle {
  const minOff = minScenarioOffsetTicks(yahooSymbol, tick);

  if (path.length < 20) {
    const last = path[path.length - 1];
    if (!last) {
      return {
        scenarios: [],
        firstImpulseUp: 50,
        firstImpulseDown: 50,
        revisitCurrent: 0,
        currentPrice: 0,
        currentLevel: 0,
        horizonLabel: formatHorizon(windowMs),
      };
    }
    // Fallback: synthetic ±min levels (never current)
    const scenarios: PriceScenario[] = [
      {
        price: discretize(last.level + minOff * tick, tick),
        offsetTicks: minOff,
        probability: 50,
        histTouch: 50,
        reachProb: 50,
        isMagnet: false,
      },
      {
        price: discretize(last.level - minOff * tick, tick),
        offsetTicks: -minOff,
        probability: 50,
        histTouch: 50,
        reachProb: 50,
        isMagnet: false,
      },
    ];
    return {
      scenarios,
      firstImpulseUp: 50,
      firstImpulseDown: 50,
      revisitCurrent: 0,
      currentPrice: last.price,
      currentLevel: last.level,
      horizonLabel: formatHorizon(windowMs),
    };
  }

  const tEnd = path[path.length - 1]!.t;
  const tStart = path[0]!.t;
  const span = Math.max(1, tEnd - tStart);
  const stride = Math.max(1, Math.floor(path.length / 400));

  const touchWeight = new Map<number, number>();
  const reachCount = new Map<number, number>();
  const magnetWeight = new Map<number, number>();
  let sampleN = 0;
  let impulseUp = 0;
  let impulseDown = 0;
  let impulseN = 0;
  let revisit = 0;
  let leaveN = 0;

  for (let i = 0; i < path.length - 5; i += stride) {
    const origin = path[i]!;
    const winEnd = origin.t + windowMs;
    if (winEnd > tEnd) break;

    const age = (tEnd - origin.t) / span;
    const w = Math.exp(-2.5 * age);

    const visited = new Set<number>();
    const visitCounts = new Map<number, number>();
    let prevLevel = origin.level;
    visitCounts.set(prevLevel, 1);

    let left = false;
    let firstDir: -1 | 0 | 1 = 0;
    let returned = false;

    for (let j = i + 1; j < path.length; j++) {
      const p = path[j]!;
      if (p.t > winEnd) break;

      const off = Math.round((p.level - origin.level) / tick);
      visited.add(off);

      if (p.level !== prevLevel) {
        visitCounts.set(off, (visitCounts.get(off) ?? 0) + 1);
        if (!left && p.level !== origin.level) {
          left = true;
          firstDir = p.level > origin.level ? 1 : -1;
        }
        if (left && p.level === origin.level) returned = true;
        prevLevel = p.level;
      }
    }

    sampleN += 1;
    for (const off of visited) {
      touchWeight.set(off, (touchWeight.get(off) ?? 0) + w);
      reachCount.set(off, (reachCount.get(off) ?? 0) + 1);
    }

    let magnetOff = 0;
    let magnetV = -1;
    for (const [off, v] of visitCounts) {
      if (v > magnetV || (v === magnetV && Math.abs(off) < Math.abs(magnetOff))) {
        magnetV = v;
        magnetOff = off;
      }
    }
    // Prefer magnets that are not the origin itself for ranking
    magnetWeight.set(magnetOff, (magnetWeight.get(magnetOff) ?? 0) + w * 1.4);

    if (left) {
      leaveN++;
      if (returned) revisit++;
      if (firstDir === 1) impulseUp++;
      else if (firstDir === -1) impulseDown++;
      impulseN++;
    }
  }

  const combined = new Map<number, number>();
  const allKeys = new Set([...touchWeight.keys(), ...magnetWeight.keys()]);
  for (const k of allKeys) {
    // Zero out / ignore near-zero offsets in ranking (current price)
    if (Math.abs(k) < minOff) continue;
    const score = (touchWeight.get(k) ?? 0) + (magnetWeight.get(k) ?? 0);
    if (score > 0) combined.set(k, score);
  }

  // If everything was near zero, fall back to farther offsets from touchWeight
  if (combined.size === 0) {
    for (const [k, score] of touchWeight) {
      if (Math.abs(k) < minOff) continue;
      combined.set(k, score);
    }
  }

  const offsets = [...combined.keys()].sort((a, b) => a - b);
  const peaks: { off: number; score: number }[] = [];
  for (const off of offsets) {
    const s = combined.get(off) ?? 0;
    const left = combined.get(off - 1) ?? 0;
    const right = combined.get(off + 1) ?? 0;
    if (s >= left && s >= right && s > 0) {
      peaks.push({ off, score: s });
    }
  }
  if (peaks.length < 3) {
    peaks.length = 0;
    for (const [off, score] of combined) {
      peaks.push({ off, score });
    }
  }

  peaks.sort((a, b) => b.score - a.score || Math.abs(b.off) - Math.abs(a.off));

  const selected: { off: number; score: number }[] = [];
  // Separation in ticks: at least 2, or half of minOff
  const sep = Math.max(2, Math.floor(minOff / 2));

  for (const p of peaks) {
    if (Math.abs(p.off) < minOff) continue;
    if (selected.some((s) => Math.abs(s.off - p.off) < sep)) continue;
    selected.push(p);
    if (selected.length >= maxScenarios) break;
  }

  // Ensure at least one up and one down when data allows
  if (selected.length > 0) {
    const hasUp = selected.some((s) => s.off > 0);
    const hasDown = selected.some((s) => s.off < 0);
    if (!hasUp) {
      const up = peaks.find(
        (p) => p.off >= minOff && !selected.some((s) => Math.abs(s.off - p.off) < sep),
      );
      if (up) selected.push(up);
    }
    if (!hasDown) {
      const down = peaks.find(
        (p) => p.off <= -minOff && !selected.some((s) => Math.abs(s.off - p.off) < sep),
      );
      if (down) selected.push(down);
    }
  }

  // Still empty: seed min-offset synthetic levels from residual weights
  if (selected.length === 0) {
    selected.push({ off: minOff, score: 1 });
    selected.push({ off: -minOff, score: 1 });
  }

  const totalSel = selected.reduce((s, x) => s + x.score, 0) || 1;
  const totalTouch =
    [...touchWeight.entries()]
      .filter(([off]) => Math.abs(off) >= minOff)
      .reduce((a, [, v]) => a + v, 0) || 1;

  let magnetOff = minOff;
  let magnetScore = -1;
  for (const [off, sc] of magnetWeight) {
    if (Math.abs(off) < minOff) continue;
    if (sc > magnetScore) {
      magnetScore = sc;
      magnetOff = off;
    }
  }

  const current = path[path.length - 1]!;
  const scenarios: PriceScenario[] = selected
    .filter((s) => Math.abs(s.off) >= minOff)
    .map((s) => ({
      price: discretize(current.level + s.off * tick, tick),
      offsetTicks: s.off,
      probability: (s.score / totalSel) * 100,
      histTouch: ((touchWeight.get(s.off) ?? 0) / totalTouch) * 100,
      reachProb: sampleN > 0 ? ((reachCount.get(s.off) ?? 0) / sampleN) * 100 : 0,
      isMagnet: s.off === magnetOff,
    }))
    .filter((s) => Math.abs(s.price - current.level) >= minOff * tick * 0.99)
    .sort((a, b) => b.probability - a.probability);

  // Renormalize to 100% among shown
  const pSum = scenarios.reduce((s, x) => s + x.probability, 0) || 1;
  for (const sc of scenarios) {
    sc.probability = (sc.probability / pSum) * 100;
  }

  return {
    scenarios,
    firstImpulseUp: impulseN > 0 ? (impulseUp / impulseN) * 100 : 50,
    firstImpulseDown: impulseN > 0 ? (impulseDown / impulseN) * 100 : 50,
    revisitCurrent: leaveN > 0 ? (revisit / leaveN) * 100 : 0,
    currentPrice: current.price,
    currentLevel: current.level,
    horizonLabel: formatHorizon(windowMs),
  };
}

function formatHorizon(ms: number): string {
  if (ms < 60 * 60 * 1000) return `${Math.round(ms / 60000)}m`;
  if (ms < 24 * 60 * 60 * 1000) return `${Math.round(ms / 3600000)}h`;
  return `${Math.round(ms / 86400000)}d`;
}

export function runAnalysis(opts: {
  symbol: string;
  yahooSymbol: string;
  bars: OHLCBar[];
  interval: string;
  range: string;
  windowMs: number;
  windowLabel: string;
  tickOverride?: number | null;
  /** Cap scenarios returned (Free 2 / Pro 5). */
  maxScenarios?: number;
  /** Cap recent revisits (Free 5 / Pro 12). */
  maxRecentRevisits?: number;
}): AnalysisResult {
  const sample = opts.bars.flatMap((b) => [b.o, b.h, b.l, b.c]);
  let tick =
    opts.tickOverride && opts.tickOverride > 0
      ? opts.tickOverride
      : detectTick(opts.yahooSymbol, sample);

  if (
    !allowsPriceDecimals(opts.yahooSymbol) &&
    !(opts.tickOverride && opts.tickOverride > 0)
  ) {
    tick = 1;
  }

  const path = reconstructPath(opts.bars, tick);
  const windows = analyzeWindows(path, opts.windowMs);
  const metrics = aggregateMetrics(windows);
  const trend = computeTrend(opts.bars, path, tick);
  const maxSc = Math.max(1, Math.min(8, opts.maxScenarios ?? 5));
  const maxRev = Math.max(1, Math.min(20, opts.maxRecentRevisits ?? 5));
  const scenarios = computeScenarios(
    path,
    opts.windowMs,
    tick,
    maxSc,
    opts.yahooSymbol,
  );
  const recentRevisits = findRecentRevisits(path, maxRev);

  if (!allowsPriceDecimals(opts.yahooSymbol)) {
    tick = Math.max(1, Math.round(tick));
    for (const sc of scenarios.scenarios) {
      sc.price = Math.round(sc.price);
      sc.offsetTicks = Math.round(sc.offsetTicks);
    }
    scenarios.currentLevel = Math.round(scenarios.currentLevel);
    for (const r of recentRevisits) {
      r.level = Math.round(r.level);
    }
  }

  const lastPrice =
    opts.bars[opts.bars.length - 1]?.c ?? scenarios.currentPrice;

  return {
    symbol: opts.symbol,
    yahooSymbol: opts.yahooSymbol,
    tick,
    interval: opts.interval,
    range: opts.range,
    windowMs: opts.windowMs,
    windowLabel: opts.windowLabel,
    bars: opts.bars,
    lastPrice: allowsPriceDecimals(opts.yahooSymbol) ? lastPrice : Math.round(lastPrice),
    metrics,
    trend,
    scenarios,
    windows,
    recentRevisits,
    fetchedAt: Date.now(),
  };
}

/**
 * Unified market data: Yahoo (history bulk) + Alpha Vantage (live / FX spot when budget).
 */
import {
  fetchAvFxBars,
  fetchAvLivePrice,
  isAlphaVantageEnabled,
} from "./alpha-vantage";
import type { OHLCBar } from "./types";
import { fetchYahooOHLC } from "./yahoo";
import { resolveYahooSymbol } from "./symbols";

export type MarketOHLC = {
  yahooSymbol: string;
  bars: OHLCBar[];
  meta: {
    price?: number;
    currency?: string;
    source?: string;
    liveSource?: string;
  };
};

function patchLastPrice(bars: OHLCBar[], price: number): OHLCBar[] {
  if (!bars.length || !(price > 0)) return bars;
  const out = bars.slice();
  const last = { ...out[out.length - 1]! };
  // Keep OHLC consistent with a fresh last trade
  last.c = price;
  last.h = Math.max(last.h, price);
  last.l = Math.min(last.l, price);
  out[out.length - 1] = last;
  return out;
}

/**
 * Primary OHLC fetch used by analyze / scalper / quantum / live quote.
 */
export async function fetchMarketOHLC(opts: {
  symbol: string;
  interval: string;
  range: string;
  /** When true, skip AV (e.g. Quantum multi-scan to save free quota). */
  yahooOnly?: boolean;
}): Promise<MarketOHLC> {
  const yahooSymbol = resolveYahooSymbol(opts.symbol);
  const useAv = isAlphaVantageEnabled() && !opts.yahooOnly;

  // Prefer Alpha Vantage spot FX bars when available (matches broker spot better than some Yahoo FX)
  if (useAv && yahooSymbol.endsWith("=X")) {
    try {
      const av = await fetchAvFxBars(opts.symbol, opts.interval);
      if (av && av.bars.length >= 10) {
        let bars = av.bars;
        // trim by rough range
        const rangeMs = rangeToMs(opts.range);
        if (rangeMs > 0) {
          const cut = Date.now() - rangeMs;
          const trimmed = bars.filter((b) => b.t >= cut);
          if (trimmed.length >= 10) bars = trimmed;
        }
        const live = await fetchAvLivePrice(opts.symbol);
        if (live) bars = patchLastPrice(bars, live.price);
        return {
          yahooSymbol,
          bars,
          meta: {
            price: live?.price ?? bars[bars.length - 1]?.c,
            source: av.source,
            liveSource: live?.source,
          },
        };
      }
    } catch {
      /* fall through to Yahoo */
    }
  }

  const y = await fetchYahooOHLC(opts);
  let bars = y.bars;
  let liveSource: string | undefined;
  let price = y.meta.price;

  // Overlay fresher AV last price (equities / crypto / FX) when budget allows
  if (useAv) {
    try {
      const live = await fetchAvLivePrice(opts.symbol);
      if (live) {
        // Sanity: ignore AV if wildly different from Yahoo last close (>25%) for non-futures
        const yLast = bars[bars.length - 1]?.c;
        const ok =
          !yLast ||
          Math.abs(live.price - yLast) / yLast < 0.25 ||
          yahooSymbol.endsWith("=X");
        if (ok) {
          bars = patchLastPrice(bars, live.price);
          price = live.price;
          liveSource = live.source;
        }
      }
    } catch {
      /* ignore */
    }
  }

  return {
    yahooSymbol: y.yahooSymbol,
    bars,
    meta: {
      price,
      currency: y.meta.currency,
      source: liveSource ? `yahoo+${liveSource}` : "yahoo",
      liveSource,
    },
  };
}

function rangeToMs(range: string): number {
  switch (range) {
    case "1d":
      return 1 * 24 * 60 * 60_000;
    case "5d":
      return 5 * 24 * 60 * 60_000;
    case "1mo":
      return 31 * 24 * 60 * 60_000;
    case "3mo":
      return 93 * 24 * 60 * 60_000;
    case "6mo":
      return 186 * 24 * 60 * 60_000;
    case "1y":
      return 366 * 24 * 60 * 60_000;
    default:
      return 0;
  }
}

import { allowsPriceDecimals } from "./symbols";

/**
 * Single source of truth for pip/point size across engine, scalper, alerts.
 * Forex (Yahoo `=X`): decimal pips. Everything else: whole points.
 */
export function pipSize(yahooSymbol: string, tick: number): number {
  const s = yahooSymbol.toUpperCase();
  if (!allowsPriceDecimals(s)) return Math.max(tick >= 1 ? tick : 1, 1);
  if (s.includes("JPY") && s.endsWith("=X")) return 0.01;
  if (s === "USDCOP=X") return 0.01;
  if (s.endsWith("=X")) return 0.0001;
  return Math.max(tick > 0 ? tick : 0.0001, 0.0001);
}

export function priceDiffToPips(
  yahooSymbol: string,
  priceDiff: number,
  tick: number,
): number {
  const ps = pipSize(yahooSymbol, tick);
  if (!(ps > 0)) return 0;
  return priceDiff / ps;
}

/**
 * Minimum |offset| in ticks so “next prices” are not the spot itself.
 * Forex ≥5 pips · equities/crypto/indices ≥2 points.
 */
export function minScenarioOffsetTicks(
  yahooSymbol: string,
  tick: number,
): number {
  const t = tick > 0 ? tick : allowsPriceDecimals(yahooSymbol) ? 0.0001 : 1;
  const pip = pipSize(yahooSymbol, t);
  const minPips = allowsPriceDecimals(yahooSymbol) ? 5 : 2;
  return Math.max(1, Math.ceil((minPips * pip) / t - 1e-12));
}

/** Human label for the unit (pip vs point). */
export function unitLabel(yahooSymbol: string, lang: "en" | "es" = "en"): string {
  if (allowsPriceDecimals(yahooSymbol)) {
    return lang === "es" ? "pips" : "pips";
  }
  return lang === "es" ? "pts" : "pts";
}

/**
 * In-process Quantum job store for live progress (dev + long-lived Node).
 * On multi-instance serverless, prefer a single request; jobs still work
 * when the same isolate handles start + poll.
 */
import type { QuantumRunResult } from "./quantum";

export type QuantumJobPhase = "queued" | "phase1" | "phase2" | "consensus" | "done" | "error";

export type QuantumJobProgress = {
  jobId: string;
  status: QuantumJobPhase;
  phase: 0 | 1 | 2 | 3;
  label: string;
  detail: string;
  current: number;
  total: number;
  pct: number;
  refinedAssets?: string[];
  result?: QuantumRunResult;
  error?: string;
  updatedAt: number;
  createdAt: number;
};

const g = globalThis as typeof globalThis & {
  __quantumJobs__?: Map<string, QuantumJobProgress>;
};

function store(): Map<string, QuantumJobProgress> {
  g.__quantumJobs__ ??= new Map();
  return g.__quantumJobs__;
}

export function newQuantumJobId(): string {
  return `q-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

export function createQuantumJob(jobId: string, totalEstimate: number): QuantumJobProgress {
  const job: QuantumJobProgress = {
    jobId,
    status: "queued",
    phase: 0,
    label: "Queued",
    detail: "Starting…",
    current: 0,
    total: Math.max(1, totalEstimate),
    pct: 0,
    createdAt: Date.now(),
    updatedAt: Date.now(),
  };
  store().set(jobId, job);
  // prune old jobs (>30 min)
  const cutoff = Date.now() - 30 * 60_000;
  for (const [id, j] of store()) {
    if (j.updatedAt < cutoff) store().delete(id);
  }
  return job;
}

export function patchQuantumJob(
  jobId: string,
  patch: Partial<QuantumJobProgress>,
): QuantumJobProgress | null {
  const prev = store().get(jobId);
  if (!prev) return null;
  const next: QuantumJobProgress = {
    ...prev,
    ...patch,
    updatedAt: Date.now(),
    pct: Math.min(
      100,
      Math.round(
        ((patch.current ?? prev.current) / Math.max(1, patch.total ?? prev.total)) *
          100,
      ),
    ),
  };
  // keep explicit pct if provided
  if (patch.pct != null) next.pct = patch.pct;
  store().set(jobId, next);
  return next;
}

export function getQuantumJob(jobId: string): QuantumJobProgress | null {
  return store().get(jobId) ?? null;
}

