export function pickQuantumUniverse(limit = 7): SymbolEntry[] {
  const byValue = new Map(SYMBOL_LIST.map((s) => [s.value.toUpperCase(), s]));
  const out: SymbolEntry[] = [];
  const seenYahoo = new Set<string>();

  for (const v of QUANTUM_UNIVERSE_DEFAULT) {
    if (out.length >= limit) break;
    const entry = byValue.get(v.toUpperCase());
    if (!entry) continue;
    const y = entry.yahoo.toUpperCase();
    if (seenYahoo.has(y)) continue;
    seenYahoo.add(y);
    out.push(entry);
  }

  if (out.length < limit) {
    for (const entry of SYMBOL_LIST) {
      if (out.length >= limit) break;
      const y = entry.yahoo.toUpperCase();
      if (seenYahoo.has(y)) continue;
      seenYahoo.add(y);
      out.push(entry);
    }
  }
  return out;
}

export type QuantumCandidate = {
  id: string;
  symbol: string;
  yahooSymbol: string;
  name: string;
  category: string;
  interval: string;
  range: string;
  window: string;
  style: QuantumParamCombo["style"];
  currentPrice: number;
  targetPrice: number;
  direction: "up" | "down";
  pips: number;
  probability: number;
  histTouch: number;
  reachProb: number;
  isMagnet: boolean;
  tick: number;
  score: number;
  trendScore: number;
  trendLabel: string;
  consensus?: number;
  phase?: 1 | 2;
  edge?: number;
};

export type QuantumRunResult = {
  topPrices: QuantumCandidate[];
