function scenarioPips(
  yahoo: string,
  current: number,
  target: number,
  tick: number,
): number {
  return Math.abs(priceDiffToPips(yahoo, target - current, tick));
}

function oppositeReach(list: PriceScenario[], sc: PriceScenario): number {
  const want = sc.offsetTicks >= 0 ? "down" : "up";
  let best = 0;
  for (const o of list) {
    const dir = o.offsetTicks >= 0 ? "up" : "down";
    if (dir !== want) continue;
    best = Math.max(best, o.reachProb ?? o.probability ?? 0);
  }
  return best;
}

export function scoreQuantumTarget(
  sc: PriceScenario,
  current: number,
  yahoo: string,
  tick: number,
  trendScore: number,
  allScenarios: PriceScenario[] = [],
): { pips: number; score: number; direction: "up" | "down"; edge: number } {
  const pips = scenarioPips(yahoo, current, sc.price, tick);
  const reach = sc.reachProb ?? sc.probability;
  const direction: "up" | "down" = sc.price >= current ? "up" : "down";
  const opp = oppositeReach(allScenarios, sc);
  const edge = reach - opp;

  const pScore = Math.min(42, reach * 0.42);
  const pipScore = Math.min(28, Math.log1p(pips) * 7.2);
  const edgeScore = Math.min(14, Math.max(0, edge) * 0.28);
  const magnetBonus = sc.isMagnet ? 7 : 0;
  const histBonus = Math.min(6, (sc.histTouch ?? 0) * 0.06);
  const align =
    direction === "up"
      ? (trendScore - 50) * 0.1
      : (50 - trendScore) * 0.1;

  return {
    pips,
    direction,
    edge,
    score: pScore + pipScore + edgeScore + magnetBonus + histBonus + align,
  };
}

export function candidatesFromAnalysis(
  result: AnalysisResult,
  combo: QuantumParamCombo,
  name: string,
  category: string,
): QuantumCandidate[] {
  const current = result.scenarios.currentPrice || result.lastPrice;
  const list = result.scenarios.scenarios ?? [];
  const out: QuantumCandidate[] = [];

  for (const sc of list) {
    const { pips, score, direction, edge } = scoreQuantumTarget(
      sc,
      current,
      result.yahooSymbol,
      result.tick,
      result.trend.score,
      list,
    );
    if (pips < 0.5) continue;

    out.push({
      id: `${result.symbol}|${combo.id}|${sc.price}|${sc.offsetTicks}`,
      symbol: result.symbol,
      yahooSymbol: result.yahooSymbol,
      name,
      category,
      interval: combo.interval,
      range: combo.range,
      window: combo.window,
      style: combo.style,
      currentPrice: current,
      targetPrice: sc.price,
      direction,
      pips,
      probability: sc.probability,
      histTouch: sc.histTouch,
      reachProb: sc.reachProb ?? sc.probability,
      isMagnet: sc.isMagnet,
      tick: result.tick,
      score,
      trendScore: result.trend.score,
      trendLabel: result.trend.label,
      phase: combo.phase,
      edge,
      consensus: 1,
    });
  }
  return out;
}

export function targetBucketKey(c: QuantumCandidate): string {
  const tick = c.tick > 0 ? c.tick : 0.0001;
  const rounded = Math.round(c.targetPrice / (tick * 2)) * (tick * 2);
  return `${c.symbol.toUpperCase()}|${rounded.toFixed(8)}`;
}

export function applyConsensusBoost(
  all: QuantumCandidate[],
): { boosted: QuantumCandidate[]; boostCount: number } {
  const buckets = new Map<string, QuantumCandidate[]>();
  for (const c of all) {
    const k = targetBucketKey(c);
    const list = buckets.get(k) ?? [];
    list.push(c);
    buckets.set(k, list);
  }

  let boostCount = 0;
  const boosted: QuantumCandidate[] = [];

  for (const [, list] of buckets) {
    const windows = new Set(
      list.map((c) => `${c.interval}|${c.window}|${c.range}`),
    );
    const consensus = windows.size;
    list.sort((a, b) => b.score - a.score || b.reachProb - a.reachProb);
    const best = list[0]!;
    if (consensus >= 2) {
      boostCount += 1;
      const multiWindowBonus = Math.min(22, (consensus - 1) * 9);
      const avgReach =
        list.reduce((s, x) => s + (x.reachProb || x.probability), 0) /
        list.length;
      boosted.push({
        ...best,
        consensus,
        score: best.score + multiWindowBonus + Math.min(8, avgReach * 0.05),
        reachProb: Math.max(best.reachProb, avgReach * 0.85),
      });
    } else {
      boosted.push({ ...best, consensus: 1 });
    }
    for (let i = 1; i < list.length && i < 2; i++) {
      const alt = list[i]!;
      if (alt.score >= best.score * 0.92 && alt.window !== best.window) {
        boosted.push({ ...alt, consensus });
      }
    }
  }

  return { boosted, boostCount };
}

export function assetSeedScore(candidates: QuantumCandidate[]): number {
  if (candidates.length === 0) return -Infinity;
  const sorted = [...candidates].sort(
    (a, b) => b.score - a.score || b.reachProb - a.reachProb,
  );
  const top = sorted.slice(0, 3);
  const best = top[0]!;
  const avg = top.reduce((s, c) => s + c.score, 0) / Math.max(1, top.length);
  return best.score * 0.65 + avg * 0.35 + (best.reachProb || 0) * 0.15;
}

export function pickAssetsToRefine(
  all: QuantumCandidate[],
  universe: SymbolEntry[],
  k = QUANTUM_REFINE_ASSETS,
): SymbolEntry[] {
  const bySym = new Map<string, QuantumCandidate[]>();
  for (const c of all) {
    const s = c.symbol.toUpperCase();
    const list = bySym.get(s) ?? [];
    list.push(c);
    bySym.set(s, list);
  }

  const ranked = universe
    .map((entry) => ({
      entry,
      seed: assetSeedScore(bySym.get(entry.value.toUpperCase()) ?? []),
    }))
    .filter((x) => Number.isFinite(x.seed) && x.seed > -Infinity)
    .sort((a, b) => b.seed - a.seed);

  const picked = ranked.slice(0, k).map((x) => x.entry);
  if (picked.length < k) {
    for (const e of universe) {
      if (picked.length >= k) break;
      if (!picked.some((p) => p.value === e.value)) picked.push(e);
    }
  }
  return picked;
}

function sortByQuality(a: QuantumCandidate, b: QuantumCandidate): number {
  const ca = (a.consensus ?? 1) >= 2 ? 1 : 0;
  const cb = (b.consensus ?? 1) >= 2 ? 1 : 0;
  if (cb !== ca) return cb - ca;
  if (b.score !== a.score) return b.score - a.score;
  const pa = a.reachProb || a.probability;
  const pb = b.reachProb || b.probability;
  if (pb !== pa) return pb - pa;
  return b.pips - a.pips;
}

export function rankQuantumTop(
  all: QuantumCandidate[],
  limit = QUANTUM_TOP_LIMIT,
  maxPerSymbol = QUANTUM_MAX_PER_SYMBOL,
): QuantumCandidate[] {
  if (all.length === 0) return [];

  const { boosted } = applyConsensusBoost(all);
  const sorted = [...boosted].sort(sortByQuality);

  const out: QuantumCandidate[] = [];
  const usedTarget = new Set<string>();
  const perSym = new Map<string, number>();

  for (const c of sorted) {
    const sym = c.symbol.toUpperCase();
    const n = perSym.get(sym) ?? 0;
    if (n >= maxPerSymbol) continue;
    const tk = targetBucketKey(c);
    if (usedTarget.has(tk)) continue;
    if (c.pips < 0.5) continue;

    usedTarget.add(tk);
    perSym.set(sym, n + 1);
    out.push(c);
    if (out.length >= limit) break;
  }

  if (out.length < limit) {
    for (const c of sorted) {
      if (out.length >= limit) break;
      const sym = c.symbol.toUpperCase();
      const n = perSym.get(sym) ?? 0;
      if (n >= maxPerSymbol + 1) continue;
      const tk = targetBucketKey(c);
      if (usedTarget.has(tk)) continue;
      if (c.pips < 0.5) continue;
      usedTarget.add(tk);
      perSym.set(sym, n + 1);
      out.push(c);
    }
  }

  return out.slice(0, limit);
}

export type QuantumAnalyzeFn = (
  entry: SymbolEntry,
  combo: QuantumParamCombo,
) => Promise<QuantumCandidate[]>;

/**
 * Multi-phase Quantum search loop with progress callbacks + filters.
 */
export async function runQuantumLoop(opts: {
  universe: SymbolEntry[];
  analyze: QuantumAnalyzeFn;
  refineCount?: number;
  pauseMs?: number;
  minProb?: number;
  minPips?: number;
  onProgress?: (e: QuantumProgressEvent) => void;
}): Promise<{
  all: QuantumCandidate[];
  scanned: number;
  errors: { symbol: string; error: string }[];
  phase1Scans: number;
  phase2Scans: number;
  refinedAssets: string[];
  consensusBoosts: number;
  topPrices: QuantumCandidate[];
}> {
  const pause = opts.pauseMs ?? 70;
  const minProb = opts.minProb ?? 0;
  const minPips = opts.minPips ?? 0;
  const all: QuantumCandidate[] = [];
  const errors: { symbol: string; error: string }[] = [];
  let scanned = 0;
  let phase1Scans = 0;
  let phase2Scans = 0;

  const p1Total = opts.universe.length * QUANTUM_PHASE1_GRID.length;
  const p2Total =
    (opts.refineCount ?? QUANTUM_REFINE_ASSETS) * QUANTUM_PHASE2_GRID.length;
  const totalEst = p1Total + p2Total + 1;

  const sleep = () => new Promise((r) => setTimeout(r, pause));
  const report = (e: QuantumProgressEvent) => {
    try {
      opts.onProgress?.(e);
    } catch {
      /* ignore */
    }
  };

  report({
    phase: 1,
    status: "phase1",
    label: "Wide scan",
    detail: "Scanning liquid assets…",
    current: 0,
    total: totalEst,
  });

  for (const entry of opts.universe) {
    for (const combo of QUANTUM_PHASE1_GRID) {
      scanned += 1;
      phase1Scans += 1;
      try {
        const got = await opts.analyze(entry, combo);
        all.push(...got);
      } catch (e) {
        errors.push({
          symbol: `${entry.value}/${combo.id}`,
          error: e instanceof Error ? e.message : String(e),
        });
      }
      report({
        phase: 1,
        status: "phase1",
        label: "Wide scan",
        detail: `${entry.value} · ${combo.window}`,
        current: scanned,
        total: totalEst,
      });
      await sleep();
    }
  }

  const refineList = pickAssetsToRefine(
    all,
    opts.universe,
    opts.refineCount ?? QUANTUM_REFINE_ASSETS,
  );
  const refinedAssets = refineList.map((e) => e.value);

  report({
    phase: 2,
    status: "phase2",
    label: "Deep refine",
    detail: refinedAssets.join(", ") || "—",
    current: scanned,
    total: totalEst,
    refinedAssets,
  });

  for (const entry of refineList) {
    for (const combo of QUANTUM_PHASE2_GRID) {
      scanned += 1;
      phase2Scans += 1;
      try {
        const got = await opts.analyze(entry, combo);
        all.push(...got);
      } catch (e) {
        errors.push({
          symbol: `${entry.value}/${combo.id}`,
          error: e instanceof Error ? e.message : String(e),
        });
      }
      report({
        phase: 2,
        status: "phase2",
        label: "Deep refine",
        detail: `${entry.value} · ${combo.id}`,
        current: scanned,
        total: totalEst,
        refinedAssets,
      });
      await sleep();
    }
  }

  report({
    phase: 3,
    status: "consensus",
    label: "Consensus",
    detail: "Scoring multi-window agreement…",
    current: scanned,
    total: totalEst,
    refinedAssets,
  });

  const { boostCount } = applyConsensusBoost(all);
  let topPrices = rankQuantumTop(all, QUANTUM_TOP_LIMIT);

  if (minProb > 0 || minPips > 0) {
    const filtered = topPrices.filter((c) => {
      const p = c.reachProb || c.probability;
      if (minProb > 0 && p < minProb) return false;
      if (minPips > 0 && c.pips < minPips) return false;
      return true;
    });
    if (filtered.length === 0) {
      topPrices = rankQuantumTop(all, QUANTUM_TOP_LIMIT).filter((c) => {
        const p = c.reachProb || c.probability;
        return (
          (minProb <= 0 || p >= minProb * 0.5) &&
          (minPips <= 0 || c.pips >= minPips * 0.5)
        );
      });
    } else {
      topPrices = filtered;
    }
  }

  report({
    phase: 3,
    status: "done",
    label: "Done",
    detail: `${topPrices.length} targets`,
    current: totalEst,
    total: totalEst,
    refinedAssets,
  });

  return {
    all,
    scanned,
    errors,
    phase1Scans,
    phase2Scans,
    refinedAssets,
    consensusBoosts: boostCount,
    topPrices,
  };
}

import type { AnalysisResult } from "./types";

const KEY = "pra-analysis-cache-v1";
const TTL_MS = 90_000;

type CacheEntry = {
  key: string;
  at: number;
  result: AnalysisResult;
};

function paramsKey(p: {
  symbol: string;
  interval: string;
  range: string;
  window: string;
  tick: string | null;
}): string {
  return [
    p.symbol.toUpperCase(),
    p.interval,
    p.range,
    p.window,
    p.tick ?? "auto",
  ].join("|");
}

export function readAnalysisCache(p: {
  symbol: string;
  interval: string;
  range: string;
  window: string;
  tick: string | null;
}): AnalysisResult | null {
  try {
    const raw = sessionStorage.getItem(KEY);
    if (!raw) return null;
    const entry = JSON.parse(raw) as CacheEntry;
    if (entry.key !== paramsKey(p)) return null;
    if (Date.now() - entry.at > TTL_MS) return null;
    return entry.result;
  } catch {
    return null;
  }
}

export function writeAnalysisCache(
  p: {
    symbol: string;
    interval: string;
    range: string;
    window: string;
    tick: string | null;
  },
  result: AnalysisResult,
): void {
  try {
    const entry: CacheEntry = {
      key: paramsKey(p),
      at: Date.now(),
      result,
    };
    sessionStorage.setItem(KEY, JSON.stringify(entry));
  } catch {
    /* quota */
  }
}

import { reconstructPath, discretize } from "./engine";
import { pipSize, priceDiffToPips } from "./pips";
import { allowsPriceDecimals, detectTick } from "./symbols";
import type { AnalysisResult, OHLCBar, PriceScenario, ScalperSetup } from "./types";

const PROB_THRESHOLD = 80;
const MIN_PIPS_DEFAULT = 8;

export { pipSize } from "./pips";

export function priceToPips(
  yahooSymbol: string,
  priceDiff: number,
  tick: number,
): number {
  return Math.abs(priceDiffToPips(yahooSymbol, priceDiff, tick));
}

export function minPipsFor(
  yahooSymbol: string,
  atrPips: number,
  windowMs: number,
): number {
  const s = yahooSymbol.toUpperCase();
  let base = MIN_PIPS_DEFAULT;
  if (s === "USDCOP=X") base = 20;
  else if (s.endsWith("=X")) base = 6;
  else base = 1;

  const hourFrac = windowMs / (60 * 60 * 1000);
  const windowScale = Math.sqrt(Math.max(0.2, Math.min(hourFrac, 4)));
  const atrFloor = atrPips * 0.15;
  return Math.max(base, Math.round(atrFloor * windowScale));
}

function atrPipsFromBars(
  bars: OHLCBar[],
  yahooSymbol: string,
  tick: number,
  lookback = 40,
): number {
  if (bars.length < 2) return 0;
  const slice = bars.slice(-lookback);
  let sum = 0;
  for (let i = 1; i < slice.length; i++) {
    const b = slice[i]!;
    const prev = slice[i - 1]!;
    const tr = Math.max(
      b.h - b.l,
      Math.abs(b.h - prev.c),
      Math.abs(b.l - prev.c),
    );
    sum += tr;
  }
  const atr = sum / Math.max(1, slice.length - 1);
  return priceToPips(yahooSymbol, atr, tick);
}

/** MFE / MAE over recent path windows in pip units. */
function excursionStats(
  bars: OHLCBar[],
  yahooSymbol: string,
  tick: number,
  direction: "up" | "down",
  windowMs: number,
): { mfe: number; mae: number } {
  if (bars.length < 8) return { mfe: 0, mae: 0 };
  const path = reconstructPath(bars, tick);
  if (path.length < 10) return { mfe: 0, mae: 0 };

  let mfeSum = 0;
  let maeSum = 0;
  let n = 0;
  const step = Math.max(1, Math.floor(path.length / 40));

  for (let i = 0; i < path.length - 5; i += step) {
    const a = path[i]!;
    const endT = a.t + windowMs;
    let maxFav = 0;
    let maxAdv = 0;
    for (let j = i + 1; j < path.length; j++) {
      const p = path[j]!;
      if (p.t > endT) break;
      const d = priceToPips(yahooSymbol, p.price - a.price, tick);
      if (direction === "up") {
        maxFav = Math.max(maxFav, d);
        maxAdv = Math.max(maxAdv, -d);
      } else {
        maxFav = Math.max(maxFav, -d);
        maxAdv = Math.max(maxAdv, d);
      }
    }
    mfeSum += maxFav;
    maeSum += maxAdv;
    n += 1;
  }
  if (n === 0) return { mfe: 0, mae: 0 };
  return { mfe: mfeSum / n, mae: maeSum / n };
}

function oppositeScenario(
  scenarios: PriceScenario[],
  sc: PriceScenario,
): PriceScenario | undefined {
  const wantDir = sc.offsetTicks >= 0 ? "down" : "up";
  const absOff = Math.abs(sc.offsetTicks);
  let best: PriceScenario | undefined;
  let bestDist = Infinity;
  for (const o of scenarios) {
    const dir = o.offsetTicks >= 0 ? "up" : "down";
    if (dir !== wantDir) continue;
    const dist = Math.abs(Math.abs(o.offsetTicks) - absOff);
    if (dist < bestDist) {
      bestDist = dist;
      best = o;
    }
  }
  return best;
}

/**
 * Turn one asset analysis into ranked scalper candidates.
 */
export function setupsFromAnalysis(result: AnalysisResult): ScalperSetup[] {
  const { yahooSymbol, tick, scenarios, bars, windowLabel, windowMs, symbol } =
    result;
  const scList = scenarios.scenarios ?? [];
  if (scList.length === 0) return [];

  const atr = atrPipsFromBars(bars, yahooSymbol, tick);
  const minPips = minPipsFor(yahooSymbol, atr, windowMs);
  const out: ScalperSetup[] = [];

  for (const sc of scList) {
    const pips = priceToPips(
      yahooSymbol,
      Math.abs(sc.price - scenarios.currentPrice),
      tick,
    );
    if (pips + 1e-9 < minPips) continue;

    const direction: "up" | "down" =
      sc.price >= scenarios.currentPrice ? "up" : "down";
    const opp = oppositeScenario(scList, sc);
    const oppositeProb = opp?.reachProb ?? opp?.probability ?? 0;
    const reach = sc.reachProb ?? sc.probability;
    const edge = reach - oppositeProb;
    const { mfe, mae } = excursionStats(
      bars,
      yahooSymbol,
      tick,
      direction,
      windowMs,
    );

    // Score: high reach + edge + pips vs ATR + MFE quality
    const pipScore = Math.min(30, (pips / Math.max(minPips, 1)) * 12);
    const reachScore = Math.min(40, reach * 0.4);
    const edgeScore = Math.min(20, Math.max(0, edge) * 0.35);
    const mfeScore = Math.min(10, (mfe / Math.max(pips, 1)) * 8);
    const score = reachScore + edgeScore + pipScore + mfeScore;

    out.push({
      symbol,
      yahooSymbol,
      currentPrice: scenarios.currentPrice,
      targetPrice: sc.price,
      direction,
      pips,
      probability: reach,
      histTouch: sc.histTouch,
      isMagnet: sc.isMagnet,
      tick,
      windowLabel,
      score,
      meetsThreshold: reach >= PROB_THRESHOLD && pips >= minPips,
      edge,
      oppositeProb,
      samples: Math.max(1, Math.round((scenarios.scenarios.length || 1) * 8)),
      atrPips: atr,
      avgMfe: mfe,
      avgMae: mae,
    });
  }

  return out;
}

export function rankScalperSetups(
  setups: ScalperSetup[],
  topN = 5,
): ScalperSetup[] {
  const bySym = new Map<string, ScalperSetup>();
  for (const s of setups) {
    const key = s.yahooSymbol.toUpperCase();
    const prev = bySym.get(key);
    if (!prev || s.score > prev.score) bySym.set(key, s);
  }

  return [...bySym.values()]
    .sort((a, b) => {
      // Prefer threshold-meeters, then score, then pips
      if (a.meetsThreshold !== b.meetsThreshold) {
        return a.meetsThreshold ? -1 : 1;
      }
      if (b.score !== a.score) return b.score - a.score;
      return b.pips - a.pips;
    })
    .slice(0, topN);
}

