import type { OHLCBar } from "./types";
import { resolveYahooSymbol } from "./symbols";

type YahooChartResponse = {
  chart?: {
    result?: Array<{
      meta?: {
        symbol?: string;
        regularMarketPrice?: number;
        currency?: string;
        instrumentType?: string;
      };
      timestamp?: number[];
      indicators?: {
        quote?: Array<{
          open?: (number | null)[];
          high?: (number | null)[];
          low?: (number | null)[];
          close?: (number | null)[];
          volume?: (number | null)[];
        }>;
      };
    }>;
    error?: { code?: string; description?: string };
  };
};

/** Compatible Yahoo ranges per interval (best-effort). */
function clampRange(interval: string, range: string): string {
  const fine = new Set(["1m", "2m", "5m"]);
  if (fine.has(interval)) {
    if (["1y", "2y", "5y", "10y", "max", "ytd"].includes(range)) return "5d";
    if (["6mo", "3mo"].includes(range)) return "1mo";
    return range;
  }
  if (interval === "15m" || interval === "30m" || interval === "60m" || interval === "1h") {
    if (["2y", "5y", "10y", "max"].includes(range)) return "3mo";
    if (range === "1y") return "6mo";
    return range;
  }
  return range;
}


/** Short in-memory cache + in-flight coalesce (faster reloads / multi-poll). */
const yahooCache = new Map<
  string,
  { at: number; value: Awaited<ReturnType<typeof fetchYahooOHLCUncached>> }
>();
const yahooInflight = new Map<
  string,
  Promise<Awaited<ReturnType<typeof fetchYahooOHLCUncached>>>
>();
const YAHOO_TTL_MS = 45_000;

async function fetchYahooOHLCUncached(opts: {
  symbol: string;
  interval: string;
  range: string;
}): Promise<{ yahooSymbol: string; bars: OHLCBar[]; meta: { price?: number; currency?: string } }> {
  const yahooSymbol = resolveYahooSymbol(opts.symbol);
  const range = clampRange(opts.interval, opts.range);
  const interval = opts.interval === "1h" ? "60m" : opts.interval;

  const url = new URL(
    `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(yahooSymbol)}`,
  );
  url.searchParams.set("interval", interval);
  url.searchParams.set("range", range);
  url.searchParams.set("includePrePost", "false");
  url.searchParams.set("events", "div,splits");

  const res = await fetch(url.toString(), {
    headers: {
      "User-Agent":
        "Mozilla/5.0 (compatible; PriceRevisitAnalyzer/1.0; +https://x.ai)",
      Accept: "application/json",
    },
  });

  if (!res.ok) {
    throw new Error(`Yahoo Finance error ${res.status} for ${yahooSymbol}`);
  }

  const data = (await res.json()) as YahooChartResponse;
  if (data.chart?.error) {
    throw new Error(
      data.chart.error.description || data.chart.error.code || "Yahoo chart error",
    );
  }

  const result = data.chart?.result?.[0];
  if (!result?.timestamp?.length) {
    throw new Error(`No data returned for ${yahooSymbol}. Try another symbol or range.`);
  }

  const quote = result.indicators?.quote?.[0];
  if (!quote) {
    throw new Error(`Missing quote data for ${yahooSymbol}`);
  }

  const bars: OHLCBar[] = [];
  for (let i = 0; i < result.timestamp.length; i++) {
    const o = quote.open?.[i];
    const h = quote.high?.[i];
    const l = quote.low?.[i];
    const c = quote.close?.[i];
    if (
      o == null ||
      h == null ||
      l == null ||
      c == null ||
      !Number.isFinite(o) ||
      !Number.isFinite(h) ||
      !Number.isFinite(l) ||
      !Number.isFinite(c)
    ) {
      continue;
    }
    bars.push({
      t: result.timestamp[i]! * 1000,
      o,
      h,
      l,
      c,
      v: quote.volume?.[i] ?? 0,
    });
  }

  if (bars.length < 10) {
    throw new Error(
      `Insufficient bars (${bars.length}) for ${yahooSymbol}. Widen range or use a coarser interval.`,
    );
  }

  return {
    yahooSymbol,
    bars,
    meta: {
      price: result.meta?.regularMarketPrice,
      currency: result.meta?.currency,
    },
  };
}


export async function fetchYahooOHLC(opts: {
  symbol: string;
  interval: string;
  range: string;
}): Promise<{ yahooSymbol: string; bars: OHLCBar[]; meta: { price?: number; currency?: string } }> {
  const yahooSymbol = resolveYahooSymbol(opts.symbol);
  const range = clampRange(opts.interval, opts.range);
  const interval = opts.interval === "1h" ? "60m" : opts.interval;
  const key = `${yahooSymbol}|${interval}|${range}`;
  const now = Date.now();
  const hit = yahooCache.get(key);
  if (hit && now - hit.at < YAHOO_TTL_MS) {
    return hit.value;
  }
  const inflight = yahooInflight.get(key);
  if (inflight) return inflight;

  const p = fetchYahooOHLCUncached(opts)
    .then((value) => {
      yahooCache.set(key, { at: Date.now(), value });
      yahooInflight.delete(key);
      return value;
    })
    .catch((err) => {
      yahooInflight.delete(key);
      throw err;
    });
  yahooInflight.set(key, p);
  return p;
}

/**
 * Browser auth client.
 *
 * Desktop live preview: /auth/popup (Vite plugin) popup + bearer postMessage.
 * Mobile: window.open → /api/oauth/start → broker → /api/oauth/done
 *   which postMessages the bearer back to the opener (preview) so the
 *   Grok iframe stays logged in (not a stranded “sub web”).
 */
import { genericOAuthClient } from "better-auth/client/plugins";
import { createAuthClient } from "better-auth/react";
import { GROK_PROVIDERS } from "./providers";

const BEARER_KEY = "grok-auth.bearer-token";

function storeBearer(token: string | null): void {
  if (typeof window === "undefined") return;
  try {
    if (token) window.sessionStorage.setItem(BEARER_KEY, token);
    else window.sessionStorage.removeItem(BEARER_KEY);
  } catch {
    /* ignore */
  }
  try {
    if (token) window.localStorage.setItem(BEARER_KEY, token);
    else window.localStorage.removeItem(BEARER_KEY);
  } catch {
    /* ignore */
  }
}

export function getBearerToken(): string | null {
  if (typeof window === "undefined") return null;
  try {
    const s = window.sessionStorage.getItem(BEARER_KEY);
    if (s) return s;
  } catch {
    /* ignore */
  }
  try {
    const l = window.localStorage.getItem(BEARER_KEY);
    if (l) {
      try {
        window.sessionStorage.setItem(BEARER_KEY, l);
      } catch {
        /* ignore */
      }
      return l;
    }
  } catch {
    /* ignore */
  }
  return null;
}

export const authClient = createAuthClient({
  plugins: [genericOAuthClient()],
  fetchOptions: {
    onRequest(ctx) {
      const token = getBearerToken();
      if (token) ctx.headers.set("Authorization", `Bearer ${token}`);
      return ctx;
    },
    onSuccess(ctx) {
      try {
        const h = ctx.response?.headers;
        if (!h) return;
        const token = h.get("set-auth-token") || h.get("Set-Auth-Token");
        if (token?.trim()) storeBearer(token.trim());
      } catch {
        /* ignore */
      }
    },
  },
});

export const authEnabled = import.meta.env.VITE_AUTH_ENABLED !== "false";

export { GROK_PROVIDERS };

function inLivePreview(): boolean {
  if (typeof window === "undefined") return false;
  const h = window.location.hostname;
  return (
    h.endsWith(".grok-sandbox.com") ||
    h.endsWith(".grok.me") ||
    h === "localhost" ||
    h === "127.0.0.1"
  );
}

export function isMobileClient(): boolean {
  if (typeof window === "undefined" || typeof navigator === "undefined") {
    return false;
  }
  try {
    const ua = navigator.userAgent || "";
    if (
      /Android|iPhone|iPad|iPod|Mobile|webOS|BlackBerry|IEMobile|Opera Mini|CriOS|FxiOS|SamsungBrowser|Brave/i.test(
        ua,
      )
    ) {
      return true;
    }
    if (window.matchMedia("(max-width: 820px) and (pointer: coarse)").matches) {
      return true;
    }
    if (
      window.self !== window.top &&
      window.innerWidth < 900 &&
      navigator.maxTouchPoints > 0
    ) {
      return true;
    }
  } catch {
    /* ignore */
  }
  return false;
}

type PopupMessage = {
  source: "grok-auth-popup";
  token: string | null;
  error?: string;
};

export function buildAuthPopupUrl(
  providerId: string,
  mode: "popup" | "page",
  returnTo = "/",
): string {
  const origin = window.location.origin;
  const q = new URLSearchParams({
    providerId,
    mode,
    returnTo:
      returnTo.startsWith("/") && !returnTo.startsWith("//") ? returnTo : "/",
    appOrigin: origin,
  });
  return `${origin}/auth/popup?${q.toString()}`;
}

/** Real API route — always exists (mobile safe, no Not Found). */
export function buildMobileOAuthStartUrl(
  providerId: string,
  returnTo = "/",
): string {
  const origin = window.location.origin;
  const q = new URLSearchParams({
    providerId,
    returnTo:
      returnTo.startsWith("/") && !returnTo.startsWith("//") ? returnTo : "/",
    appOrigin: origin,
  });
  return `${origin}/api/oauth/start?${q.toString()}`;
}

function waitForAuthResult(
  popup: Window | null,
  timeoutMs = 5 * 60 * 1000,
): Promise<{ token: string | null; error?: string }> {
  return new Promise((resolve) => {
    const origin = window.location.origin;
    let settled = false;
    let closeTimer: number | undefined;
    let timeoutTimer: number | undefined;

    const settle = (token: string | null, error?: string) => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve({ token, error });
    };

    const onMessage = (event: MessageEvent) => {
      // Accept same-origin only for the token payload
      if (event.origin !== origin && event.origin !== "null") return;
      const data = event.data as PopupMessage | undefined;
      if (!data || data.source !== "grok-auth-popup") return;
      settle(data.token ?? null, data.error);
    };

    const onStorage = (event: StorageEvent) => {
      if (event.key !== BEARER_KEY || !event.newValue) return;
      settle(event.newValue);
    };

    let bc: BroadcastChannel | null = null;
    try {
      bc = new BroadcastChannel("grok-auth");
      bc.onmessage = (event) => {
        const data = event.data as PopupMessage | undefined;
        if (!data || data.source !== "grok-auth-popup") return;
        settle(data.token ?? null, data.error);
      };
    } catch {
      bc = null;
    }

    const pollTimer = window.setInterval(() => {
      const t = getBearerToken();
      if (t) {
        settle(t);
        return;
      }
      if (!popup || !popup.closed) return;
      window.clearInterval(pollTimer);
      closeTimer = window.setTimeout(() => {
        const again = getBearerToken();
        if (again) settle(again);
        else settle(null, "popup_closed");
      }, 800);
    }, 300);

    timeoutTimer = window.setTimeout(() => {
      settle(null, "timeout");
    }, timeoutMs);

    function cleanup() {
      window.clearInterval(pollTimer);
      if (closeTimer !== undefined) window.clearTimeout(closeTimer);
      if (timeoutTimer !== undefined) window.clearTimeout(timeoutTimer);
      window.removeEventListener("message", onMessage);
      window.removeEventListener("storage", onStorage);
      try {
        bc?.close();
      } catch {
        /* ignore */
      }
    }

    window.addEventListener("message", onMessage);
    window.addEventListener("storage", onStorage);
  });
}

async function applyTokenAndGo(
  token: string,
  callbackURL: string,
): Promise<void> {
  storeBearer(token);
  try {
    await authClient.getSession();
  } catch {
    /* ignore */
  }
  window.location.assign(
    callbackURL.startsWith("/") && !callbackURL.startsWith("//")
      ? callbackURL
      : "/",
  );
}

/**
 * Sign in with X / Google. Call from a click handler (sync open first).
 */
export async function signIn(
  providerId: string,
  opts: { callbackURL?: string; errorCallbackURL?: string } = {},
): Promise<void> {
  const callbackURL = opts.callbackURL ?? "/";
  storeBearer(null);

  if (inLivePreview()) {
    // ── MOBILE: SAME-FRAME navigation ───────────────────────────────────
    // window.open leaves a stranded X tab and the preview never gets the
    // session (WebView + external browser = separate storage). Navigate
    // this frame through /api/oauth/start → broker → /api/oauth/done → home.
    if (isMobileClient()) {
      const url = buildMobileOAuthStartUrl(providerId, callbackURL);
      window.location.assign(url);
      return new Promise(() => undefined);
    }

    // ── DESKTOP: classic popup ───────────────────────────────────────────
    const url = buildAuthPopupUrl(providerId, "popup", callbackURL);
    const popup = window.open(
      url,
      `grok-signin-${providerId}`,
      "popup,width=520,height=720",
    );

    if (popup) {
      try {
        popup.focus();
      } catch {
        /* ignore */
      }
      const result = await waitForAuthResult(popup);
      if (result.token) {
        await applyTokenAndGo(result.token, callbackURL);
        return;
      }
      if (result.error && result.error !== "popup_closed") {
        throw new Error(`Sign-in failed: ${result.error}`);
      }
    }

    window.location.assign(
      buildAuthPopupUrl(providerId, "page", callbackURL),
    );
    return new Promise(() => undefined);
  }

  // ── Deployed ───────────────────────────────────────────────────────────
  const { data, error } = await authClient.signIn.oauth2({
    providerId,
    callbackURL,
    errorCallbackURL: opts.errorCallbackURL ?? "/login",
  });
  if (error) throw new Error(error.message ?? "Sign-in failed");
  if (data?.url) {
    window.location.assign(data.url);
    return new Promise(() => undefined);
  }
  throw new Error("Sign-in failed: no redirect URL");
}

export async function captureSessionBearer(): Promise<void> {
  try {
    await authClient.getSession();
  } catch {
    /* ignore */
  }
  if (getBearerToken()) return;
  try {
    const res = await fetch("/api/auth/get-session", {
      method: "GET",
      credentials: "include",
      headers: { Accept: "application/json" },
    });
    const token =
      res.headers.get("set-auth-token") || res.headers.get("Set-Auth-Token");
    if (token?.trim()) storeBearer(token.trim());
  } catch {
    /* ignore */
  }
}

/** Fallback if user lands on /login?auth_done=1 (legacy). */
export async function finishMobileAuthReturn(
  returnTo = "/",
): Promise<boolean> {
  for (let i = 0; i < 8; i++) {
    await captureSessionBearer();
    try {
      const { data } = await authClient.getSession();
      if (data?.user || getBearerToken()) {
        const dest =
          returnTo.startsWith("/") && !returnTo.startsWith("//")
            ? returnTo
            : "/";
        window.location.replace(dest);
        return true;
      }
    } catch {
      /* retry */
    }
    await new Promise((r) => setTimeout(r, 350));
  }
  return false;
}

/** Listen for late auth handoffs (storage / BroadcastChannel) while on login. */
export function watchAuthHandoff(
  onToken: (token: string) => void,
): () => void {
  const onStorage = (event: StorageEvent) => {
    if (event.key === BEARER_KEY && event.newValue) onToken(event.newValue);
  };
  window.addEventListener("storage", onStorage);

  let bc: BroadcastChannel | null = null;
  try {
    bc = new BroadcastChannel("grok-auth");
    bc.onmessage = (event) => {
      const data = event.data as PopupMessage | undefined;
      if (data?.source === "grok-auth-popup" && data.token) onToken(data.token);
    };
  } catch {
    bc = null;
  }

  const onMessage = (event: MessageEvent) => {
    if (event.origin !== window.location.origin) return;
    const data = event.data as PopupMessage | undefined;
    if (data?.source === "grok-auth-popup" && data.token) onToken(data.token);
  };
  window.addEventListener("message", onMessage);

  return () => {
    window.removeEventListener("storage", onStorage);
    window.removeEventListener("message", onMessage);
    try {
      bc?.close();
    } catch {
      /* ignore */
    }
  };
}

export async function signOut(redirectTo = "/"): Promise<void> {
  try {
    await authClient.signOut();
  } finally {
    storeBearer(null);
  }
  window.location.href = redirectTo;
}

import type { ReactNode } from "react";
import { Navigate } from "@tanstack/react-router";
import { authEnabled, signOut } from "./client";
import { useCurrentUser, useCurrentUserState } from "./use-current-user";

/**
 * Auth state components — plain wrappers around `useCurrentUserState()`.
 *
 * Auth is ON by default (including the sandbox live preview, which does real
 * sign-in). Visitors are signed out until they authenticate. The shared dev
 * user only appears when auth is explicitly disabled (`VITE_AUTH_ENABLED=false`).
 * While the session is still resolving, gates that care about signed-out state
 * render nothing so there's no signed-out flash on hard reload.
 */

/** Where `RedirectToSignIn` sends signed-out visitors. Create this route. */
export const SIGN_IN_PATH = "/login";

/** Render children only when a user is present (real session, or the disabled-auth dev user). */
export function SignedIn({ children }: { children: ReactNode }) {
  const { user } = useCurrentUserState();
  return user ? <>{children}</> : null;
}

/**
 * Render children only once we KNOW the visitor is signed out (`isPending` has
 * cleared and there is no user). Hidden while the session is still loading.
 */
export function SignedOut({ children }: { children: ReactNode }) {
  const { user, isPending } = useCurrentUserState();
  if (isPending || user) return null;
  return <>{children}</>;
}

/**
 * Client-side redirect to the sign-in route (TanStack `<Navigate>` — NOT a full
 * `window.location` reload). A hard navigation re-bootstraps the SPA and re-runs
 * session loading, which feels like a second "Loading…" on /login.
 *
 * Guard routes by waiting out `isPending` first (see `use-current-user`), then
 * render this.
 */
export function RedirectToSignIn({ to = SIGN_IN_PATH }: { to?: string }) {
  return <Navigate to={to} />;
}

/**
 * Minimal signed-in identity chip + sign-out. Restyle freely (see the
 * `design-ui` skill). Sign-out is only shown when auth is enabled (the
 * disabled-auth dev user has nothing to sign out of).
 */
export function UserButton() {
  const user = useCurrentUser();
  if (!user) return null;
  const label = user.displayName ?? user.primaryEmail ?? "Account";
  return (
    <div className="flex items-center gap-2">
      {user.profileImageUrl ? (
        <img
          src={user.profileImageUrl}
          alt=""
          className="h-8 w-8 rounded-full object-cover"
        />
      ) : (
        <span className="grid h-8 w-8 place-items-center rounded-full bg-black/10 text-sm font-medium dark:bg-white/20">
          {label.charAt(0).toUpperCase()}
        </span>
      )}
      <span className="text-sm font-medium">{label}</span>
      {authEnabled && (
        <button
          type="button"
          onClick={() => void signOut()}
          className="cursor-pointer text-sm underline-offset-4 opacity-70 hover:underline"
        >
          Sign out
        </button>
      )}
    </div>
  );
}

/**
 * Cross-browser OAuth handoff (X/Twitter in-app browser → Brave/Chrome).
 * Stores a short code + session token for a few minutes on globalThis.
 */
import { randomInt } from "node:crypto";

export type HandoffEntry = {
  token: string;
  userLabel: string;
  createdAt: number;
  expiresAt: number;
};

const g = globalThis as typeof globalThis & {
  __grokAuthHandoff__?: Map<string, HandoffEntry>;
};

function store(): Map<string, HandoffEntry> {
  g.__grokAuthHandoff__ ??= new Map();
  return g.__grokAuthHandoff__;
}

function purge(): void {
  const now = Date.now();
  for (const [k, v] of store()) {
    if (v.expiresAt <= now) store().delete(k);
  }
}

/** Create a 6-digit code bound to a session token. Valid 10 minutes. */
export function createHandoff(
  token: string,
  userLabel = "",
): { code: string; expiresAt: number } {
  purge();
  let code = "";
  for (let i = 0; i < 12; i++) {
    code = String(randomInt(100000, 999999));
    if (!store().has(code)) break;
  }
  const expiresAt = Date.now() + 10 * 60_000;
  store().set(code, {
    token,
    userLabel: userLabel.slice(0, 80),
    createdAt: Date.now(),
    expiresAt,
  });
  return { code, expiresAt };
}

/** One-time claim. Returns token or null. */
export function claimHandoff(code: string): HandoffEntry | null {
  purge();
  const clean = code.replace(/\D/g, "").slice(0, 6);
  if (clean.length !== 6) return null;
  const entry = store().get(clean);
  if (!entry) return null;
  if (entry.expiresAt <= Date.now()) {
    store().delete(clean);
    return null;
  }
  // One-time use
  store().delete(clean);
  return entry;
}

export function peekHandoff(code: string): boolean {
  purge();
  const clean = code.replace(/\D/g, "").slice(0, 6);
  const entry = store().get(clean);
  return Boolean(entry && entry.expiresAt > Date.now());
}

import { getRequest } from "@tanstack/react-start/server";

/**
 * Fetch-Metadata sibling isolation — **server-only** (`.server.ts` suffix).
 *
 * MUST keep the `.server` suffix: this file imports `@tanstack/react-start/server`
 * (`getRequest` → Node `AsyncLocalStorage`). If it is imported from a dual
 * client/server module under a non-`.server` name, Vite ships it to the browser
 * and the app dies with: `AsyncLocalStorage is not a constructor`.
 *
 * Apps deployed on `*.grok.me` are "same-site" to each other but MUTUALLY
 * UNTRUSTED, and a `SameSite=Lax` session cookie IS sent on same-site
 * subrequests — so without this, a malicious sibling could make a SCRIPTED
 * (fetch/XHR/form-POST) request to this app's server functions and ride this
 * app's session cookie.
 *
 * We allow only: same-origin requests (this app's own client), non-browser
 * requests (SSR / server-to-server, which send no `Sec-Fetch-Site`), and
 * top-level GET navigations (how the OAuth callback and normal page loads
 * arrive). Every cross-site / same-site *scripted* request is rejected.
 * Together with `__Host-` cookies and Better Auth's `trustedOrigins`, this
 * closes the sibling-tenant attack surface. Enforced at the `authMiddleware`
 * chokepoint (see `middleware.ts`).
 */
export class CrossSiteRequestError extends Error {
  readonly status = 403;
  constructor() {
    super("Forbidden: cross-site request blocked");
    this.name = "CrossSiteRequestError";
  }
}

/** Throw `CrossSiteRequestError` for a scripted cross-site/sibling request. */
export function assertSameSiteRequest(): void {
  const request = getRequest();
  if (!request) return; // no request context (e.g. build) — nothing to guard
  const h = request.headers;
  const site = h.get("sec-fetch-site");
  // Non-browser client (no header), the app's own origin, or a direct
  // (address-bar/bookmark) load are all fine.
  if (!site || site === "same-origin" || site === "none") return;
  // A top-level GET navigation (e.g. the broker's OAuth callback redirect) is
  // fine even when it's cross-site; scripted requests never set navigate mode.
  const dest = h.get("sec-fetch-dest");
  const isTopLevelGet =
    h.get("sec-fetch-mode") === "navigate" &&
    request.method === "GET" &&
    dest !== "object" &&
    dest !== "embed";
  if (isTopLevelGet) return;
  throw new CrossSiteRequestError();
}

import { createMiddleware } from "@tanstack/react-start";

/**
 * Auth middleware for server functions — verified user id (+ identity fields for god-mode).
 *
 * Live preview: session cookies are partitioned, so the client stores a bearer
 * token and we forward it both as `Authorization` (request header) and via
 * `sendContext` (legacy path). Prefer the header so Better Auth's bearer plugin
 * sees the same shape as `/api/auth/get-session`.
 */
export const authMiddleware = createMiddleware({ type: "function" })
  .client(async ({ next }) => {
    const { getBearerToken } = await import("./client");
    const token = getBearerToken() ?? undefined;
    return next({
      headers: token
        ? { Authorization: `Bearer ${token}` }
        : {},
      sendContext: { bearerToken: token },
    });
  })
  .server(async ({ next, context }) => {
    const { assertSameSiteRequest } = await import("./isolation.server");
    const { requireUser } = await import("./verify.server");
    const { getRequest } = await import("@tanstack/react-start/server");
    assertSameSiteRequest();

    // Prefer token from Authorization header (set by client middleware), then sendContext
    let bearer = context.bearerToken as string | undefined;
    try {
      const req = getRequest();
      const h = req?.headers.get("authorization") ?? req?.headers.get("Authorization");
      if (h?.toLowerCase().startsWith("bearer ")) {
        bearer = h.slice(7).trim() || bearer;
      }
    } catch {
      /* no request context */
    }

    const user = await requireUser(bearer);
    return next({
      context: {
        userId: user.id,
        userEmail: user.email,
        userName: user.name,
      },
    });
  });

import { createMiddleware } from "@tanstack/react-start";

/**
 * Optional auth: attaches user when present, never throws Unauthorized.
 * Used for analyze/scalper gates (guests still allowed with client quota).
 */
export const optionalAuthMiddleware = createMiddleware({ type: "function" })
  .client(async ({ next }) => {
    const { getBearerToken } = await import("./client");
    const token = getBearerToken() ?? undefined;
    return next({
      headers: token ? { Authorization: `Bearer ${token}` } : {},
      sendContext: { bearerToken: token },
    });
  })
  .server(async ({ next, context }) => {
    const { getSessionUser } = await import("./verify.server");
    let bearer = context.bearerToken as string | undefined;
    try {
      const { getRequest } = await import("@tanstack/react-start/server");
      const req = getRequest();
      const h =
        req?.headers.get("authorization") ?? req?.headers.get("Authorization");
      if (h?.toLowerCase().startsWith("bearer ")) {
        bearer = h.slice(7).trim() || bearer;
      }
    } catch {
      /* no request */
    }

    const user = await getSessionUser(bearer);
    return next({
      context: {
        userId: user?.id ?? null,
        userEmail: user?.email ?? null,
        userName: user?.name ?? null,
      },
    });
  });

/**
 * Kysely dialect for Better Auth over the app's embedded PGLite instance.
 * Lazy: resolves `getClient` on first connection so migrations can finish first.
 */
import type { PGlite } from "@electric-sql/pglite";
import {
  CompiledQuery,
  type DatabaseConnection,
  type DatabaseIntrospector,
  type Dialect,
  type Driver,
  type Kysely,
  PostgresAdapter,
  PostgresIntrospector,
  PostgresQueryCompiler,
  type QueryCompiler,
  type QueryResult,
  type TransactionSettings,
} from "kysely";

type Client = PGlite;

/** Factory used by `auth/server.ts`: `pgliteDialect(() => getPglite())`. */
export function pgliteDialect(
  getClient: () => Promise<Client> | Client,
): Dialect {
  return {
    createAdapter: () => new PostgresAdapter(),
    createDriver: () => new LazyPGliteDriver(getClient),
    createQueryCompiler: (): QueryCompiler => new PostgresQueryCompiler(),
    createIntrospector: (db: Kysely<unknown>): DatabaseIntrospector =>
      new PostgresIntrospector(db),
  };
}

class LazyPGliteDriver implements Driver {
  private client: Client | undefined;
  private connection: PGliteConnection | undefined;
  private queue: Array<(con: PGliteConnection) => void> = [];

  constructor(private readonly getClient: () => Promise<Client> | Client) {}

  async init(): Promise<void> {
    this.client = await this.getClient();
  }

  async acquireConnection(): Promise<DatabaseConnection> {
    if (this.client === undefined) {
      this.client = await this.getClient();
    }
    if (this.connection !== undefined) {
      return new Promise((resolve) => {
        this.queue.push(resolve);
      });
    }
    this.connection = new PGliteConnection(this.client);
    return this.connection;
  }

  async releaseConnection(connection: DatabaseConnection): Promise<void> {
    if (connection !== this.connection) {
      throw new Error("Invalid connection");
    }
    const next = this.queue.shift();
    if (next === undefined) {
      this.connection = undefined;
      return;
    }
    next(this.connection);
  }

  async beginTransaction(
    conn: DatabaseConnection,
    settings: TransactionSettings,
  ): Promise<void> {
    const c = conn as PGliteConnection;
    if (settings.isolationLevel) {
      await c.executeQuery(
        CompiledQuery.raw(
          `start transaction isolation level ${settings.isolationLevel}`,
        ),
      );
    } else {
      await c.executeQuery(CompiledQuery.raw("begin"));
    }
  }

  async commitTransaction(conn: DatabaseConnection): Promise<void> {
    await (conn as PGliteConnection).executeQuery(CompiledQuery.raw("commit"));
  }

  async rollbackTransaction(conn: DatabaseConnection): Promise<void> {
    await (conn as PGliteConnection).executeQuery(
      CompiledQuery.raw("rollback"),
    );
  }

  async destroy(): Promise<void> {
    // Do not close the client: it is the shared getPglite() singleton used by
    // app SQL (getSql). Only drop our local handle so auth teardown cannot
    // poison the rest of the process.
    this.client = undefined;
    this.connection = undefined;
    this.queue = [];
  }
}

class PGliteConnection implements DatabaseConnection {
  constructor(private readonly client: Client) {}

  async executeQuery<O>(compiledQuery: CompiledQuery): Promise<QueryResult<O>> {
    const result = await this.client.query(compiledQuery.sql, [
      ...compiledQuery.parameters,
    ]);
    if (result.affectedRows) {
      return {
        numAffectedRows: BigInt(result.affectedRows),
        rows: result.rows as O[],
      };
    }
    return { rows: result.rows as O[] };
  }

  async *streamQuery<O>(
    compiledQuery: CompiledQuery,
    chunkSize: number,
  ): AsyncIterableIterator<QueryResult<O>> {
    if (!Number.isInteger(chunkSize) || chunkSize <= 0) {
      throw new Error("chunkSize must be a positive integer");
    }
    const result = await this.client.query(compiledQuery.sql, [
      ...compiledQuery.parameters,
    ]);
    for (let i = 0; i < result.rows.length; i += chunkSize) {
      yield { rows: result.rows.slice(i, i + chunkSize) as O[] };
    }
  }
}

/**
 * Live-preview OAuth popup/page bridge (Vite authPopupPlugin only).
 * mode=popup → postMessage + close
 * mode=page  → store bearer + redirect (mobile / full page)
 */
import { auth, SESSION_TOKEN_COOKIE } from "./server";
import { PREVIEW_ALLOWED_HOSTS } from "./preview";

type PopupMessage = {
  source: "grok-auth-popup";
  token: string | null;
  error?: string;
};

function safeReturnTo(raw: string | null): string {
  if (!raw) return "/";
  if (raw.startsWith("/") && !raw.startsWith("//") && !raw.includes("://")) {
    return raw.slice(0, 512);
  }
  return "/";
}

function hostAllowed(hostname: string): boolean {
  const h = hostname.toLowerCase();
  if (
    h === "localhost" ||
    h === "127.0.0.1" ||
    h === "[::1]" ||
    h.endsWith(".localhost")
  ) {
    return true;
  }
  for (const pattern of PREVIEW_ALLOWED_HOSTS) {
    if (pattern.startsWith("*.")) {
      const suffix = pattern.slice(1);
      if (h.endsWith(suffix) || h === pattern.slice(2)) return true;
    } else if (h === pattern) {
      return true;
    }
  }
  if (h.endsWith(".grok.me") || h === "grok.me") return true;
  if (h.endsWith(".grok-sandbox.com")) return true;
  return false;
}

function isLoopback(hostname: string): boolean {
  const h = hostname.toLowerCase();
  return (
    h === "localhost" ||
    h === "127.0.0.1" ||
    h === "[::1]" ||
    h.endsWith(".localhost")
  );
}

function resolveAppOrigin(request: Request, url: URL): string {
  const raw = url.searchParams.get("appOrigin")?.trim();
  if (raw) {
    try {
      const o = new URL(raw);
      if (
        (o.protocol === "https:" || o.protocol === "http:") &&
        hostAllowed(o.hostname)
      ) {
        if (!isLoopback(o.hostname) && o.protocol !== "https:") {
          return `https://${o.host}`;
        }
        return o.origin;
      }
    } catch {
      /* fall through */
    }
  }

  const xfHost =
    request.headers.get("x-forwarded-host")?.split(",")[0]?.trim() ||
    request.headers.get("host")?.split(",")[0]?.trim();
  const xfProto =
    request.headers.get("x-forwarded-proto")?.split(",")[0]?.trim() ||
    url.protocol.replace(":", "");

  if (xfHost) {
    const hostOnly = xfHost.split(":")[0] ?? xfHost;
    if (hostAllowed(hostOnly)) {
      const proto = isLoopback(hostOnly) ? xfProto || "http" : "https";
      return `${proto}://${xfHost}`;
    }
  }
  return url.origin;
}

function fixAuthorizeRedirectUri(location: string, appOrigin: string): string {
  try {
    const loc = new URL(location);
    const ru = loc.searchParams.get("redirect_uri");
    if (!ru) return location;
    const ruUrl = new URL(ru);
    const app = new URL(appOrigin);
    if (isLoopback(ruUrl.hostname) && !isLoopback(app.hostname)) {
      loc.searchParams.set(
        "redirect_uri",
        `${appOrigin}${ruUrl.pathname}${ruUrl.search}`,
      );
      return loc.toString();
    }
    if (
      !isLoopback(app.hostname) &&
      hostAllowed(app.hostname) &&
      ruUrl.origin !== appOrigin
    ) {
      loc.searchParams.set(
        "redirect_uri",
        `${appOrigin}${ruUrl.pathname}${ruUrl.search}`,
      );
      return loc.toString();
    }
  } catch {
    /* leave */
  }
  return location;
}

function readCookie(request: Request, name: string): string | null {
  const header = request.headers.get("cookie");
  if (!header) return null;
  for (const part of header.split(";")) {
    const trimmed = part.trim();
    if (!trimmed) continue;
    const eq = trimmed.indexOf("=");
    if (eq <= 0) continue;
    if (trimmed.slice(0, eq) !== name) continue;
    const raw = trimmed.slice(eq + 1);
    try {
      return decodeURIComponent(raw);
    } catch {
      return raw;
    }
  }
  return null;
}

function readSessionToken(request: Request): string | null {
  for (const name of [
    SESSION_TOKEN_COOKIE,
    "__Host-grok-auth.session_token",
    "grok-auth.session_token",
    "__Secure-better-auth.session_token",
    "__Host-better-auth.session_token",
    "better-auth.session_token",
  ]) {
    const v = readCookie(request, name);
    if (v) return v;
  }
  return null;
}

export async function handleAuthPopupRequest(
  request: Request,
): Promise<Response> {
  // Auth uses memory adapter in preview — no PGLite warm-up.
  const url = new URL(request.url);
  const done = url.searchParams.get("done") === "1";
  const mode = url.searchParams.get("mode") === "page" ? "page" : "popup";
  const returnTo = safeReturnTo(url.searchParams.get("returnTo"));
  const appOrigin = resolveAppOrigin(request, url);

  if (done) {
    const errored = url.searchParams.has("error");
    let token: string | null = null;
    if (!errored) {
      token = readSessionToken(request);
      if (!token) {
        try {
          const session = await auth.api.getSession({
            headers: request.headers,
          });
          const s = session as { session?: { token?: string } } | null;
          if (s?.session?.token) token = s.session.token;
        } catch {
          /* ignore */
        }
      }
    }
    const message: PopupMessage = {
      source: "grok-auth-popup",
      token,
      ...(errored || !token
        ? {
            error: errored
              ? (url.searchParams.get("error") ?? "sign_in_failed")
              : "no_session",
          }
        : {}),
    };
    return new Response(completionHtml(message, mode, returnTo, appOrigin), {
      status: 200,
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store",
      },
    });
  }

  const providerId = url.searchParams.get("providerId")?.trim();
  if (!providerId) {
    return new Response("Missing providerId", {
      status: 400,
      headers: { "content-type": "text/plain; charset=utf-8" },
    });
  }

  const backParams = new URLSearchParams({
    done: "1",
    mode,
    appOrigin,
  });
  if (returnTo !== "/") backParams.set("returnTo", returnTo);
  const back = `${appOrigin}/auth/popup?${backParams.toString()}`;
  const errBack = `${back}&error=1`;

  const authHeaders = new Headers(request.headers);
  try {
    const originUrl = new URL(appOrigin);
    authHeaders.set("host", originUrl.host);
    authHeaders.set("x-forwarded-host", originUrl.host);
    authHeaders.set("x-forwarded-proto", originUrl.protocol.replace(":", ""));
    authHeaders.set("origin", appOrigin);
  } catch {
    /* keep */
  }

  try {
    const apiRes = await auth.api.signInWithOAuth2({
      body: {
        providerId,
        callbackURL: back,
        errorCallbackURL: errBack,
      },
      headers: authHeaders,
      asResponse: true,
    });

    if (!apiRes.ok) {
      const detail = await apiRes.text().catch(() => "");
      return failHtml(
        detail || `oauth_init_${apiRes.status}`,
        mode,
        returnTo,
        appOrigin,
      );
    }

    const body = (await apiRes.json().catch(() => null)) as {
      url?: string;
    } | null;
    let location = body?.url;
    if (!location) {
      return failHtml("oauth_init_missing_url", mode, returnTo, appOrigin);
    }

    location = fixAuthorizeRedirectUri(location, appOrigin);

    const headers = new Headers({ location, "cache-control": "no-store" });
    for (const cookie of apiRes.headers.getSetCookie()) {
      headers.append("set-cookie", cookie);
    }
    return new Response(null, { status: 302, headers });
  } catch (err) {
    const message = err instanceof Error ? err.message : "oauth_init_threw";
    return failHtml(message, mode, returnTo, appOrigin);
  }
}

function failHtml(
  error: string,
  mode: "popup" | "page",
  returnTo: string,
  appOrigin: string,
): Response {
  return new Response(
    completionHtml(
      { source: "grok-auth-popup", token: null, error },
      mode,
      returnTo,
      appOrigin,
    ),
    {
      status: 200,
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store",
      },
    },
  );
}

function completionHtml(
  message: PopupMessage,
  mode: "popup" | "page",
  returnTo: string,
  appOrigin: string,
): string {
  const payload = JSON.stringify(message).replace(/</g, "\\u003c");
  const safeReturn = JSON.stringify(returnTo);
  const safeOrigin = JSON.stringify(appOrigin);
  const pageMode = mode === "page";

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"/>
<title>Signing in…</title>
<style>
html,body{margin:0;min-height:100%;background:#0b0b0c;color:#a1a1aa;
font:15px/1.5 system-ui,sans-serif}
main{min-height:100dvh;display:grid;place-items:center;padding:1.5rem;text-align:center}
.err{color:#f87171;max-width:22rem;margin-top:.5rem;word-break:break-word}
a,button{color:#042f2e;background:#2dd4bf;border:0;border-radius:8px;
padding:12px 18px;font:600 14px/1.2 inherit;text-decoration:none;display:inline-block;margin-top:12px;cursor:pointer}
</style>
</head>
<body>
<main>
  <div>
    <p id="status">Signing you in…</p>
    <p id="hint" class="err" style="display:none"></p>
    <a id="btn" href="/" style="display:none">Continue</a>
  </div>
</main>
<script type="application/json" id="msg">${payload}</script>
<script>
(function () {
  var KEY = "grok-auth.bearer-token";
  var PAGE = ${pageMode ? "true" : "false"};
  var RETURN_TO = ${safeReturn};
  var APP_ORIGIN = ${safeOrigin};
  var el = document.getElementById("msg");
  var msg = { source: "grok-auth-popup", token: null };
  try { if (el && el.textContent) msg = JSON.parse(el.textContent); } catch (e) {}

  function stripSlash(s) {
    if (!s) return "";
    s = String(s);
    while (s.length && s.charAt(s.length - 1) === "/") s = s.slice(0, -1);
    return s;
  }
  function store(t) {
    if (!t) return;
    try { sessionStorage.setItem(KEY, t); } catch (e) {}
    try { localStorage.setItem(KEY, t); } catch (e) {}
  }
  function homePath() {
    if (typeof RETURN_TO === "string" && RETURN_TO.charAt(0) === "/" && RETURN_TO.charAt(1) !== "/") {
      return RETURN_TO;
    }
    return "/";
  }
  function homeUrl() {
    return stripSlash(APP_ORIGIN || window.location.origin) + homePath();
  }
  function loginUrl() {
    return stripSlash(APP_ORIGIN || window.location.origin) + "/login";
  }
  function showBtn(label, href) {
    var b = document.getElementById("btn");
    if (!b) return;
    b.style.display = "inline-block";
    b.textContent = label;
    b.setAttribute("href", href);
  }
  function goHome() {
    var dest = homeUrl();
    try { window.location.replace(dest); } catch (e) { window.location.href = dest; }
  }

  // Notify opener (desktop popup OR mobile tab with opener)
  if (window.opener) {
    try { window.opener.postMessage(msg, window.location.origin); } catch (e) {}
  }
  if (msg.token) store(msg.token);

  if (window.opener && !PAGE) {
    try { window.close(); } catch (e) {}
    setTimeout(function () {
      if (window.closed) return;
      if (msg.token) {
        document.getElementById("status").textContent = "Signed in — you can close this tab.";
        showBtn("Open app", homeUrl());
        goHome();
      } else {
        document.getElementById("status").textContent = "Sign-in did not complete";
        var h = document.getElementById("hint");
        h.style.display = "block";
        h.textContent = msg.error || "Try again";
        showBtn("Back to login", loginUrl());
      }
    }, 300);
    return;
  }

  // Full-page / mobile tab without relying on opener
  if (msg.token) {
    store(msg.token);
    document.getElementById("status").textContent = "Signed in — opening app…";
    showBtn("Open app", homeUrl());
    goHome();
    return;
  }

  document.getElementById("status").textContent = "Sign-in did not complete";
  var hint = document.getElementById("hint");
  hint.style.display = "block";
  hint.textContent = msg.error || "No session. Please try again.";
  showBtn("Back to login", loginUrl());
})();
</script>
</body>
</html>`;
}

import { useEffect, type ReactNode } from "react";
import { captureSessionBearer, getBearerToken } from "@/lib/auth/client";
import { authClient } from "@/lib/auth/client";

/**
 * App-wide client provider. Restores bearer session ASAP on reload so
 * Free/guest UI doesn't flash for signed-in users.
 */
export function AuthProvider({ children }: { children: ReactNode }) {
  useEffect(() => {
    if (!getBearerToken()) return;
    let cancelled = false;
    void (async () => {
      try {
        await captureSessionBearer();
        if (!cancelled) await authClient.getSession();
      } catch {
        /* ignore */
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  return <>{children}</>;
}

/**
 * Sign-in providers — display order is product order:
 * 1) X  2) Google  (email/password is separate, last on the login screen)
 */
export type GrokProvider = {
  providerId: string;
  idp: string;
  label: string;
};

/** Ordered: X first, then Google. */
export const GROK_PROVIDERS: readonly GrokProvider[] = [
  { providerId: "grok-x", idp: "twitter", label: "X" },
  { providerId: "grok-google", idp: "google", label: "Google" },
];

/**
 * Self-hosted Better Auth for THIS app (server-only).
 *
 * Preview (no DATABASE_URL): uses Better Auth **memory adapter** on globalThis.
 *   → Login never depends on PGLite (avoids ENOENT / database_warming loops on mobile).
 *   → Sessions survive Vite HMR within the same process (globalThis).
 * Deployed (DATABASE_URL): real Postgres pool.
 *
 * App data (alerts, etc.) still uses PGLite via `@/lib/db` separately.
 */
import { betterAuth } from "better-auth";
import { bearer, genericOAuth } from "better-auth/plugins";
import { tanstackStartCookies } from "better-auth/tanstack-start";
import { memoryAdapter, type MemoryDB } from "better-auth/adapters/memory";
import { getCookie } from "@tanstack/react-start/server";
import { randomBytes } from "node:crypto";
import { Pool } from "pg";
import { emailAndPasswordEnabled } from "./email-password";
import { GROK_PROVIDERS } from "./providers";
import {
  GROK_ISSUER_DEFAULT,
  PREVIEW_ALLOWED_HOSTS,
  PREVIEW_CLIENT_ID,
  PREVIEW_CLIENT_SECRET,
} from "./preview";

const globalAuthRef = globalThis as typeof globalThis & {
  __grokAuthPreviewSecret__?: string;
  /** Shared memory DB — survives HMR so OAuth mid-flow is not wiped. */
  __grokAuthMemoryDB__?: MemoryDB;
};

function previewAuthSecret(): string {
  globalAuthRef.__grokAuthPreviewSecret__ ??= randomBytes(32).toString("hex");
  return globalAuthRef.__grokAuthPreviewSecret__;
}

function previewMemoryDB(): MemoryDB {
  if (!globalAuthRef.__grokAuthMemoryDB__) {
    globalAuthRef.__grokAuthMemoryDB__ = {
      user: [],
      session: [],
      account: [],
      verification: [],
    };
  } else {
    const db = globalAuthRef.__grokAuthMemoryDB__;
    for (const k of ["user", "session", "account", "verification"] as const) {
      if (!Array.isArray(db[k])) db[k] = [];
    }
  }
  return globalAuthRef.__grokAuthMemoryDB__;
}

const env = (key: string): string | undefined => {
  const value = process.env[key]?.trim();
  return value ? value : undefined;
};

const authDisabled = env("VITE_AUTH_ENABLED") === "false";

const grokIssuer = env("GROK_AUTH_ISSUER") ?? GROK_ISSUER_DEFAULT;
const grokClientId = env("GROK_AUTH_CLIENT_ID") ?? PREVIEW_CLIENT_ID;
const grokClientSecret = env("GROK_AUTH_CLIENT_SECRET") ?? PREVIEW_CLIENT_SECRET;

export const authConfigured =
  !authDisabled && Boolean(grokClientId && grokClientSecret);

const explicitBaseURL = env("BETTER_AUTH_URL");
const previewAllowedHosts: string[] = [...PREVIEW_ALLOWED_HOSTS];
const LOCAL_DEV_ORIGINS: string[] = [
  "http://localhost:8080",
  "http://127.0.0.1:8080",
  "http://[::1]:8080",
];
const baseURL = explicitBaseURL ?? {
  allowedHosts: [...previewAllowedHosts, "localhost", "127.0.0.1", "[::1]"],
  protocol: "auto" as const,
  fallback: "http://localhost:8080",
};

const trustedOrigins: string[] = explicitBaseURL
  ? [explicitBaseURL, ...LOCAL_DEV_ORIGINS]
  : [
      ...previewAllowedHosts,
      ...previewAllowedHosts.flatMap((host) => [
        `https://${host}`,
        `http://${host}`,
      ]),
      ...LOCAL_DEV_ORIGINS,
    ];

const databaseUrl = env("DATABASE_URL");

const issuerBase = grokIssuer.replace(/\/+$/, "");
const grokAuthorizationUrl = `${issuerBase}/api/auth/oauth2/authorize`;
const grokTokenUrl = `${issuerBase}/api/auth/oauth2/token`;
const grokUserInfoUrl = `${issuerBase}/api/auth/oauth2/userinfo`;

/**
 * Deployed → Postgres.
 * Preview → in-memory adapter (NO PGLite). This is the fix for mobile login
 * loops on database_warming / pglite ENOENT.
 */
const database = databaseUrl
  ? new Pool({ connectionString: databaseUrl })
  : memoryAdapter(previewMemoryDB());

export const SESSION_TOKEN_COOKIE = "__Secure-grok-auth.session_token";
// Also used on some hosts:
// "__Host-grok-auth.session_token" | "grok-auth.session_token"

const grokOAuthPlugin = authConfigured
  ? genericOAuth({
      config: GROK_PROVIDERS.map(({ providerId, idp }) => ({
        providerId,
        clientId: grokClientId as string,
        clientSecret: grokClientSecret as string,
        authorizationUrl: grokAuthorizationUrl,
        tokenUrl: grokTokenUrl,
        userInfoUrl: grokUserInfoUrl,
        scopes: ["openid", "profile", "email"],
        authorizationUrlParams: { idp, prompt: "login" },
      })),
    })
  : null;

export const auth = betterAuth({
  baseURL,
  secret: env("BETTER_AUTH_SECRET") ?? previewAuthSecret(),
  database,
  trustedOrigins,

  account: {
    encryptOAuthTokens: true,
    accountLinking: {
      enabled: true,
      trustedProviders: GROK_PROVIDERS.map((p) => p.providerId),
      requireLocalEmailVerified: false,
    },
  },

  emailAndPassword: {
    enabled: emailAndPasswordEnabled,
  },

  session: {
    expiresIn: 60 * 60 * 24 * 30,
    updateAge: 60 * 60 * 24,
    cookieCache: {
      enabled: true,
      maxAge: 60 * 5,
    },
  },

  advanced: {
    useSecureCookies: true,
    // __Host- prefix in production/preview https; cookie name for popup reader
    cookiePrefix: "grok-auth",
  },

  plugins: [
    bearer(),
    ...(grokOAuthPlugin ? [grokOAuthPlugin] : []),
    tanstackStartCookies(),
  ],
});

export type Session = typeof auth.$Infer.Session;

/** Read session token from request cookies (popup / oauth done bridges). */
export function sessionTokenFromCookies(request: Request): string | null {
  const header = request.headers.get("cookie");
  if (!header) return null;
  const names = [
    SESSION_TOKEN_COOKIE,
    "__Host-grok-auth.session_token",
    "grok-auth.session_token",
    "__Secure-better-auth.session_token",
    "__Host-better-auth.session_token",
    "better-auth.session_token",
  ];
  for (const name of names) {
    for (const part of header.split(";")) {
      const trimmed = part.trim();
      const eq = trimmed.indexOf("=");
      if (eq <= 0) continue;
      if (trimmed.slice(0, eq) !== name) continue;
      const raw = trimmed.slice(eq + 1);
      try {
        return decodeURIComponent(raw);
      } catch {
        return raw;
      }
    }
  }
  // Fallback: tanstack cookie helper when available in handler context
  try {
    for (const name of names) {
      const v = getCookie(name);
      if (v) return v;
    }
  } catch {
    /* not in request context */
  }
  return null;
}

import { useEffect, useState } from "react";
import { authClient, authEnabled, getBearerToken } from "./client";

/** Normalized user shape used across the app, auth on or off. */
export type AppUser = {
  id: string;
  displayName: string | null;
  primaryEmail: string | null;
  profileImageUrl: string | null;
  /** True when this is the sandbox/dev fallback (auth not configured). */
  isDevFallback: boolean;
};

/**
 * Stable fallback user, used ONLY when auth is explicitly disabled
 * (`VITE_AUTH_ENABLED=false`).
 */
export const DEV_USER: AppUser = {
  id: "dev-user",
  displayName: "Dev User",
  primaryEmail: "dev@example.com",
  profileImageUrl: null,
  isDevFallback: true,
};

/** Cached user so reload doesn't flash "guest / Free" while session loads. */
const USER_CACHE_KEY = "pra-user-cache-v1";

export function readCachedUser(): AppUser | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = localStorage.getItem(USER_CACHE_KEY);
    if (!raw) return null;
    const j = JSON.parse(raw) as AppUser;
    if (j?.id && !j.isDevFallback) return j;
  } catch {
    /* ignore */
  }
  return null;
}

export function writeCachedUser(user: AppUser | null): void {
  if (typeof window === "undefined") return;
  try {
    if (!user || user.isDevFallback) localStorage.removeItem(USER_CACHE_KEY);
    else localStorage.setItem(USER_CACHE_KEY, JSON.stringify(user));
  } catch {
    /* ignore */
  }
}

export type CurrentUserState = {
  user: AppUser | null;
  isPending: boolean;
};

/**
 * Current user + loading state.
 * With bearer + cache → show instantly (no 4–10s Free flash).
 */
export function useCurrentUserState(): CurrentUserState {
  if (!authEnabled) return { user: DEV_USER, isPending: false };

  // eslint-disable-next-line react-hooks/rules-of-hooks -- authEnabled is constant
  const { data, isPending: sessionPending } = authClient.useSession();
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const [cache] = useState(() => readCachedUser());
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const [bootPending, setBootPending] = useState(() => {
    if (typeof window === "undefined") return true;
    // Instant if we already have cached user + token
    if (getBearerToken() && readCachedUser()) return false;
    return !!getBearerToken() || true; // short boot only
  });

  // eslint-disable-next-line react-hooks/rules-of-hooks
  useEffect(() => {
    // Cap pending at 1.2s — was 4s and felt like 5–10s login
    const t = window.setTimeout(() => setBootPending(false), 1200);
    return () => window.clearTimeout(t);
  }, []);

  const sessionUser = data?.user;
  const mapped: AppUser | null = sessionUser
    ? {
        id: sessionUser.id,
        displayName: sessionUser.name ?? null,
        primaryEmail: sessionUser.email ?? null,
        profileImageUrl: sessionUser.image ?? null,
        isDevFallback: false,
      }
    : null;

  // eslint-disable-next-line react-hooks/rules-of-hooks
  useEffect(() => {
    if (mapped) writeCachedUser(mapped);
  }, [mapped?.id, mapped?.displayName, mapped?.primaryEmail]);

  const hasBearer =
    typeof window !== "undefined" ? !!getBearerToken() : false;

  if (mapped) {
    return { user: mapped, isPending: false };
  }

  // Optimistic: bearer + cache → treat as signed in immediately
  if (hasBearer && cache) {
    return {
      user: cache,
      isPending: sessionPending && bootPending,
    };
  }

  if (sessionPending || (bootPending && hasBearer)) {
    return { user: cache, isPending: true };
  }

  if (!hasBearer && cache) {
    queueMicrotask(() => writeCachedUser(null));
  }

  return { user: null, isPending: false };
}

export function useCurrentUser(): AppUser | null {
  return useCurrentUserState().user;
}

import { getRequest } from "@tanstack/react-start/server";
import { auth, authConfigured } from "./server";

/**
 * Server-side session resolution (server-only).
 */

const databaseConfigured = Boolean(process.env.DATABASE_URL?.trim());

export { authConfigured };

if (databaseConfigured && !authConfigured) {
  console.error(
    "[auth] DATABASE_URL is set but auth is disabled (VITE_AUTH_ENABLED=false) " +
      "— requireUserId() will reject every request (fail closed) rather than " +
      "share one dev user on a real database.",
  );
}

export const DEV_USER_ID = "dev-user";

export class UnauthorizedError extends Error {
  readonly status = 401;
  constructor() {
    super("Unauthorized");
    this.name = "UnauthorizedError";
  }
}

export type VerifiedUser = {
  id: string;
  email: string | null;
  name: string | null;
};

/**
 * Resolve the signed-in user from the current request, or `null`.
 * Uses cookie session and/or Authorization: Bearer (live preview).
 */
export async function getSessionUser(
  bearerToken?: string,
): Promise<VerifiedUser | null> {
  if (!authConfigured) return null;
  const request = getRequest();
  if (!request) return null;

  let headers = new Headers(request.headers);

  // Explicit token wins; else keep any Authorization already on the request
  if (bearerToken?.trim()) {
    headers.set("Authorization", `Bearer ${bearerToken.trim()}`);
  }

  try {
    const session = await auth.api.getSession({ headers });
    if (!session?.user) return null;
    return {
      id: session.user.id,
      email: session.user.email ?? null,
      name: session.user.name ?? null,
    };
  } catch (e) {
    console.warn("[auth] getSession failed", e instanceof Error ? e.message : e);
    return null;
  }
}

export async function requireUserId(bearerToken?: string): Promise<string> {
  if (!authConfigured) {
    if (databaseConfigured) {
      throw new Error(
        "Auth is disabled (VITE_AUTH_ENABLED=false) but DATABASE_URL is set — " +
          "refusing to fall back to the shared dev user against a real database.",
      );
    }
    return DEV_USER_ID;
  }
  const user = await getSessionUser(bearerToken);
  if (!user) throw new UnauthorizedError();
  return user.id;
}

export async function requireUser(
  bearerToken?: string,
): Promise<VerifiedUser> {
  if (!authConfigured) {
    if (databaseConfigured) {
      throw new Error(
        "Auth is disabled (VITE_AUTH_ENABLED=false) but DATABASE_URL is set.",
      );
    }
    return { id: DEV_USER_ID, email: "dev@example.com", name: "Dev User" };
  }
  const user = await getSessionUser(bearerToken);
  if (!user) throw new UnauthorizedError();
  return user;
}

import type { Entitlements, PlanId, PlanStatus } from "@/lib/billing/plans";
import {
  FREE_ANALYSES_PER_DAY,
  FREE_MAX_ACTIVE_ALERTS,
  resolveEntitlements,
} from "@/lib/billing/plans";

/** Owner tokens — match name, email local-part, X handle, display name. */
const BUILTIN_GOD_TOKENS = [
  "realismomagico0",
  "realismo magico",
  "realismomagico",
  "magical realism",
  "magicalrealism",
  "realismomagico0",
  "realismo_magico",
  "realismo-magico",
  "dev-user",
  "dev@example.com",
];

function envTokens(): string[] {
  const raw =
    (typeof process !== "undefined" && process.env.GOD_MODE_ALLOW?.trim()) ||
    (typeof import.meta !== "undefined" &&
      (import.meta as { env?: { VITE_GOD_MODE_ALLOW?: string } }).env
        ?.VITE_GOD_MODE_ALLOW?.trim()) ||
    "";
  if (!raw) return [];
  return raw
    .split(/[,;]+/)
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

function normalize(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[@]/g, "")
    .replace(/[^a-z0-9._+\- ]+/g, "")
    .trim();
}

function compact(s: string): string {
  return normalize(s).replace(/[\s._+\-]+/g, "");
}

export function isGodUser(input: {
  id?: string | null;
  email?: string | null;
  name?: string | null;
  displayName?: string | null;
}): boolean {
  const raw = [
    input.id,
    input.email,
    input.name,
    input.displayName,
    input.email?.split("@")[0],
    // X sometimes puts handle in name as @user
    input.name?.replace(/^@/, ""),
    input.displayName?.replace(/^@/, ""),
  ].filter((x): x is string => !!x && x.trim().length > 0);

  if (raw.length === 0) return false;

  const candidates = new Set<string>();
  for (const r of raw) {
    candidates.add(normalize(r));
    candidates.add(compact(r));
  }

  const tokens = [...BUILTIN_GOD_TOKENS, ...envTokens()];
  for (const c of candidates) {
    if (!c) continue;
    for (const tok of tokens) {
      const nt = normalize(tok);
      const ct = compact(tok);
      if (!nt) continue;
      if (c === nt || c === ct) return true;
      if (c.includes(nt) || nt.includes(c)) return true;
      if (c.includes(ct) || ct.includes(c)) return true;
    }
  }
  return false;
}

