export const GOD_ENTITLEMENTS: Entitlements = {
  plan: "pro",
  status: "active",
  isPremium: true,
  canAnalyze: true,
  analysesLeftToday: null,
  canUseScalper: true,
  canUseEmailAlerts: true,
