/**
 * Lemon Squeezy API helpers (server-only).
 * Docs: https://docs.lemonsqueezy.com/api
 */

const API = "https://api.lemonsqueezy.com/v1";

function apiKey(): string {
  const k = process.env.LEMONSQUEEZY_API_KEY?.trim();
  if (!k) throw new Error("LEMONSQUEEZY_API_KEY not set");
  return k;
}

export function lemonConfigured(): boolean {
  return Boolean(process.env.LEMONSQUEEZY_API_KEY?.trim());
}

export function lemonStoreId(): string | null {
  return process.env.LEMONSQUEEZY_STORE_ID?.trim() || null;
}

export function lemonVariantId(): string | null {
  return process.env.LEMONSQUEEZY_VARIANT_ID?.trim() || null;
}

export function lemonStoreUrl(): string {
  const slug = process.env.LEMONSQUEEZY_STORE_SLUG?.trim() || "pricerevisitanalyzer";
  return (
    process.env.PRO_PAYMENT_URL?.trim() ||
    `https://${slug}.lemonsqueezy.com`
  );
}

async function lsFetch(path: string, init?: RequestInit): Promise<Response> {
  return fetch(`${API}${path}`, {
    ...init,
    headers: {
      Accept: "application/vnd.api+json",
      "Content-Type": "application/vnd.api+json",
      Authorization: `Bearer ${apiKey()}`,
      ...(init?.headers || {}),
    },
  });
}

export type LemonProductSummary = {
  id: string;
  name: string;
  status: string;
  price: number | null;
  buyUrl: string | null;
};

export async function listLemonProducts(): Promise<LemonProductSummary[]> {
  if (!lemonConfigured()) return [];
  const storeId = lemonStoreId();
  const q = storeId
    ? `?filter[store_id]=${encodeURIComponent(storeId)}`
    : "";
  const res = await lsFetch(`/products${q}`);
  if (!res.ok) {
    const t = await res.text();
    throw new Error(`Lemon products ${res.status}: ${t.slice(0, 200)}`);
  }
  const body = (await res.json()) as {
    data?: Array<{
      id: string;
      attributes: {
        name: string;
        status: string;
        price?: number;
        buy_now_url?: string;
      };
    }>;
  };
  return (body.data ?? []).map((p) => ({
    id: p.id,
    name: p.attributes.name,
    status: p.attributes.status,
    price: p.attributes.price ?? null,
    buyUrl: p.attributes.buy_now_url ?? null,
  }));
}

export async function listLemonVariants(productId?: string): Promise<
  Array<{ id: string; name: string; price: number; productId: string }>
> {
  if (!lemonConfigured()) return [];
  const q = productId
    ? `?filter[product_id]=${encodeURIComponent(productId)}`
    : "";
  const res = await lsFetch(`/variants${q}`);
  if (!res.ok) return [];
  const body = (await res.json()) as {
    data?: Array<{
      id: string;
      attributes: { name: string; price: number; product_id: number };
    }>;
  };
  return (body.data ?? []).map((v) => ({
    id: v.id,
    name: v.attributes.name,
    price: v.attributes.price,
    productId: String(v.attributes.product_id),
  }));
}

/**
 * Create a hosted checkout URL for Pro, tagged with our user id.
 */
export async function createLemonCheckout(opts: {
  userId: string;
  email?: string | null;
  redirectUrl?: string;
  variantId?: string;
}): Promise<{ url: string; id: string }> {
  const storeId = lemonStoreId();
  const variantId = opts.variantId || lemonVariantId();
  if (!storeId) throw new Error("LEMONSQUEEZY_STORE_ID not set");
  if (!variantId) {
    throw new Error(
      "LEMONSQUEEZY_VARIANT_ID not set — create a Pro product in Lemon Squeezy and paste the variant id",
    );
  }

  const res = await lsFetch("/checkouts", {
    method: "POST",
    body: JSON.stringify({
      data: {
        type: "checkouts",
        attributes: {
          checkout_data: {
            email: opts.email || undefined,
            custom: {
              user_id: opts.userId,
            },
          },
          product_options: {
            redirect_url: opts.redirectUrl || undefined,
            receipt_button_text: "Back to Analyzer",
            receipt_thank_you_note:
              "Pro will activate automatically. If not, open the app and refresh.",
          },
          checkout_options: {
            embed: false,
            media: true,
            logo: true,
          },
          test_mode: process.env.LEMONSQUEEZY_TEST_MODE !== "false",
        },
        relationships: {
          store: {
            data: { type: "stores", id: String(storeId) },
          },
          variant: {
            data: { type: "variants", id: String(variantId) },
          },
        },
      },
    }),
  });

  const raw = await res.text();
  if (!res.ok) {
    throw new Error(`Lemon checkout ${res.status}: ${raw.slice(0, 300)}`);
  }
  const body = JSON.parse(raw) as {
    data: { id: string; attributes: { url: string } };
  };
  return { url: body.data.attributes.url, id: body.data.id };
}

/** Verify Lemon Squeezy webhook signature (X-Signature = hex HMAC-SHA256). */
export async function verifyLemonSignature(
  rawBody: string,
  signature: string | null,
): Promise<boolean> {
  const secret = process.env.LEMONSQUEEZY_WEBHOOK_SECRET?.trim();
  if (!secret) {
    // No secret configured: accept only in demo (never in production)
    return process.env.PRO_ALLOW_DEMO === "true";
  }
  if (!signature) return false;
  try {
    const enc = new TextEncoder();
    const key = await crypto.subtle.importKey(
      "raw",
      enc.encode(secret),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"],
    );
    const sig = await crypto.subtle.sign("HMAC", key, enc.encode(rawBody));
    const hex = [...new Uint8Array(sig)]
      .map((b) => b.toString(16).padStart(2, "0"))
      .join("");
    return hex === signature.toLowerCase();
  } catch {
    return false;
  }
}

export function extractUserIdFromLemonPayload(payload: unknown): string | null {
  try {
    const p = payload as {
      meta?: { custom_data?: Record<string, string> };
      data?: {
        attributes?: {
          first_order_item?: { product_id?: number };
          user_email?: string;
          custom_data?: Record<string, string>;
        };
      };
    };
    const custom =
      p.meta?.custom_data ||
      p.data?.attributes?.custom_data ||
      {};
    const uid =
      custom.user_id ||
      custom.userId ||
      custom.userid ||
      null;
    return uid ? String(uid) : null;
  } catch {
    return null;
  }
}

/** Client REST helpers for plan / trial (mobile-safe). */
import { getBearerToken } from "@/lib/auth/client";
import type { Entitlements } from "@/lib/billing/plans";

function authHeaders(): HeadersInit {
  const h: Record<string, string> = {
    Accept: "application/json",
    "Content-Type": "application/json",
  };
  const t = getBearerToken();
  if (t) h.Authorization = `Bearer ${t}`;
  return h;
}

export type PlanApiResponse = {
  entitlements: Entitlements;
  isGod?: boolean;
  freeAnalysesPerDay?: number;
  trialDays?: number;
  proDays?: number;
};

export async function fetchMyPlan(): Promise<PlanApiResponse> {
  const res = await fetch("/api/user/plan", {
    method: "GET",
    credentials: "include",
    headers: authHeaders(),
  });
  if (res.status === 401) throw new Error("Unauthorized");
  if (!res.ok) {
    const t = await res.text().catch(() => "");
    throw new Error(t || `plan_failed_${res.status}`);
  }
  return (await res.json()) as PlanApiResponse;
}

export async function postPlanAction(
  action: "trial" | "consume",
): Promise<{
  ok: boolean;
  reason?: string;
  entitlements?: Entitlements;
  isGod?: boolean;
}> {
  const res = await fetch("/api/user/plan", {
    method: "POST",
    credentials: "include",
    headers: authHeaders(),
    body: JSON.stringify({ action }),
  });
  if (res.status === 401) throw new Error("Unauthorized");
  const data = (await res.json().catch(() => ({}))) as {
    ok?: boolean;
    reason?: string;
    entitlements?: Entitlements;
    isGod?: boolean;
    error?: string;
  };
  if (data.error && data.ok == null) {
    throw new Error(data.error);
  }
  return {
    ok: !!data.ok,
    reason: data.reason,
    entitlements: data.entitlements,
    isGod: data.isGod,
  };
}

/**
 * Server-side plan/trial/pro persistence (shared by REST + server fns).
 */
import { ensureDbReady, getSql, type Sql } from "@/lib/db";
import {
  FREE_ANALYSES_PER_DAY,
  PRO_DAYS,
  TRIAL_DAYS,
  resolveEntitlements,
  type Entitlements,
  type PlanId,
  type PlanStatus,
} from "@/lib/billing/plans";
import { GOD_ENTITLEMENTS, isGodUser } from "@/lib/billing/god-mode";

type SubRow = {
  user_id: string;
  plan: string;
  status: string;
  trial_started_at: number | string | null;
  trial_ends_at: number | string | null;
  pro_started_at: number | string | null;
  pro_ends_at: number | string | null;
  analyses_today: number | string | null;
  analyses_day: string | null;
};

function n(v: number | string | null | undefined): number | null {
  if (v == null) return null;
  const x = typeof v === "string" ? Number(v) : v;
  return Number.isFinite(x) ? x : null;
}

async function ensureBillingSchema(sql: Sql): Promise<void> {
  await sql.query(`
    create table if not exists user_subscriptions (
      user_id text primary key,
      plan text not null default 'free',
      status text not null default 'none',
      trial_started_at bigint,
      trial_ends_at bigint,
      pro_started_at bigint,
      pro_ends_at bigint,
      analyses_today int not null default 0,
      analyses_day text,
      updated_at timestamptz not null default now()
    )
  `);
}

async function readySql(): Promise<Sql> {
  await ensureDbReady({ retries: 3, delayMs: 150 });
  const sql = await getSql();
  await ensureBillingSchema(sql);
  return sql;
}

function rowToEntitlements(
  row: SubRow | undefined,
  now = Date.now(),
): Entitlements {
  if (!row) {
    return resolveEntitlements({
      plan: "free",
      status: "none",
      trialEndsAt: null,
      proEndsAt: null,
      analysesToday: 0,
      analysesDay: null,
      now,
    });
  }
  return resolveEntitlements({
    plan: row.plan,
    status: row.status,
    trialEndsAt: n(row.trial_ends_at),
    proEndsAt: n(row.pro_ends_at),
    analysesToday: n(row.analyses_today) ?? 0,
    analysesDay: row.analyses_day,
    now,
  });
}

async function loadRow(sql: Sql, userId: string): Promise<SubRow | undefined> {
  const rows = await sql<SubRow>`
    select * from user_subscriptions where user_id = ${userId} limit 1
  `;
  return rows[0];
}

async function upsertRow(
  sql: Sql,
  userId: string,
  patch: {
    plan: PlanId;
    status: PlanStatus;
    trialStartedAt: number | null;
    trialEndsAt: number | null;
    proStartedAt: number | null;
    proEndsAt: number | null;
    analysesToday?: number;
    analysesDay?: string | null;
  },
): Promise<void> {
  await sql`
    insert into user_subscriptions (
      user_id, plan, status,
      trial_started_at, trial_ends_at,
      pro_started_at, pro_ends_at,
      analyses_today, analyses_day, updated_at
    ) values (
      ${userId},
      ${patch.plan},
      ${patch.status},
      ${patch.trialStartedAt},
      ${patch.trialEndsAt},
      ${patch.proStartedAt},
      ${patch.proEndsAt},
      ${patch.analysesToday ?? 0},
      ${patch.analysesDay ?? null},
      now()
    )
    on conflict (user_id) do update set
      plan = excluded.plan,
      status = excluded.status,
      trial_started_at = excluded.trial_started_at,
      trial_ends_at = excluded.trial_ends_at,
      pro_started_at = excluded.pro_started_at,
      pro_ends_at = excluded.pro_ends_at,
      analyses_today = coalesce(excluded.analyses_today, user_subscriptions.analyses_today),
      analyses_day = coalesce(excluded.analyses_day, user_subscriptions.analyses_day),
      updated_at = now()
  `;
}

export type PlanUserCtx = {
  userId: string;
  email?: string | null;
  name?: string | null;
};

function isGod(ctx: PlanUserCtx): boolean {
  return isGodUser({
    id: ctx.userId,
    email: ctx.email,
    name: ctx.name,
  });
}

export type PlanResponse = {
  entitlements: Entitlements;
  isGod: boolean;
  trialDays: number;
  proDays: number;
  freeAnalysesPerDay: number;
};

/** First login auto-starts Trial (same as getMyPlan server fn). */
export async function getPlanForUser(ctx: PlanUserCtx): Promise<PlanResponse> {
  const sql = await readySql();
  const userId = ctx.userId;
  const now = Date.now();
  const god = isGod(ctx);
  let row = await loadRow(sql, userId);

  if (god) {
    await upsertRow(sql, userId, {
      plan: "pro",
      status: "active",
      trialStartedAt: n(row?.trial_started_at) ?? now,
      trialEndsAt: n(row?.trial_ends_at),
      proStartedAt: n(row?.pro_started_at) ?? now,
      proEndsAt: now + 3650 * 24 * 60 * 60_000,
      analysesToday: 0,
      analysesDay: null,
    });
    return {
      entitlements: { ...GOD_ENTITLEMENTS },
      isGod: true,
      trialDays: TRIAL_DAYS,
      proDays: PRO_DAYS,
      freeAnalysesPerDay: FREE_ANALYSES_PER_DAY,
    };
  }

  if (!row || row.status === "none") {
    const trialEnd = now + TRIAL_DAYS * 24 * 60 * 60_000;
    await upsertRow(sql, userId, {
      plan: "trial",
      status: "trialing",
      trialStartedAt: now,
      trialEndsAt: trialEnd,
      proStartedAt: null,
      proEndsAt: null,
      analysesToday: n(row?.analyses_today) ?? 0,
      analysesDay: row?.analyses_day ?? null,
    });
    row = await loadRow(sql, userId);
  } else {
    const ent = rowToEntitlements(row, now);
    if (
      (row.status === "trialing" || row.status === "active") &&
      ent.status === "expired"
    ) {
      await upsertRow(sql, userId, {
        plan: "free",
        status: "expired",
        trialStartedAt: n(row.trial_started_at),
        trialEndsAt: n(row.trial_ends_at),
        proStartedAt: n(row.pro_started_at),
        proEndsAt: n(row.pro_ends_at),
        analysesToday: n(row.analyses_today) ?? 0,
        analysesDay: row.analyses_day,
      });
      row = await loadRow(sql, userId);
    }
  }

  return {
    entitlements: rowToEntitlements(row, now),
    isGod: false,
    trialDays: TRIAL_DAYS,
    proDays: PRO_DAYS,
    freeAnalysesPerDay: FREE_ANALYSES_PER_DAY,
  };
}

export async function startTrialForUser(ctx: PlanUserCtx): Promise<{
  ok: boolean;
  reason?: string;
  entitlements: Entitlements;
  isGod?: boolean;
}> {
  if (isGod(ctx)) {
    return {
      ok: true,
      entitlements: { ...GOD_ENTITLEMENTS },
      isGod: true,
    };
  }
  const sql = await readySql();
  const userId = ctx.userId;
  const now = Date.now();
  const row = await loadRow(sql, userId);

  if (row?.status === "active") {
    return {
      ok: false,
      reason: "already_pro",
      entitlements: rowToEntitlements(row, now),
    };
  }
  if (row?.status === "trialing") {
    const ent = rowToEntitlements(row, now);
    if (ent.isPremium) {
      return { ok: false, reason: "already_trialing", entitlements: ent };
    }
  }
  if (row?.trial_started_at != null && row.status !== "none") {
    return {
      ok: false,
      reason: "trial_used",
      entitlements: rowToEntitlements(row, now),
    };
  }

  const trialEnd = now + TRIAL_DAYS * 24 * 60 * 60_000;
  await upsertRow(sql, userId, {
    plan: "trial",
    status: "trialing",
    trialStartedAt: now,
    trialEndsAt: trialEnd,
    proStartedAt: n(row?.pro_started_at),
    proEndsAt: n(row?.pro_ends_at),
    analysesToday: n(row?.analyses_today) ?? 0,
    analysesDay: row?.analyses_day ?? null,
  });
  const fresh = await loadRow(sql, userId);
  return { ok: true, entitlements: rowToEntitlements(fresh, now) };
}

export async function consumeAnalysisForUser(ctx: PlanUserCtx): Promise<{
  ok: boolean;
  reason?: string;
  entitlements: Entitlements;
  isGod?: boolean;
  consumed?: boolean;
}> {
  if (isGod(ctx)) {
    return {
      ok: true,
      entitlements: { ...GOD_ENTITLEMENTS },
      isGod: true,
      consumed: false,
    };
  }

  const sql = await readySql();
  const userId = ctx.userId;
  const now = Date.now();
  const today = new Date(now).toISOString().slice(0, 10);

  // Ensure trial row exists
  const plan = await getPlanForUser(ctx);
  if (plan.entitlements.isPremium) {
    return {
      ok: true,
      entitlements: plan.entitlements,
      consumed: false,
    };
  }

  let row = await loadRow(sql, userId);
  if (!row) {
    return {
      ok: false,
      reason: "no_row",
      entitlements: plan.entitlements,
    };
  }

  const day = row.analyses_day;
  let count = n(row.analyses_today) ?? 0;
  if (day !== today) count = 0;

  if (count >= FREE_ANALYSES_PER_DAY) {
    const ent = resolveEntitlements({
      plan: "free",
      status: row.status === "expired" ? "expired" : "none",
      trialEndsAt: n(row.trial_ends_at),
      proEndsAt: n(row.pro_ends_at),
      analysesToday: count,
      analysesDay: today,
      now,
    });
    return { ok: false, reason: "quota", entitlements: ent };
  }

  const next = count + 1;
  await upsertRow(sql, userId, {
    plan: (row.plan as PlanId) || "free",
    status: (row.status as PlanStatus) || "none",
    trialStartedAt: n(row.trial_started_at),
    trialEndsAt: n(row.trial_ends_at),
    proStartedAt: n(row.pro_started_at),
    proEndsAt: n(row.pro_ends_at),
    analysesToday: next,
    analysesDay: today,
  });
  const fresh = await loadRow(sql, userId);
  return {
    ok: true,
    entitlements: rowToEntitlements(fresh, now),
    consumed: true,
  };
}

export async function grantProForUser(
  userId: string,
  days = PRO_DAYS,
): Promise<Entitlements> {
  const sql = await readySql();
  const now = Date.now();
  const row = await loadRow(sql, userId);
  const proEnd = now + days * 24 * 60 * 60_000;
  await upsertRow(sql, userId, {
    plan: "pro",
    status: "active",
    trialStartedAt: n(row?.trial_started_at),
    trialEndsAt: n(row?.trial_ends_at),
    proStartedAt: now,
    proEndsAt: proEnd,
    analysesToday: n(row?.analyses_today) ?? 0,
    analysesDay: row?.analyses_day ?? null,
  });
  const fresh = await loadRow(sql, userId);
  return rowToEntitlements(fresh, now);
}

/** Commercial plans for Price Revisit Analyzer. */

export type PlanId = "free" | "trial" | "pro";

export type PlanStatus =
  | "none"
  | "trialing"
  | "active"
  | "expired"
  | "canceled";

export const TRIAL_DAYS = 7;
export const PRO_DAYS = 30;

export const FREE_ANALYSES_PER_DAY = 20;
export const FREE_MAX_ACTIVE_ALERTS = 5;
export const FREE_TOP_SCENARIOS = 2;
export const FREE_RECENT_REVISITS = 5;
export const FREE_HOT_LEVELS = 5;

export type Entitlements = {
  plan: PlanId;
  status: PlanStatus;
  isPremium: boolean;
  canAnalyze: boolean;
  analysesLeftToday: number | null;
  canUseScalper: boolean;
  canUseEmailAlerts: boolean;
  maxActiveAlerts: number | null;
  canCloudSync: boolean;
  maxTopScenarios: number;
  maxRecentRevisits: number;
  maxHotLevels: number;
  canUseBreakdown: boolean;
  canUseFullReport: boolean;
  canUseFullScenarios: boolean;
  /** Smart symbol search, categories, recents. */
  canUseProSearch: boolean;
  /** Extra windows/intervals, min-P% filter, multi-window tools. */
  canUseAdvancedParams: boolean;
  trialEndsAt: number | null;
  proEndsAt: number | null;
  trialDaysLeft: number | null;
  proDaysLeft: number | null;
};

export function daysLeft(
  endsAt: number | null | undefined,
  now = Date.now(),
): number | null {
  if (endsAt == null) return null;
  const ms = endsAt - now;
  if (ms <= 0) return 0;
  return Math.ceil(ms / (24 * 60 * 60_000));
}

function freeFeatures(freeLeft: number): Omit<
  Entitlements,
  | "plan"
  | "status"
  | "trialEndsAt"
  | "proEndsAt"
  | "trialDaysLeft"
  | "proDaysLeft"
> {
  return {
    isPremium: false,
    canAnalyze: freeLeft > 0,
    analysesLeftToday: freeLeft,
    canUseScalper: false,
    canUseEmailAlerts: false,
    maxActiveAlerts: FREE_MAX_ACTIVE_ALERTS,
    canCloudSync: true,
    maxTopScenarios: FREE_TOP_SCENARIOS,
    maxRecentRevisits: FREE_RECENT_REVISITS,
    maxHotLevels: FREE_HOT_LEVELS,
    canUseBreakdown: false,
    canUseFullReport: false,
    canUseFullScenarios: false,
    canUseProSearch: false,
    canUseAdvancedParams: false,
  };
}

function premiumFeatures(): Omit<
  Entitlements,
  | "plan"
  | "status"
  | "trialEndsAt"
  | "proEndsAt"
  | "trialDaysLeft"
  | "proDaysLeft"
> {
  return {
    isPremium: true,
    canAnalyze: true,
    analysesLeftToday: null,
    canUseScalper: true,
    canUseEmailAlerts: true,
    maxActiveAlerts: null,
    canCloudSync: true,
    maxTopScenarios: 5,
    maxRecentRevisits: 12,
    maxHotLevels: 12,
    canUseBreakdown: true,
    canUseFullReport: true,
    canUseFullScenarios: true,
    canUseProSearch: true,
    canUseAdvancedParams: true,
  };
}

export function resolveEntitlements(input: {
  plan: string;
  status: string;
  trialEndsAt: number | null;
  proEndsAt: number | null;
  analysesToday: number;
  analysesDay: string | null;
  now?: number;
}): Entitlements {
  const now = input.now ?? Date.now();
  const today = new Date(now).toISOString().slice(0, 10);
  const usedToday =
    input.analysesDay === today ? Math.max(0, input.analysesToday) : 0;

  let plan = (input.plan as PlanId) || "free";
  let status = (input.status as PlanStatus) || "none";

  if (
    status === "trialing" &&
    input.trialEndsAt != null &&
    input.trialEndsAt <= now
  ) {
    plan = "free";
    status = "expired";
  }
  if (
    status === "active" &&
    input.proEndsAt != null &&
    input.proEndsAt <= now
  ) {
    plan = "free";
    status = "expired";
  }
  if (status === "active" && (input.proEndsAt == null || input.proEndsAt > now)) {
    plan = "pro";
  }
  if (
    status === "trialing" &&
    input.trialEndsAt != null &&
    input.trialEndsAt > now
  ) {
    plan = "trial";
  }

  const isPremium = plan === "trial" || plan === "pro";
  const freeLeft = Math.max(0, FREE_ANALYSES_PER_DAY - usedToday);
  const base = isPremium ? premiumFeatures() : freeFeatures(freeLeft);

  return {
    plan,
    status,
    ...base,
    trialEndsAt: input.trialEndsAt,
    proEndsAt: input.proEndsAt,
    trialDaysLeft:
      status === "trialing" ? daysLeft(input.trialEndsAt, now) : null,
    proDaysLeft: status === "active" ? daysLeft(input.proEndsAt, now) : null,
  };
}

