function initialFromCache(): {
  ent: Entitlements;
  isGod: boolean;
  loading: boolean;
} {
  if (typeof window === "undefined") {
    return { ent: GUEST_ENTITLEMENTS, isGod: false, loading: true };
  }
  const hasBearer = !!getBearerToken();
  const cache = readPlanCache();
  if (hasBearer && cache) {
    return { ent: cache.entitlements, isGod: cache.isGod, loading: true };
  }
  if (hasBearer) {
    // Optimistic premium-safe: don't flash Free while session restores
    return { ent: GUEST_ENTITLEMENTS, isGod: false, loading: true };
  }
  return { ent: GUEST_ENTITLEMENTS, isGod: false, loading: true };
}

export function usePlan(): PlanState {
  const { user, isPending } = useCurrentUserState();
  const boot = useMemo(() => initialFromCache(), []);
  const [serverEntitlements, setServerEntitlements] = useState<Entitlements>(
    boot.ent,
  );
  const [serverIsGod, setServerIsGod] = useState(boot.isGod);
  const [loading, setLoading] = useState(boot.loading);
  const [freeAnalysesPerDay, setFree] = useState(FREE_ANALYSES_PER_DAY);
  const viewAs = useGodView((s) => s.viewAs);
  const setViewAs = useGodView((s) => s.setViewAs);

  const signedIn = !!user && !user.isDevFallback;
  const clientGodGuess = useMemo(
    () =>
      isGodUser({
        id: user?.id,
        email: user?.primaryEmail,
        name: user?.displayName,
        displayName: user?.displayName,
      }) || (!!user?.isDevFallback && user.id === "dev-user"),
    [user],
  );

  const isGod =
    serverIsGod || (signedIn && clientGodGuess) || !!user?.isDevFallback;

  const refresh = useCallback(async () => {
    if (!signedIn && !user?.isDevFallback) {
      // Keep cache while session still might restore (bearer present)
      if (getBearerToken()) {
        setLoading(true);
        return;
      }
      setServerEntitlements(GUEST_ENTITLEMENTS);
      setServerIsGod(false);
      setLoading(false);
      return;
    }
    if (user?.isDevFallback) {
      setServerEntitlements({ ...GOD_ENTITLEMENTS });
      setServerIsGod(true);
      writePlanCache(GOD_ENTITLEMENTS, true);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const res = await fetchMyPlan();
      const god = !!res.isGod || clientGodGuess;
      setServerIsGod(god);
      const next = god ? { ...GOD_ENTITLEMENTS } : res.entitlements;
      setServerEntitlements(next);
      writePlanCache(next, god);
      if (res.freeAnalysesPerDay) setFree(res.freeAnalysesPerDay);
    } catch (e) {
      console.warn("[usePlan] refresh failed", e);
      if (clientGodGuess) {
        setServerIsGod(true);
        setServerEntitlements({ ...GOD_ENTITLEMENTS });
        writePlanCache(GOD_ENTITLEMENTS, true);
      } else {
        // Keep last known premium cache — never demote on network blip
        const cache = readPlanCache();
        if (cache?.entitlements?.isPremium || cache?.isGod) {
          setServerEntitlements(cache.entitlements);
          setServerIsGod(!!cache.isGod);
        }
      }
    } finally {
      setLoading(false);
    }
  }, [signedIn, user?.isDevFallback, clientGodGuess]);

  useEffect(() => {
    if (isPending) {
      // Stay loading while auth restores — prevents Free flash
      setLoading(true);
      return;
    }
    void refresh();
  }, [isPending, refresh, user?.id]);

  useEffect(() => {
    if (clientGodGuess && signedIn) {
      setServerIsGod(true);
      setServerEntitlements((prev) =>
        prev.plan === "pro" && prev.isPremium ? prev : { ...GOD_ENTITLEMENTS },
      );
      writePlanCache(GOD_ENTITLEMENTS, true);
    }
  }, [clientGodGuess, signedIn, user?.id]);

  const entitlements = useMemo(
    () => applyViewAs(isGod, isGod ? viewAs : "pro", serverEntitlements),
    [isGod, viewAs, serverEntitlements],
  );

  const beginTrial = useCallback(async () => {
    if (!signedIn) return false;
    if (isGod) {
      setServerEntitlements({ ...GOD_ENTITLEMENTS });
      return true;
    }
    try {
      const res = await postPlanAction("trial");
      if (res.entitlements) {
        setServerEntitlements(res.entitlements);
        writePlanCache(res.entitlements, !!res.isGod);
      }
      if (res.isGod) {
        setServerIsGod(true);
        setServerEntitlements({ ...GOD_ENTITLEMENTS });
        writePlanCache(GOD_ENTITLEMENTS, true);
      }
      if (res.ok) return true;
      if (
        res.reason === "already_trialing" ||
        res.reason === "already_pro"
      ) {
        await refresh();
        return true;
      }
      return false;
    } catch {
      return false;
    }
  }, [signedIn, isGod, refresh]);

  const subscribePro = useCallback(
    async (opts?: { unlockCode?: string; paymentRef?: string }) => {
      if (!signedIn) return false;
      try {
        const res = (await activatePro({
          data: {
            confirm: true as const,
            unlockCode: opts?.unlockCode,
            paymentRef: opts?.paymentRef,
          },
        })) as {
          ok: boolean;
          entitlements?: Entitlements;
          isGod?: boolean;
        };
        if (res.isGod || clientGodGuess) {
          setServerIsGod(true);
          setServerEntitlements({ ...GOD_ENTITLEMENTS });
          writePlanCache(GOD_ENTITLEMENTS, true);
          return true;
        }
        if (res.entitlements) {
          setServerEntitlements(res.entitlements);
          writePlanCache(res.entitlements, false);
        }
        if (res.ok) return true;
        await refresh();
        return false;
      } catch {
        return false;
      }
    },
    [signedIn, refresh, clientGodGuess],
  );

  const tryConsumeAnalysis = useCallback(async (): Promise<ConsumeResult> => {
    if (isGod && viewAs !== "free") {
      return { ok: true, remaining: null };
    }
    if (serverEntitlements.isPremium && !(isGod && viewAs === "free")) {
      return { ok: true, remaining: null };
    }

    const consumeLocal = (storageKey: string, status: "none" | "expired") => {
      const today = new Date().toISOString().slice(0, 10);
      try {
        const raw = localStorage.getItem(storageKey);
        const parsed = raw
          ? (JSON.parse(raw) as { day: string; n: number })
          : null;
        const n0 = parsed?.day === today ? parsed.n : 0;
        if (n0 >= FREE_ANALYSES_PER_DAY) {
          return {
            ok: false as const,
            reason: "quota",
            remaining: 0,
            total: FREE_ANALYSES_PER_DAY,
          };
        }
        const next = n0 + 1;
        localStorage.setItem(
          storageKey,
          JSON.stringify({ day: today, n: next }),
        );
        const ent = resolveEntitlements({
          plan: "free",
          status,
          trialEndsAt: null,
          proEndsAt: null,
          analysesToday: next,
          analysesDay: today,
        });
        setServerEntitlements(ent);
        return {
          ok: true as const,
          remaining: ent.analysesLeftToday,
          total: FREE_ANALYSES_PER_DAY,
        };
      } catch {
        return { ok: true as const, remaining: null };
      }
    };

    if (isGod && viewAs === "free") {
      return consumeLocal("pra-god-preview-free-analyses", "expired");
    }

    if (!signedIn) {
      return consumeLocal("pra-guest-analyses", "none");
    }

    try {
      const res = await postPlanAction("consume");
      if (res.isGod) {
        setServerIsGod(true);
        setServerEntitlements({ ...GOD_ENTITLEMENTS });
        writePlanCache(GOD_ENTITLEMENTS, true);
        return { ok: true, remaining: null };
      }
      if (res.entitlements) {
        setServerEntitlements(res.entitlements);
        writePlanCache(res.entitlements, false);
      }
      return {
        ok: !!res.ok,
        reason: res.reason,
        remaining: res.entitlements?.analysesLeftToday ?? null,
        total: FREE_ANALYSES_PER_DAY,
      };
    } catch {
      if (serverEntitlements.isPremium) {
        return { ok: true, remaining: null };
      }
      return { ok: false as const, reason: "network", remaining: 0 };
    }
  }, [signedIn, isGod, viewAs, serverEntitlements.isPremium]);

  // While auth is pending, treat plan as loading so Free banner stays hidden
  const effectiveLoading = isPending || loading;

  return {
    entitlements,
    isGod,
    viewAs: isGod ? viewAs : "pro",
    setViewAs,
    loading: effectiveLoading,
    freeAnalysesPerDay,
    refresh,
    beginTrial,
    subscribePro,
    tryConsumeAnalysis,
  };
}

/**
 * Embedded PGLite for live preview auth + app data.
 *
 * Assets (data/wasm/initdb) always loaded from absolute node_modules paths —
 * never via import.meta.url (/var/task/_libs → ENOENT).
 *
 * Disk dataDir is used so OAuth state + sessions survive Vite HMR mid-login
 * (memory-only wiped the DB between /api/oauth/start and the broker callback).
 */
export type DbSource = "neon" | "pglite";

const rawDatabaseUrl =
  typeof process !== "undefined" ? process.env.DATABASE_URL : undefined;
const databaseUrl =
  rawDatabaseUrl && rawDatabaseUrl.trim() ? rawDatabaseUrl : undefined;

export const dbSource: DbSource = databaseUrl ? "neon" : "pglite";

export interface Sql {
  <T = Record<string, unknown>>(
    strings: TemplateStringsArray,
    ...values: unknown[]
  ): Promise<T[]>;
  query<T = Record<string, unknown>>(
    text: string,
    params?: unknown[],
  ): Promise<T[]>;
}

const globalRef = globalThis as typeof globalThis & {
  __pgSqlPromise__?: Promise<Sql>;
  __pgliteInstance__?: Promise<import("@electric-sql/pglite").PGlite>;
  __pgliteMigrateChain__?: Promise<void>;
  __pgliteOpenLock__?: Promise<void>;
  __pgliteAssets__?: {
    data: Uint8Array;
    wasm: WebAssembly.Module;
    initdb: WebAssembly.Module;
  };
  __pgliteAssetsPromise__?: Promise<{
    data: Uint8Array;
    wasm: WebAssembly.Module;
    initdb: WebAssembly.Module;
  }>;
  __pgReadyPromise__?: Promise<void>;
};

const OID_INT8 = 20;
const OID_DATE = 1082;
const OID_INTERVAL = 1186;
const identity = (v: string) => v;

const DIST = "/workspace/node_modules/@electric-sql/pglite/dist";
const DATA_DIR = "/workspace/.data/pglite";

type Run = <T>(text: string, params: unknown[]) => Promise<T[]>;

function toSql(run: Run): Sql {
  const sql = (async <T = Record<string, unknown>>(
    strings: TemplateStringsArray,
    ...values: unknown[]
  ): Promise<T[]> => {
    let text = strings[0];
    for (let i = 0; i < values.length; i += 1)
      text += `$${i + 1}${strings[i + 1]}`;
    return run<T>(text, values);
  }) as unknown as Sql;
  sql.query = <T = Record<string, unknown>>(
    text: string,
    params: unknown[] = [],
  ) => run<T>(text, params);
  return sql;
}

function createNeonSql(): Promise<Sql> {
  globalRef.__pgSqlPromise__ ??= (async () => {
    const { Pool, types } = await import("pg");
    types.setTypeParser(OID_INT8, Number);
    types.setTypeParser(OID_DATE, identity);
    types.setTypeParser(OID_INTERVAL, identity);
    const pool = new Pool({ connectionString: databaseUrl });
    return toSql(async <T>(text: string, params: unknown[]) => {
      const res = await pool.query(text, params);
      return res.rows as T[];
    });
  })().catch((err) => {
    globalRef.__pgSqlPromise__ = undefined;
    throw err;
  });
  return globalRef.__pgSqlPromise__;
}

function copyBytes(buf: Buffer): Uint8Array {
  const out = new Uint8Array(buf.byteLength);
  out.set(new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength));
  return out;
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

async function loadPgliteAssets(): Promise<{
  data: Uint8Array;
  wasm: WebAssembly.Module;
  initdb: WebAssembly.Module;
}> {
  if (globalRef.__pgliteAssets__) return globalRef.__pgliteAssets__;
  globalRef.__pgliteAssetsPromise__ ??= (async () => {
    const { readFileSync, existsSync } = await import("node:fs");
    const { join } = await import("node:path");
    const { createRequire } = await import("node:module");

    let dist = DIST;
    if (!existsSync(join(dist, "pglite.data"))) {
      try {
        const req = createRequire(
          "/workspace/node_modules/@electric-sql/pglite/package.json",
        );
        const entry = req.resolve("@electric-sql/pglite");
        dist = join(entry, "..");
      } catch {
        dist = join(process.cwd(), "node_modules/@electric-sql/pglite/dist");
      }
    }

    const dataPath = join(dist, "pglite.data");
    const wasmPath = join(dist, "pglite.wasm");
    const initdbPath = join(dist, "initdb.wasm");

    for (const p of [dataPath, wasmPath, initdbPath]) {
      if (!existsSync(p)) throw new Error(`PGLite asset missing: ${p}`);
    }

    const data = copyBytes(readFileSync(dataPath));
    const wasmBuf = readFileSync(wasmPath);
    const initdbBuf = readFileSync(initdbPath);
    const [wasm, initdb] = await Promise.all([
      WebAssembly.compile(wasmBuf),
      WebAssembly.compile(initdbBuf),
    ]);

    const assets = { data, wasm, initdb };
    globalRef.__pgliteAssets__ = assets;
    console.info(
      "[db] PGLite assets ready",
      "data",
      data.byteLength,
      "from",
      dist,
    );
    return assets;
  })().catch((err) => {
    globalRef.__pgliteAssetsPromise__ = undefined;
    throw err;
  });
  return globalRef.__pgliteAssetsPromise__;
}

async function ensureDataDir(): Promise<string | undefined> {
  if (process.env.PGLITE_MEMORY === "1") return undefined;
  try {
    const { mkdirSync, writeFileSync, unlinkSync } = await import("node:fs");
    const { join } = await import("node:path");
    mkdirSync(DATA_DIR, { recursive: true });
    const probe = join(DATA_DIR, ".write-probe");
    writeFileSync(probe, "ok");
    try {
      unlinkSync(probe);
    } catch {
      /* ignore */
    }
    return DATA_DIR;
  } catch (e) {
    console.warn("[db] disk dataDir unavailable, using memory", e);
    return undefined;
  }
}

async function openPgliteOnce(): Promise<
  import("@electric-sql/pglite").PGlite
> {
  const { PGlite } = await import("@electric-sql/pglite");
  const { Buffer } = await import("node:buffer");
  const assets = await loadPgliteAssets();
  const dataDir = await ensureDataDir();

  const parsers = {
    [OID_INT8]: Number,
    [OID_DATE]: identity,
    [OID_INTERVAL]: identity,
  };

  const fsBundle = new Blob([Buffer.from(assets.data)]);
  const baseOpts = {
    parsers,
    fsBundle,
    pgliteWasmModule: assets.wasm,
    initdbWasmModule: assets.initdb,
  };

  // Prefer durable disk (survives HMR mid-OAuth). Fall back to memory.
  const attempts: Array<{ label: string; opts: Record<string, unknown> }> = [];
  if (dataDir) {
    attempts.push({
      label: `disk+assets:${dataDir}`,
      opts: { ...baseOpts, dataDir },
    });
  }
  attempts.push({ label: "memory+assets", opts: { ...baseOpts } });

  let lastErr: unknown;
  for (const a of attempts) {
    try {
      const pg = new PGlite(
        a.opts as ConstructorParameters<typeof PGlite>[0],
      );
      await pg.waitReady;
      await pg.query("select 1::int as n");
      await pg.exec(`
        create table if not exists _migrations (
          name text primary key,
          applied_at timestamptz not null default now()
        );
      `);
      console.info("[db] PGLite ready:", a.label);
      return pg;
    } catch (err) {
      lastErr = err;
      console.warn(
        "[db] open failed:",
        a.label,
        err instanceof Error ? err.message : err,
      );
    }
  }
  throw lastErr instanceof Error
    ? lastErr
    : new Error("PGLite failed all open attempts");
}

async function openPglite(): Promise<import("@electric-sql/pglite").PGlite> {
  let release!: () => void;
  const prev = globalRef.__pgliteOpenLock__ ?? Promise.resolve();
  globalRef.__pgliteOpenLock__ = new Promise<void>((r) => {
    release = r;
  });
  await prev.catch(() => undefined);
  try {
    return await openPgliteOnce();
  } finally {
    release();
  }
}

async function createPgliteSql(): Promise<Sql> {
  // Single-flight open — never await __pgliteInstance__ inside openPglite
  // (self-await deadlock → permanent "database_warming").
  if (!globalRef.__pgliteInstance__) {
    globalRef.__pgliteInstance__ = openPglite().catch((err) => {
      globalRef.__pgliteInstance__ = undefined;
      throw err;
    });
  }
  const pg = await globalRef.__pgliteInstance__;

  const migrate = async (): Promise<void> => {
    // Ensure ledger exists (0001 also creates it, but we need it before reading)
    await pg.exec(`
      create table if not exists _migrations (
        name text primary key,
        applied_at timestamptz not null default now()
      );
    `);

    // Prefer fs over import.meta.glob — glob is not always available in SSR
    // workers / HMR and caused: "(intermediate value).glob is not a function"
    // which broke listMyAlerts / cloud alert sync entirely.
    const { readdirSync, readFileSync, existsSync } = await import("node:fs");
    const { join } = await import("node:path");
    const dirCandidates = [
      join(process.cwd(), "migrations"),
      "/workspace/migrations",
    ];
    let dir: string | null = null;
    for (const d of dirCandidates) {
      if (existsSync(d)) {
        dir = d;
        break;
      }
    }
    if (!dir) {
      console.warn("[db] no migrations directory found");
      return;
    }

    const files = readdirSync(dir)
      .filter((f) => f.endsWith(".sql"))
      .sort((a, b) => a.localeCompare(b));

    const doneRows = await pg.query<{ name: string }>(
      "select name from _migrations",
    );
    const done = new Set(doneRows.rows.map((r) => r.name));

    for (const name of files) {
      if (done.has(name)) continue;
      const text = readFileSync(join(dir, name), "utf8");
      try {
        await pg.transaction(async (tx) => {
          await tx.exec(text);
          await tx.query("insert into _migrations (name) values ($1)", [name]);
        });
        console.info("[db] migration applied:", name);
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        if (/already exists|duplicate/i.test(msg)) {
          await pg.query(
            "insert into _migrations (name) values ($1) on conflict do nothing",
            [name],
          );
          console.warn("[db] migration already applied:", name);
        } else {
          throw e;
        }
      }
    }
  };
  const pass = (globalRef.__pgliteMigrateChain__ ?? Promise.resolve())
    .catch(() => undefined)
    .then(migrate);
  globalRef.__pgliteMigrateChain__ = pass;
  await pass;

  return toSql(async <T>(text: string, params: unknown[]) => {
    const result = await pg.query<T>(text, params);
    return result.rows;
  });
}

let sqlPromise: Promise<Sql> | null = null;

async function createSql(): Promise<Sql> {
  if (typeof window !== "undefined") {
    throw new Error(
      "@/lib/db is server-only — call getSql() from a createServerFn handler " +
        "or a server route loader, never from client code.",
    );
  }
  return dbSource === "neon" ? createNeonSql() : createPgliteSql();
}

export function getSql(): Promise<Sql> {
  sqlPromise ??= createSql().catch((err) => {
    sqlPromise = null;
    throw err;
  });
  return sqlPromise;
}

export async function getPglite(): Promise<
  import("@electric-sql/pglite").PGlite
> {
  if (dbSource !== "pglite") {
    throw new Error(
      "getPglite() is only available on the PGLite fallback (no DATABASE_URL)",
    );
  }
  await ensureDbReady();
  const pg = await globalRef.__pgliteInstance__;
  if (!pg) throw new Error("PGLite instance failed to initialize");
  await pg.query("select 1");
  return pg;
}

export function resetDbForRetry(): void {
  globalRef.__pgSqlPromise__ = undefined;
  globalRef.__pgliteInstance__ = undefined;
  globalRef.__pgliteMigrateChain__ = undefined;
  globalRef.__pgReadyPromise__ = undefined;
  sqlPromise = null;
}

/**
 * Real multi-attempt warm-up. Resets poisoned singletons between tries.
 * Used by OAuth start/callback — not a cosmetic message.
 */
export async function ensureDbReady(opts?: {
  retries?: number;
  delayMs?: number;
}): Promise<void> {
  if (dbSource !== "pglite") return;

  const retries = opts?.retries ?? 5;
  const delayMs = opts?.delayMs ?? 250;

  // Coalesce concurrent waiters onto one warm promise, but only while healthy
  if (globalRef.__pgReadyPromise__) {
    try {
      await globalRef.__pgReadyPromise__;
      // live probe
      const pg = await globalRef.__pgliteInstance__;
      if (pg) {
        await pg.query("select 1");
        return;
      }
    } catch {
      resetDbForRetry();
    }
  }

  let lastErr: unknown;
  for (let attempt = 1; attempt <= retries; attempt++) {
    const run = (async () => {
      await loadPgliteAssets();
      await getSql();
      const pg = await globalRef.__pgliteInstance__;
      if (!pg) throw new Error("no pglite instance");
      await pg.query("select 1 as ok");
    })();
    globalRef.__pgReadyPromise__ = run;
    try {
      await run;
      if (attempt > 1) {
        console.info("[db] ensureDbReady recovered on attempt", attempt);
      }
      return;
    } catch (err) {
      lastErr = err;
      console.warn(
        `[db] ensureDbReady attempt ${attempt}/${retries} failed:`,
        err instanceof Error ? err.message : err,
      );
      resetDbForRetry();
      if (attempt < retries) await sleep(delayMs * attempt);
    }
  }
  throw lastErr instanceof Error
    ? lastErr
    : new Error("Database failed to start after retries");
}

export function isDbError(err: unknown): boolean {
  const msg = err instanceof Error ? err.message : String(err ?? "");
  return /enoent|pglite|no such file|database|ECONN|WASM|initdb/i.test(msg);
}

// Boot early so the first mobile OAuth request is warm
const globalBoot = globalThis as typeof globalThis & {
  __pgBootstrapPromise__?: Promise<void>;
};
if (typeof window === "undefined" && dbSource === "pglite") {
  globalBoot.__pgBootstrapPromise__ ??= ensureDbReady({ retries: 3 }).catch(
    (err) => {
      globalBoot.__pgBootstrapPromise__ = undefined;
      console.error("[db] PGLite bootstrap failed:", err);
    },
  );
}

import { create } from "zustand";
import { persist } from "zustand/middleware";

export type EmailAlertPrefs = {
  email: string;
  enabled: boolean;
  setEmail: (email: string) => void;
  setEnabled: (enabled: boolean) => void;
  subscribe: (email: string) => void;
  unsubscribe: () => void;
};

const emailOk = (e: string) =>
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e.trim()) && e.trim().length <= 120;

export function isValidAlertEmail(email: string): boolean {
  return emailOk(email);
}

/** Guest + client cache of email-alert subscription (synced to server when signed in). */
export const useEmailAlertPrefs = create<EmailAlertPrefs>()(
  persist(
    (set) => ({
      email: "",
      enabled: false,
      setEmail: (email) => set({ email: email.trim() }),
      setEnabled: (enabled) => set({ enabled }),
      subscribe: (email) => {
        const e = email.trim();
        if (!emailOk(e)) return;
        set({ email: e, enabled: true });
      },
      unsubscribe: () => set({ enabled: false }),
    }),
    { name: "pra-email-alerts-v1" },
  ),
);

/** Bump only when legal text changes in a material way (forces re-accept). */
export const TERMS_VERSION = "2026-07-30";
export const TERMS_STORAGE_KEY = "pra-terms-accepted-v1";
/** Lightweight cookie — survives reloads even when storage is flaky. */
export const TERMS_COOKIE = "pra_terms_ok";
/** Extra backup key (boolean flag). */
export const TERMS_FLAG_KEY = "pra_terms_ok_flag";

export type TermsAcceptance = {
  version: string;
  acceptedAt: number;
  lang: "en" | "es";
};

function readCookie(name: string): string | null {
  if (typeof document === "undefined") return null;
  try {
    const parts = document.cookie.split(";");
    for (const part of parts) {
      const t = part.trim();
      const eq = t.indexOf("=");
      if (eq <= 0) continue;
      if (t.slice(0, eq) === name) {
        return decodeURIComponent(t.slice(eq + 1));
      }
    }
  } catch {
    /* ignore */
  }
  return null;
}

function writeCookie(name: string, value: string, days = 400): void {
  if (typeof document === "undefined") return;
  try {
    const maxAge = days * 24 * 60 * 60;
    const secure =
      typeof location !== "undefined" && location.protocol === "https:"
        ? "; Secure"
        : "";
    // Lax is enough first-party; also write without Secure on http preview
    document.cookie = `${name}=${encodeURIComponent(value)}; Path=/; Max-Age=${maxAge}; SameSite=Lax${secure}`;
  } catch {
    /* ignore */
  }
}

function looksLikeAccepted(raw: string | null): boolean {
  if (!raw) return false;
  const t = raw.trim();
  if (!t) return false;
  // legacy: "1", "true", bare version string
  if (t === "1" || t === "true" || t === TERMS_VERSION) return true;
  try {
    const parsed = JSON.parse(t) as TermsAcceptance | boolean | string | number;
    if (parsed === true || parsed === 1 || parsed === "1") return true;
    if (typeof parsed === "string" && parsed === TERMS_VERSION) return true;
    if (parsed && typeof parsed === "object") {
      const v = (parsed as TermsAcceptance).version;
      if (!v) return true;
      if (v === TERMS_VERSION) return true;
      return true;
    }
  } catch {
    return t.length > 0;
  }
  return false;
}

/** True if this browser already accepted terms (any durable store). */
export function hasAcceptedTerms(): boolean {
  if (typeof window === "undefined") return false;

  try {
    if (readCookie(TERMS_COOKIE) === TERMS_VERSION) return true;
    if (readCookie(TERMS_FLAG_KEY) === "1") return true;
  } catch {
    /* ignore */
  }

  try {
    if (looksLikeAccepted(localStorage.getItem(TERMS_STORAGE_KEY))) {
      // heal cookie
      writeCookie(TERMS_COOKIE, TERMS_VERSION);
      writeCookie(TERMS_FLAG_KEY, "1");
      return true;
    }
    if (localStorage.getItem(TERMS_FLAG_KEY) === "1") {
      writeCookie(TERMS_COOKIE, TERMS_VERSION);
      return true;
    }
  } catch {
    /* ignore */
  }

  try {
    if (looksLikeAccepted(sessionStorage.getItem(TERMS_STORAGE_KEY))) {
      writeCookie(TERMS_COOKIE, TERMS_VERSION);
      return true;
    }
  } catch {
    /* ignore */
  }

  return false;
}

export function loadTermsAcceptance(): TermsAcceptance | null {
  if (!hasAcceptedTerms()) return null;
  try {
    const raw =
      localStorage.getItem(TERMS_STORAGE_KEY) ||
      sessionStorage.getItem(TERMS_STORAGE_KEY);
    if (raw) {
      try {
        const parsed = JSON.parse(raw) as TermsAcceptance;
        if (parsed && typeof parsed === "object" && parsed.acceptedAt) {
          return { ...parsed, version: TERMS_VERSION };
        }
      } catch {
        /* legacy */
      }
    }
  } catch {
    /* ignore */
  }
  return {
    version: TERMS_VERSION,
    acceptedAt: Date.now(),
    lang: "es",
  };
}

export function saveTermsAcceptance(lang: "en" | "es"): TermsAcceptance {
  const record: TermsAcceptance = {
    version: TERMS_VERSION,
    acceptedAt: Date.now(),
    lang,
  };
  const json = JSON.stringify(record);
  try {
    localStorage.setItem(TERMS_STORAGE_KEY, json);
    localStorage.setItem(TERMS_FLAG_KEY, "1");
  } catch {
    /* ignore */
  }
  try {
    sessionStorage.setItem(TERMS_STORAGE_KEY, json);
    sessionStorage.setItem(TERMS_FLAG_KEY, "1");
  } catch {
    /* ignore */
  }
  writeCookie(TERMS_COOKIE, TERMS_VERSION);
  writeCookie(TERMS_FLAG_KEY, "1");
  return record;
}

export function clearTermsAcceptance(): void {
  try {
    localStorage.removeItem(TERMS_STORAGE_KEY);
    localStorage.removeItem(TERMS_FLAG_KEY);
  } catch {
    /* ignore */
  }
  try {
    sessionStorage.removeItem(TERMS_STORAGE_KEY);
    sessionStorage.removeItem(TERMS_FLAG_KEY);
  } catch {
    /* ignore */
  }
  try {
    document.cookie = `${TERMS_COOKIE}=; Path=/; Max-Age=0; SameSite=Lax`;
    document.cookie = `${TERMS_FLAG_KEY}=; Path=/; Max-Age=0; SameSite=Lax`;
  } catch {
    /* ignore */
  }
}

