/** Rule of thumb thresholds shown in the tutorial. */
export const PROB_SOFT = 50;
export const PROB_STRONG = 60;

import { create } from "zustand";
import { persist } from "zustand/middleware";
import { pipSize } from "@/lib/analyzer/pips";

export type AbandonReason = "too_far" | "away_timeout" | "expired";

/** Alerts stay open while price drifts — only expire by calendar time. */
export const ALERT_TTL_DAYS = 7;
export const ALERT_MAX_AGE_MS = ALERT_TTL_DAYS * 24 * 60 * 60_000;
/** @deprecated kept for old history rows; distance-stop is disabled. */
export const ALERT_AWAY_TIMEOUT_MS = ALERT_MAX_AGE_MS;
/** @deprecated no short grace kill */
export const ALERT_ABANDON_GRACE_MS = 0;

export type PriceAlert = {
  id: string;
  symbol: string;
  yahooSymbol: string;
  targetPrice: number;
  tick: number;
  entryPrice: number;
  createdAt: number;
  active: boolean;
  hitAt?: number;
  hitPrice?: number;
  livePrice?: number;
  liveAt?: number;
  needsLeaveFirst?: boolean;
  hasLeftTarget?: boolean;
  awaySince?: number | null;
  abandonedAt?: number;
  abandonReason?: AbandonReason;
  armedProbability?: number;
  armedHistTouch?: number;
  armedRank?: number;
};

type LivePatch = Partial<Pick<PriceAlert, "hasLeftTarget" | "awaySince">>;

export function coerceArmedProbability(v: unknown): number | undefined {
  if (v == null || v === "") return undefined;
  const n = typeof v === "number" ? v : Number(v);
  if (!Number.isFinite(n)) return undefined;
  const pct = n > 0 && n <= 1 ? n * 100 : n;
  return Math.max(0, Math.min(100, pct));
}

export function coerceArmedRank(v: unknown): number | undefined {
  if (v == null || v === "") return undefined;
  const n = typeof v === "number" ? v : Number(v);
  if (!Number.isFinite(n) || n < 1) return undefined;
  return Math.round(n);
}

type AlertState = {
  alerts: PriceAlert[];
  addAlert: (
    input: Omit<
      PriceAlert,
      | "id"
      | "createdAt"
      | "active"
      | "hitAt"
      | "hitPrice"
      | "livePrice"
      | "liveAt"
      | "needsLeaveFirst"
      | "hasLeftTarget"
      | "awaySince"
      | "abandonedAt"
      | "abandonReason"
    >,
  ) => PriceAlert;
  removeAlert: (id: string) => void;
  deactivate: (id: string) => void;
  markHit: (id: string, hitAt: number, hitPrice: number) => void;
  markAbandoned: (
    id: string,
    at: number,
    reason: AbandonReason,
    livePrice?: number,
  ) => void;
  updateLive: (
    id: string,
    livePrice: number,
    liveAt: number,
    patch?: LivePatch,
  ) => void;
  replaceAll: (alerts: PriceAlert[]) => void;
  clearHitHistory: () => void;
  clearAll: () => void;
  getActiveForSymbol: (symbol: string) => PriceAlert[];
  isWatching: (symbol: string, targetPrice: number, tick: number) => boolean;
  findActive: (
    symbol: string,
    targetPrice: number,
    tick: number,
  ) => PriceAlert | undefined;
};

function alertKey(symbol: string, target: number, tick: number) {
  const decimals =
    tick >= 1 ? 0 : Math.min(8, Math.max(0, Math.ceil(-Math.log10(tick))));
  return `${symbol.toUpperCase()}:${target.toFixed(decimals)}`;
}

export function alertPipSize(yahooSymbol: string, tick: number): number {
  return pipSize(yahooSymbol, tick);
}

export function pipsSinceEntry(

  alert: PriceAlert,
  refPrice?: number,
): number | null {
  const ref = refPrice ?? alert.hitPrice ?? alert.livePrice;
  if (ref == null || !Number.isFinite(alert.entryPrice)) return null;
  const ps = pipSize(alert.yahooSymbol, alert.tick);
  if (!(ps > 0)) return null;
  return (ref - alert.entryPrice) / ps;
}

export function pipsToTarget(
  alert: PriceAlert,
  refPrice?: number,
): number | null {
  const ref =
    refPrice ?? alert.hitPrice ?? alert.livePrice ?? alert.entryPrice;
  if (!Number.isFinite(ref)) return null;
  const ps = pipSize(alert.yahooSymbol, alert.tick);
  if (!(ps > 0)) return null;
  return (alert.targetPrice - ref) / ps;
}

export function distToTargetPips(
  alert: PriceAlert,
  price: number,
): number | null {
  const ps = pipSize(alert.yahooSymbol, alert.tick);
  if (!(ps > 0) || !Number.isFinite(price)) return null;
  return Math.abs(alert.targetPrice - price) / ps;
}

export function formatSignedPips(pips: number | null, digits = 1): string {
  if (pips == null || !Number.isFinite(pips)) return "—";
  const d = Math.abs(pips) >= 100 ? 0 : digits;
  const v = pips.toFixed(d);
  if (pips > 0) return `+${v}`;
  return v;
}

export function onTargetTol(tick: number): number {
  return Math.max(tick * 0.5, Number.EPSILON);
}

export function isOnTarget(
  price: number,
  target: number,
  tick: number,
): boolean {
  return Math.abs(price - target) <= onTargetTol(tick);
}

export function evaluateAbandon(
  alert: PriceAlert,
  livePrice: number,
  now = Date.now(),
): {
  abandon: boolean;
  reason?: AbandonReason;
  awaySince: number | null;
} {
  if (!alert.active || alert.hitAt) {
    return { abandon: false, awaySince: alert.awaySince ?? null };
  }

  // Track "away" only for display / analytics — never stop because price drifted.
  // Revisits often happen after a deep excursion; killing on distance was wrong.
  const onSpot = isOnTarget(livePrice, alert.targetPrice, alert.tick);
  const awaySince = onSpot ? null : (alert.awaySince ?? now);

  // Sole auto-stop: full calendar TTL (default 7 days) without a hit
  const age = now - alert.createdAt;
  if (age >= ALERT_MAX_AGE_MS) {
    return {
      abandon: true,
      reason: "expired",
      awaySince,
    };
  }

  return { abandon: false, awaySince };
}

export function detectAlertHit(
  alert: PriceAlert,
  bars: { t: number; h: number; l: number; c: number }[],
  last: number,
  now = Date.now(),
): {
  hit: boolean;
  hitAt?: number;
  hitPrice?: number;
  leftTarget: boolean;
} {
  if (!alert.active || alert.hitAt) {
    return { hit: false, leftTarget: !!alert.hasLeftTarget };
  }
  const tol = onTargetTol(alert.tick);
  const target = alert.targetPrice;

  let left = alert.hasLeftTarget ?? !alert.needsLeaveFirst;
  if (alert.needsLeaveFirst && !left) {
    if (!isOnTarget(last, target, alert.tick)) left = true;
  }

  if (!left && alert.needsLeaveFirst) {
    for (const b of bars) {
      if (b.t < alert.createdAt) continue;
      if (b.l - tol > target || target > b.h + tol) {
        left = true;
        break;
      }
    }
    if (!left) return { hit: false, leftTarget: false };
  }

  for (const b of bars) {
    if (b.t < alert.createdAt) continue;
    if (b.l - tol <= target && target <= b.h + tol) {
      const hitPrice =
        Math.abs(b.c - target) <= tol
          ? b.c
          : Math.abs(b.h - target) < Math.abs(b.l - target)
            ? b.h
            : b.l;
      return {
        hit: true,
        hitAt: Math.max(b.t, alert.createdAt),
        hitPrice,
        leftTarget: true,
      };
    }
  }

  if (left && isOnTarget(last, target, alert.tick)) {
    return {
      hit: true,
      hitAt: now,
      hitPrice: last,
      leftTarget: true,
    };
  }
  return { hit: false, leftTarget: left };
}

export function fireBrowserNotification(title: string, body: string): void {
  try {
    if (typeof Notification === "undefined") return;
    if (Notification.permission === "granted") {
      new Notification(title, { body });
    }
  } catch {
    /* ignore */
  }
}

export async function requestAlertPermission(): Promise<boolean> {
  try {
    if (typeof Notification === "undefined") return false;
    if (Notification.permission === "granted") return true;
    if (Notification.permission === "denied") return false;
    const p = await Notification.requestPermission();
    return p === "granted";
  } catch {
    return false;
  }
}

export function normalizeAlert(raw: PriceAlert): PriceAlert {
  return {
    ...raw,
    symbol: String(raw.symbol || "").toUpperCase(),
    yahooSymbol: String(raw.yahooSymbol || raw.symbol || ""),
    targetPrice: Number(raw.targetPrice),
    tick: Number(raw.tick) || 0.0001,
    entryPrice: Number(raw.entryPrice),
    createdAt: Number(raw.createdAt) || Date.now(),
    active: !!raw.active,
    armedProbability: coerceArmedProbability(raw.armedProbability),
    armedHistTouch: coerceArmedProbability(raw.armedHistTouch),
    armedRank: coerceArmedRank(raw.armedRank),
  };
}

function newId(): string {
  return `a-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

export const usePriceAlerts = create<AlertState>()(
  persist(
    (set, get) => ({
      alerts: [],
      addAlert: (input) => {
        const onSpot = isOnTarget(
          input.entryPrice,
          input.targetPrice,
          input.tick,
        );
        const alert: PriceAlert = {
          ...input,
          id: newId(),
          createdAt: Date.now(),
          active: true,
          needsLeaveFirst: onSpot,
          hasLeftTarget: !onSpot,
          awaySince: onSpot ? null : Date.now(),
        };
        set((s) => ({
          alerts: [alert, ...s.alerts].slice(0, 120),
        }));
        return alert;
      },
      removeAlert: (id) =>
        set((s) => ({ alerts: s.alerts.filter((a) => a.id !== id) })),
      deactivate: (id) =>
        set((s) => ({
          alerts: s.alerts.map((a) =>
            a.id === id ? { ...a, active: false } : a,
          ),
        })),
      markHit: (id, hitAt, hitPrice) =>
        set((s) => ({
          alerts: s.alerts.map((a) =>
            a.id === id
              ? {
                  ...a,
                  active: false,
                  hitAt,
                  hitPrice,
                  livePrice: hitPrice,
                  liveAt: hitAt,
                }
              : a,
          ),
        })),
      markAbandoned: (id, at, reason, livePrice) =>
        set((s) => ({
          alerts: s.alerts.map((a) =>
            a.id === id
              ? {
                  ...a,
                  active: false,
                  abandonedAt: at,
                  abandonReason: reason,
                  livePrice: livePrice ?? a.livePrice,
                  liveAt: at,
                }
              : a,
          ),
        })),
      updateLive: (id, livePrice, liveAt, patch) =>
        set((s) => ({
          alerts: s.alerts.map((a) =>
            a.id === id ? { ...a, livePrice, liveAt, ...patch } : a,
          ),
        })),
      replaceAll: (alerts) =>
        set({ alerts: alerts.map(normalizeAlert).slice(0, 120) }),
      clearHitHistory: () =>
        set((s) => ({
          alerts: s.alerts.filter((a) => a.active || !a.hitAt),
        })),
      clearAll: () => set({ alerts: [] }),
      getActiveForSymbol: (symbol) =>
        get().alerts.filter(
          (a) => a.active && a.symbol.toUpperCase() === symbol.toUpperCase(),
        ),
      isWatching: (symbol, targetPrice, tick) =>
        !!get().findActive(symbol, targetPrice, tick),
      findActive: (symbol, targetPrice, tick) => {
        const k = alertKey(symbol, targetPrice, tick);
        return get().alerts.find(
          (a) =>
            a.active && alertKey(a.symbol, a.targetPrice, a.tick) === k,
        );
      },
    }),
    { name: "pra-price-alerts-v3" },
  ),
);

/**
 * Client REST helpers for cloud alerts (PC ↔ mobile).
 */
import { getBearerToken } from "@/lib/auth/client";
import type { PriceAlert } from "@/lib/price-alerts";

function authHeaders(): HeadersInit {
  const h: Record<string, string> = {
    Accept: "application/json",
    "Content-Type": "application/json",
  };
  let t = getBearerToken();
  if (t && t.includes(".") && t.split(".").length === 2) {
    const raw = t.split(".")[0];
    if (raw && raw.length >= 16) t = raw;
  }
  if (t) h.Authorization = `Bearer ${t}`;
  return h;
}

async function waitForToken(ms = 5000): Promise<string | null> {
  const start = Date.now();
  while (Date.now() - start < ms) {
    const t = getBearerToken();
    if (t) return t;
    await new Promise((r) => setTimeout(r, 100));
  }
  return getBearerToken();
}

export type AlertsFetchResult = {
  alerts: PriceAlert[];
  count: number;
  userId?: string;
  accountKey?: string;
  userLabel?: string;
};

export async function fetchMyAlertsDetailed(): Promise<AlertsFetchResult> {
  await waitForToken(4000);
  const res = await fetch("/api/user/alerts", {
    method: "GET",
    credentials: "include",
    headers: authHeaders(),
    cache: "no-store",
  });
  if (res.status === 401) throw new Error("Unauthorized");
  if (!res.ok) {
    const t = await res.text().catch(() => "");
    throw new Error(t || `list_failed_${res.status}`);
  }
  const data = (await res.json()) as {
    alerts?: PriceAlert[];
    count?: number;
    userId?: string;
    accountKey?: string;
    userLabel?: string;
  };
  const alerts = Array.isArray(data.alerts) ? data.alerts : [];
  return {
    alerts,
    count: data.count ?? alerts.length,
    userId: data.userId,
    accountKey: data.accountKey,
    userLabel: data.userLabel,
  };
}

export async function fetchMyAlerts(): Promise<PriceAlert[]> {
  const r = await fetchMyAlertsDetailed();
  return r.alerts;
}

export async function pushMyAlerts(
  alerts: PriceAlert[],
  allowEmpty = false,
): Promise<{
  ok: boolean;
  count: number;
  skippedEmpty?: boolean;
  accountKey?: string;
  userId?: string;
}> {
  await waitForToken(4000);
  const res = await fetch("/api/user/alerts", {
    method: "POST",
    credentials: "include",
    headers: authHeaders(),
    cache: "no-store",
    body: JSON.stringify({
      allowEmpty,
      alerts: alerts.map((a) => ({
        id: a.id,
        symbol: a.symbol,
        yahooSymbol: a.yahooSymbol,
        targetPrice: a.targetPrice,
        tick: a.tick,
        entryPrice: a.entryPrice,
        createdAt: a.createdAt,
        active: a.active,
        hitAt: a.hitAt ?? null,
        hitPrice: a.hitPrice ?? null,
        livePrice: a.livePrice ?? null,
        liveAt: a.liveAt ?? null,
        needsLeaveFirst: a.needsLeaveFirst ?? false,
        hasLeftTarget: a.hasLeftTarget ?? false,
        awaySince: a.awaySince ?? null,
        abandonedAt: a.abandonedAt ?? null,
        abandonReason: a.abandonReason ?? null,
        armedProbability: a.armedProbability ?? null,
        armedHistTouch: a.armedHistTouch ?? null,
        armedRank: a.armedRank ?? null,
      })),
    }),
  });
  if (res.status === 401) throw new Error("Unauthorized");
  if (!res.ok) {
    const t = await res.text().catch(() => "");
    throw new Error(t || `save_failed_${res.status}`);
  }
  return (await res.json()) as {
    ok: boolean;
    count: number;
    skippedEmpty?: boolean;
    accountKey?: string;
    userId?: string;
  };
}

/**
 * Disk-backed alert cloud for preview (and fallback if PGLite flakes).
 * Path: /workspace/.data/cloud-alerts/<accountKey>.json
 *
 * Why files: same server process + multi-device share one disk;
 * identity is email/name so different better-auth user_ids still meet.
 */
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import type { AlertDTO } from "@/lib/user-data/alerts-repo.server";

const DIR =
  (typeof process !== "undefined" && process.env.CLOUD_ALERTS_DIR?.trim()) ||
  "/workspace/.data/cloud-alerts";

function ensureDir() {
  try {
    mkdirSync(DIR, { recursive: true });
  } catch {
    /* ignore */
  }
}

function safeFileName(key: string): string {
  return key.replace(/[^a-zA-Z0-9@._+\-:]/g, "_").slice(0, 180);
}

function pathFor(key: string): string {
  return join(DIR, `${safeFileName(key)}.json`);
}

export type CloudBlob = {
  accountKey: string;
  userIds: string[];
  alerts: AlertDTO[];
  updatedAt: number;
};

export function readCloudBlob(accountKey: string): CloudBlob | null {
  ensureDir();
  const p = pathFor(accountKey);
  if (!existsSync(p)) return null;
  try {
    const raw = readFileSync(p, "utf8");
    const j = JSON.parse(raw) as CloudBlob;
    if (!j || !Array.isArray(j.alerts)) return null;
    return j;
  } catch {
    return null;
  }
}

export function writeCloudBlob(
  accountKey: string,
  alerts: AlertDTO[],
  userId: string,
  prev?: CloudBlob | null,
): CloudBlob {
  ensureDir();
  const userIds = new Set(prev?.userIds ?? []);
  userIds.add(userId);
  const blob: CloudBlob = {
    accountKey,
    userIds: [...userIds],
    alerts,
    updatedAt: Date.now(),
  };
  writeFileSync(pathFor(accountKey), JSON.stringify(blob), "utf8");
  // also mirror under each known user id for reverse lookup
  for (const uid of userIds) {
    if (`u:${uid}` === accountKey) continue;
    try {
      writeFileSync(
        pathFor(`u:${uid}`),
        JSON.stringify({ ...blob, accountKey: `u:${uid}` }),
        "utf8",
      );
    } catch {
      /* ignore */
    }
  }
  return blob;
}

/** Merge alerts from several identity keys (email + name + user id). */
export function loadMergedFromFiles(keys: string[]): AlertDTO[] {
  const byId = new Map<string, AlertDTO>();
  for (const k of keys) {
    const blob = readCloudBlob(k);
    if (!blob) continue;
    for (const a of blob.alerts) {
      const prev = byId.get(a.id);
      if (!prev) {
        byId.set(a.id, a);
        continue;
      }
      // prefer more recently hit / newer created
      const score = (x: AlertDTO) =>
        Math.max(x.hitAt ?? 0, x.liveAt ?? 0, x.createdAt ?? 0);
      byId.set(a.id, score(a) >= score(prev) ? a : prev);
    }
  }
  return [...byId.values()].sort(
    (a, b) => (b.hitAt ?? b.createdAt) - (a.hitAt ?? a.createdAt),
  );
}

/**
 * Alert persistence:
 *  - Production (DATABASE_URL / Neon): Postgres is primary by account_key
 *  - Preview (PGLite): dual write PGLite + disk file cloud
 *
 * SAVE always merges with existing cloud so one device never wipes another.
 */
import { dbSource, ensureDbReady, getSql, type Sql } from "@/lib/db";
import { ensureUserDataSchema } from "@/lib/user-data/server";
import {
