/**
 * Mobile-safe OAuth start — real TanStack API route (no SPA Not Found).
 * Auth uses in-memory adapter in preview → no PGLite / database_warming.
 */
import { createFileRoute } from "@tanstack/react-router";
import { auth } from "@/lib/auth/server";
import { PREVIEW_ALLOWED_HOSTS } from "@/lib/auth/preview";

function hostAllowed(hostname: string): boolean {
  const h = hostname.toLowerCase();
  if (
    h === "localhost" ||
    h === "127.0.0.1" ||
    h === "[::1]" ||
    h.endsWith(".localhost")
  ) {
    return true;
  }
  for (const pattern of PREVIEW_ALLOWED_HOSTS) {
    if (pattern.startsWith("*.")) {
      const suffix = pattern.slice(1);
      if (h.endsWith(suffix) || h === pattern.slice(2)) return true;
    } else if (h === pattern) {
      return true;
    }
  }
  if (h.endsWith(".grok.me") || h === "grok.me") return true;
  if (h.endsWith(".grok-sandbox.com")) return true;
  return false;
}

function isLoopback(hostname: string): boolean {
  const h = hostname.toLowerCase();
  return (
    h === "localhost" ||
    h === "127.0.0.1" ||
    h === "[::1]" ||
    h.endsWith(".localhost")
  );
}

function resolveAppOrigin(request: Request, url: URL): string {
  const raw = url.searchParams.get("appOrigin")?.trim();
  if (raw) {
    try {
      const o = new URL(raw);
      if (
        (o.protocol === "https:" || o.protocol === "http:") &&
        hostAllowed(o.hostname)
      ) {
        if (!isLoopback(o.hostname) && o.protocol !== "https:") {
          return `https://${o.host}`;
        }
        return o.origin;
      }
    } catch {
      /* fall through */
    }
  }
  const xfHost =
    request.headers.get("x-forwarded-host")?.split(",")[0]?.trim() ||
    request.headers.get("host")?.split(",")[0]?.trim();
  const xfProto =
    request.headers.get("x-forwarded-proto")?.split(",")[0]?.trim() ||
    url.protocol.replace(":", "");
  if (xfHost) {
    const hostOnly = xfHost.split(":")[0] ?? xfHost;
    if (hostAllowed(hostOnly)) {
      const proto = isLoopback(hostOnly) ? xfProto || "http" : "https";
      return `${proto}://${xfHost}`;
    }
  }
  return url.origin;
}

function fixRedirectUri(location: string, appOrigin: string): string {
  try {
    const loc = new URL(location);
    const ru = loc.searchParams.get("redirect_uri");
    if (!ru) return location;
    const ruUrl = new URL(ru);
    const app = new URL(appOrigin);
    if (
      (isLoopback(ruUrl.hostname) && !isLoopback(app.hostname)) ||
      (!isLoopback(app.hostname) &&
        hostAllowed(app.hostname) &&
        ruUrl.origin !== appOrigin)
    ) {
      loc.searchParams.set(
        "redirect_uri",
        `${appOrigin}${ruUrl.pathname}${ruUrl.search}`,
      );
      return loc.toString();
    }
  } catch {
    /* leave */
  }
  return location;
}

function safeReturnTo(raw: string | null): string {
  if (!raw) return "/";
  if (raw.startsWith("/") && !raw.startsWith("//") && !raw.includes("://")) {
    return raw.slice(0, 512);
  }
  return "/";
}

async function handleStart(request: Request): Promise<Response> {
  const url = new URL(request.url);
  const providerId = url.searchParams.get("providerId")?.trim();
  const appOrigin = resolveAppOrigin(request, url);
  const returnTo = safeReturnTo(url.searchParams.get("returnTo"));

  if (!providerId) {
    return new Response("Missing providerId", { status: 400 });
  }

  const done = new URL(`${appOrigin}/api/oauth/done`);
  if (returnTo !== "/") done.searchParams.set("returnTo", returnTo);
  const callbackURL = done.toString();
  const errorURL = `${appOrigin}/api/oauth/done?error=1`;

  const authHeaders = new Headers(request.headers);
  try {
    const o = new URL(appOrigin);
    authHeaders.set("host", o.host);
    authHeaders.set("x-forwarded-host", o.host);
    authHeaders.set("x-forwarded-proto", o.protocol.replace(":", ""));
    authHeaders.set("origin", appOrigin);
  } catch {
    /* keep */
  }

  try {
    const apiRes = await auth.api.signInWithOAuth2({
      body: {
        providerId,
        callbackURL,
        errorCallbackURL: errorURL,
      },
      headers: authHeaders,
      asResponse: true,
    });

    if (!apiRes.ok) {
      const t = await apiRes.text().catch(() => "");
      console.error("[oauth/start] oauth init not ok", apiRes.status, t.slice(0, 200));
      return Response.redirect(
        `${appOrigin}/login?auth_error=${encodeURIComponent((t || "oauth_init").slice(0, 100))}`,
        302,
      );
    }

    const body = (await apiRes.json().catch(() => null)) as {
      url?: string;
    } | null;
    let location = body?.url;
    if (!location) {
      return Response.redirect(
        `${appOrigin}/login?auth_error=missing_url`,
        302,
      );
    }

    location = fixRedirectUri(location, appOrigin);

    const headers = new Headers({
      location,
      "cache-control": "no-store",
    });
    for (const cookie of apiRes.headers.getSetCookie()) {
      headers.append("set-cookie", cookie);
    }
    return new Response(null, { status: 302, headers });
  } catch (err) {
    const raw = err instanceof Error ? err.message : "oauth_threw";
    console.error("[oauth/start] error", raw);
    // Never show database_warming — auth no longer uses PGLite
    return Response.redirect(
      `${appOrigin}/login?auth_error=${encodeURIComponent(raw.slice(0, 100))}`,
      302,
    );
  }
}

export const Route = createFileRoute("/api/oauth/start")({
  server: {
    handlers: {
      GET: ({ request }) => handleStart(request),
    },
  },
});

/**
 * REST alert sync — identity-stable cloud (email/name + user id).
 * GET  /api/user/alerts
 * POST /api/user/alerts
 */
import { createFileRoute } from "@tanstack/react-router";
import { auth } from "@/lib/auth/server";
import {
  alertsUsePostgresPrimary,
  listAlertsForAccount,
  saveAlertsForAccount,
  type AlertDTO,
} from "@/lib/user-data/alerts-repo.server";
import { accountCloudKey } from "@/lib/user-data/cloud-identity";

function bearerFrom(request: Request): string | null {
  const h =
    request.headers.get("authorization") ??
    request.headers.get("Authorization");
  if (h?.toLowerCase().startsWith("bearer ")) {
    let t = h.slice(7).trim();
    if (t.includes(".")) {
      const raw = t.split(".")[0];
      if (raw && raw.length >= 16) t = raw;
    }
    if (t) return t;
  }
  return null;
}

async function requireUser(request: Request): Promise<{
  id: string;
  email: string | null;
  name: string | null;
} | null> {
  const headers = new Headers(request.headers);
  const bearer = bearerFrom(request);
  if (bearer) headers.set("Authorization", `Bearer ${bearer}`);
  try {
    const session = await auth.api.getSession({ headers });
    if (!session?.user?.id) return null;
    return {
      id: session.user.id,
      email: session.user.email ?? null,
      name: session.user.name ?? null,
    };
  } catch {
    return null;
  }
}

function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
    },
  });
}

async function handleGet(request: Request): Promise<Response> {
  const user = await requireUser(request);
  if (!user) return json({ error: "Unauthorized" }, 401);
  try {
    const alerts = await listAlertsForAccount(user);
    return json({
      alerts,
      userId: user.id,
      accountKey: accountCloudKey(user),
      count: alerts.length,
      userLabel: user.name || user.email || user.id.slice(0, 8),
      backend: alertsUsePostgresPrimary() ? "postgres" : "pglite+files",
    });
  } catch (e) {
    console.error("[api/user/alerts GET]", e);
    return json(
      { error: e instanceof Error ? e.message : "list_failed" },
      500,
    );
  }
}

async function handlePost(request: Request): Promise<Response> {
  const user = await requireUser(request);
  if (!user) return json({ error: "Unauthorized" }, 401);
  let body: { alerts?: AlertDTO[]; allowEmpty?: boolean };
  try {
    body = (await request.json()) as {
      alerts?: AlertDTO[];
      allowEmpty?: boolean;
    };
  } catch {
    return json({ error: "invalid_json" }, 400);
  }
  const alerts = Array.isArray(body.alerts) ? body.alerts.slice(0, 120) : [];
  try {
    const result = await saveAlertsForAccount(
      user,
      alerts,
      Boolean(body.allowEmpty),
    );
    return json({
      ...result,
      userId: user.id,
      accountKey: result.accountKey,
    });
  } catch (e) {
    console.error("[api/user/alerts POST]", e);
    return json(
      { error: e instanceof Error ? e.message : "save_failed" },
      500,
    );
  }
}

export const Route = createFileRoute("/api/user/alerts")({
  server: {
    handlers: {
      GET: ({ request }) => handleGet(request),
      POST: ({ request }) => handlePost(request),
    },
  },
});

